def _indicator_icon_path(name: str, svg: str) -> str:
    """生成指示器小图标 SVG（写入临时目录，供 QSS image: 引用）。"""
    import tempfile
    path = Path(tempfile.gettempdir()) / f"novel_formatter_{name}.svg"
    try:
        path.write_text(svg, encoding="utf-8")
        return path.as_posix()
    except Exception:
        return ""


