        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        header = QWidget()
        header.setStyleSheet(f"background: {CARD};")
        hl = QVBoxLayout(header)
        hl.setContentsMargins(14, 10, 14, 8)
        hl.setSpacing(7)

