    def _set_advanced_actions_visible(self, visible: bool):
        self._advanced_actions_panel.setVisible(bool(visible))
        self._more_actions_btn.setText("收起操作 ▴" if visible else "更多操作 ▾")

    def _multi_review_controls_available(self) -> bool:
        """Return whether a real multi-model comparison is currently active."""
        return bool(
            self._mode == "multi"
            and self._comparison is not None
            and len(self._documents) >= 2
        )

    def _sync_review_mode_controls(self) -> bool:
        """Keep every load/restore path in sync with the visible view switch."""
        available = self._multi_review_controls_available()
        self._decision_mode_btn.setEnabled(available)
        self._full_mode_btn.setEnabled(available)
        self._full_text_compare_check.setEnabled(available)
        if not available:
            self._full_text_compare_check.blockSignals(True)
            self._full_text_compare_check.setChecked(False)
            self._full_text_compare_check.blockSignals(False)
        return available

    def _toggle_full_text_compare(self, checked: bool):
        """Expose the existing full/one-sentence presentation through one switch."""
        # Restored multi-model sessions previously left the visible switch
        # disabled even though the comparison had already been restored.  Heal
        # the control state first and never let a stale disabled flag make the
        # visible button appear inert.
        if not self._sync_review_mode_controls():
            return
        self._set_review_mode("full" if bool(checked) else "decision")

    def _set_review_mode(self, mode: str, _checked=False, *, force: bool = False):
        """Switch view organization only; OCR documents and decisions stay shared."""
        mode = str(mode or "decision")
        if mode not in {"decision", "full"}:
            return
        if not force and mode == self._review_mode:
            return
        self._review_mode = mode
        decision_mode = mode == "decision"
        self._decision_mode_btn.setChecked(decision_mode)
        self._full_mode_btn.setChecked(not decision_mode)
        self._full_text_compare_check.blockSignals(True)
        self._full_text_compare_check.setChecked(not decision_mode)
        self._full_text_compare_check.blockSignals(False)
        self._decision_queue_panel.setVisible(decision_mode)
        self._auto_advance_check.setVisible(decision_mode)
        self._review_only_check.setVisible(not decision_mode)
        if hasattr(self, "_main_splitter"):
            self._main_splitter.setSizes([250, 570] if decision_mode else [460, 360])

        self._single_card_check.blockSignals(True)
        self._single_card_check.setChecked(decision_mode)
        self._single_card_check.blockSignals(False)
        self._review_only_check.blockSignals(True)
        self._review_only_check.setChecked(decision_mode)
        self._review_only_check.blockSignals(False)
        self._set_single_card_mode(decision_mode)
        self._set_review_only(decision_mode)

        if decision_mode:
            self._result_title.setText("逐句裁决 · 当前候选")
            self._workspace_title.setText("OCR 对比 · 逐句裁决")
            self._refresh_decision_queue(force=True)
        else:
            self._result_title.setText("全文融合结果（可查看、重新选择与编辑）")
            self._workspace_title.setText("OCR 对比 · 全文对比")
        if self._comparison is not None and self._fusion_states:
            self._select_row(self._current_row())

    def _request_image_review(self):
        self.image_review_requested.emit(int(self._current_row()))

    @staticmethod
    def _queue_preview_text(state) -> str:
        candidates = list(getattr(state, "candidates", ()) or ())
        text = ""
        if candidates:
            preferred = getattr(state, "preferred_model_index", None)
            for candidate in candidates:
                if preferred is not None and preferred in tuple(getattr(candidate, "model_indices", ()) or ()):
                    text = str(getattr(candidate, "text", "") or "")
                    break
            if not text:
                text = str(getattr(candidates[0], "text", "") or "")
        text = " ".join(text.replace("\r", " ").replace("\n", " ").split())
        return text[:28] + ("…" if len(text) > 28 else "")

    def _refresh_decision_queue(self, *, force: bool = False):
        if not hasattr(self, "_decision_queue"):
            return
        unresolved_rows = tuple(
            index for index, state in enumerate(self._fusion_states) if state.unresolved
        )
        self._decision_queue_count.setText(str(len(unresolved_rows)))
        if force or unresolved_rows != self._decision_queue_signature:
            old_rows = self._decision_queue_signature
            remove_only = (
                not force
                and bool(old_rows)
                and set(unresolved_rows).issubset(set(old_rows))
            )
            self._syncing_decision_queue = True
            try:
                if remove_only:
                    allowed = set(unresolved_rows)
                    for item_index in range(self._decision_queue.count() - 1, -1, -1):
                        item = self._decision_queue.item(item_index)
                        if int(item.data(Qt.UserRole)) not in allowed:
                            self._decision_queue.takeItem(item_index)
                else:
                    self._decision_queue.clear()
                    for row_index in unresolved_rows:
                        state = self._fusion_states[row_index]
                        item = QListWidgetItem(
                            f"{row_index + 1:>4}  {self._queue_preview_text(state)}"
                        )
                        item.setData(Qt.UserRole, int(row_index))
                        item.setToolTip(f"第 {row_index + 1} 句 · 点击定位")
                        self._decision_queue.addItem(item)
            finally:
                self._syncing_decision_queue = False
            self._decision_queue_signature = unresolved_rows
        self._select_current_queue_item()

    def _select_current_queue_item(self):
        if not hasattr(self, "_decision_queue") or self._syncing_decision_queue:
            return
        current = int(self._current_row())
        self._syncing_decision_queue = True
        try:
            self._decision_queue.clearSelection()
            for index in range(self._decision_queue.count()):
                item = self._decision_queue.item(index)
                if int(item.data(Qt.UserRole)) == current:
                    self._decision_queue.setCurrentItem(item)
                    self._decision_queue.scrollToItem(item, QAbstractItemView.ScrollHint.PositionAtCenter)
                    break
        finally:
            self._syncing_decision_queue = False

    def _decision_queue_item_clicked(self, item):
        if self._syncing_decision_queue or item is None:
            return
        try:
            row_index = int(item.data(Qt.UserRole))
        except (TypeError, ValueError, OverflowError):
            return
        self._select_row(row_index)

    @staticmethod
    def _editor_lines(editor: QPlainTextEdit) -> list[str]:
        return editor.toPlainText().replace("\r\n", "\n").replace("\r", "\n").split("\n")

    @staticmethod
    def _line_text(editor: QPlainTextEdit, row: int) -> str:
        block = editor.document().findBlockByNumber(row)
        return block.text() if block.isValid() else ""

    @staticmethod
    def _split_source_lines(text: str) -> list[str]:
        return str(text or "").replace("\r\n", "\n").replace("\r", "\n").split("\n")

    def _invalidate_highlight_cache(self) -> None:
        self._highlight_source_revision += 1
        self._highlight_mask_cache.clear()
        self._last_highlight_signature = None

    def _set_full_source_texts(self, texts) -> None:
        values = [str(value or "") for value in (texts or [])]
        self._full_source_texts = values
        self._full_source_lines = [self._split_source_lines(value) for value in values]
        self._invalidate_highlight_cache()

    def _set_full_source_text(self, model_index: int, text: str) -> None:
        index = max(0, int(model_index))
        while len(self._full_source_texts) <= index:
            self._full_source_texts.append("")
            self._full_source_lines.append([""])
        value = str(text or "")
        if self._full_source_texts[index] == value:
            return
        self._full_source_texts[index] = value
        self._full_source_lines[index] = self._split_source_lines(value)
        self._invalidate_highlight_cache()

    def _sync_full_source_cache_from_editors(self) -> None:
        """Persist full editor text before entering the one-card preview mode."""
        if self._single_card_enabled or self._loading_text:
            return
        count = len(self._documents)
        self._set_full_source_texts([
            self._source_editors[index].toPlainText()
            for index in range(min(count, len(self._source_editors)))
        ])

    def _source_text(self, model_index: int) -> str:
        if 0 <= model_index < len(self._full_source_texts):
            return str(self._full_source_texts[model_index] or "")
        if 0 <= model_index < len(self._source_editors):
            return self._source_editors[model_index].toPlainText()
        return ""

    def _source_line_text(self, model_index: int, row: int) -> str:
        if 0 <= model_index < len(self._full_source_lines):
            lines = self._full_source_lines[model_index]
        else:
            lines = self._split_source_lines(self._source_text(model_index))
        return lines[row] if 0 <= row < len(lines) else ""

    def _source_line_count(self, model_index: int) -> int:
        if 0 <= model_index < len(self._full_source_lines):
            return len(self._full_source_lines[model_index])
        return len(self._split_source_lines(self._source_text(model_index)))

    def _set_source_labels_for_mode(self) -> None:
        for index in range(min(len(self._documents), len(self._source_labels))):
            label = self._labels[index] if index < len(self._labels) else f"模型{index + 1}"
            suffix = "（结构底稿）" if index == 0 else "（文字候选）"
            if self._single_card_enabled:
                suffix = "（当前句只读）"
            self._source_labels[index].setText(f"模型{index + 1} · {label} {suffix}")

    def _update_single_card_source_preview(self, row: int, *, force: bool = False) -> None:
        if not self._single_card_enabled or self._comparison is None:
            return
        row = max(0, min(int(row), max(0, len(self._comparison.rows) - 1)))
        if not force and getattr(self, "_single_card_preview_row", -1) == row:
            return
        self._single_card_preview_row = row
        self._loading_text = True
        try:
            for index, editor in enumerate(self._source_editors[:len(self._documents)]):
                editor.setUpdatesEnabled(False)
                try:
                    editor.setReadOnly(True)
                    editor.setPlainText(self._source_line_text(index, row))
                    editor.moveCursor(QTextCursor.Start)
                finally:
                    editor.setUpdatesEnabled(True)
        finally:
            self._loading_text = False
        self._set_source_labels_for_mode()

    def _restore_full_source_editors(self) -> None:
        self._single_card_preview_row = -1
        self._loading_text = True
        try:
            for index, editor in enumerate(self._source_editors[:len(self._documents)]):
                editor.setUpdatesEnabled(False)
                try:
                    editor.setReadOnly(False)
                    editor.setPlainText(self._source_text(index))
                    block = editor.document().findBlockByNumber(self._current_row())
                    if block.isValid():
                        editor.setTextCursor(QTextCursor(block))
                finally:
                    editor.setUpdatesEnabled(True)
        finally:
            self._loading_text = False
        self._set_source_labels_for_mode()

    @staticmethod
    def _single_document_preview_text(doc: UnifiedDocument) -> str:
        lines = []
        for block in doc.text_blocks():
            if isinstance(block.metadata, dict) and block.metadata.get("consumed"):
                continue
            lines.append(str(block.text or ""))
        return "\n".join(lines)

    def set_available_single_result(self, doc: UnifiedDocument | None, label: str = "") -> None:
        """Register a single OCR result without loading it into the workspace."""
        if doc is None:
            self._available_single_doc = None
            self._available_single_label = ""
            self._available_single_generation += 1
        elif doc is not self._available_single_doc:
            self._available_single_doc = doc
            self._available_single_label = str(label or getattr(doc.metadata, "source_engine", "") or "单模型 OCR")
            self._available_single_generation += 1
        else:
            self._available_single_label = str(label or self._available_single_label or "单模型 OCR")
        self._refresh_single_source_controls()

    def _refresh_single_source_controls(self) -> None:
        available = self._available_single_doc is not None
        same_loaded = (
            self._mode == "single"
            and self._loaded_single_generation == self._available_single_generation
            and (
                self._single_doc is self._available_single_doc
                or self._single_original_doc is self._available_single_doc
            )
        )
        if not available:
            self._single_source_state.setText("单 OCR：暂无可载入结果")
            self._load_single_from_ocr_btn.setText("＋ 从 OCR 识别载入")
            self._load_single_from_ocr_btn.setEnabled(False)
        elif same_loaded:
            self._single_source_state.setText(f"单 OCR：已载入 · {self._available_single_label}")
            self._load_single_from_ocr_btn.setText("✓ 已载入当前单OCR")
            self._load_single_from_ocr_btn.setEnabled(False)
        else:
            action = "↻ 更新为最新单OCR" if self._mode == "single" else "＋ 从 OCR 识别载入"
            if self._mode == "multi":
                action = "⇄ 切换到最近单OCR"
            self._single_source_state.setText(f"单 OCR：可载入 · {self._available_single_label}")
            self._load_single_from_ocr_btn.setText(action)
            self._load_single_from_ocr_btn.setEnabled(True)
        self._single_export_btn.setEnabled(self._mode == "single" and self._single_doc is not None)
        self._return_multi_btn.setVisible(
            self._mode == "single" and self._suspended_multi_state is not None
        )
        self._return_multi_btn.setEnabled(self._suspended_multi_state is not None)

    def _capture_multi_state(self) -> dict | None:
        if self._mode != "multi" or self._comparison is None or len(self._documents) < 2:
            return None
        return {
            "documents": list(self._documents),
            "labels": list(self._labels),
            "comparison": self._comparison,
            "primary_doc": self._primary_doc,
            "initial_payload": self._initial_payload,
            "ruby_overlay_doc": self._ruby_overlay_doc,
            "fusion_states": self._fusion_states,
            "image_review_overrides": copy.deepcopy(self._image_review_overrides),
            "canonical_source_decisions": copy.deepcopy(self._canonical_source_decisions),
            "source_correction_import_history": copy.deepcopy(self._source_correction_import_history),
            "source_correction_imported_package_ids": set(self._source_correction_imported_package_ids),
            "last_source_correction_report": copy.deepcopy(self._last_source_correction_report),
            "current_row_index": self._current_row_index,
            "source_texts": [
                self._source_text(index) for index in range(len(self._documents))
            ],
            "sources_dirty": self._sources_dirty,
        }

    def _restore_suspended_multi(self) -> None:
        state = self._suspended_multi_state
        if not isinstance(state, dict):
            return
        self.clear(preserve_available_single=True)
        self._mode = "multi"
        self._documents = list(state.get("documents") or [])
        self._labels = list(state.get("labels") or [])
        self._comparison = state.get("comparison")
        self._primary_doc = state.get("primary_doc")
        self._initial_payload = state.get("initial_payload")
        self._ruby_overlay_doc = state.get("ruby_overlay_doc")
        self._fusion_states = list(state.get("fusion_states") or [])
        self._image_review_overrides = copy.deepcopy(state.get("image_review_overrides") or {})
        self._canonical_source_decisions = copy.deepcopy(state.get("canonical_source_decisions") or {})
        self._source_correction_import_history = copy.deepcopy(state.get("source_correction_import_history") or [])
        self._source_correction_imported_package_ids = set(state.get("source_correction_imported_package_ids") or set())
        self._last_source_correction_report = copy.deepcopy(state.get("last_source_correction_report"))
        self._current_row_index = int(state.get("current_row_index", 0) or 0)
        self._sources_dirty = bool(state.get("sources_dirty", False))
        source_texts = list(state.get("source_texts") or [])
        restored_source_texts = [str(value or "") for value in source_texts[:len(self._documents)]]
        while len(restored_source_texts) < len(self._documents):
            restored_source_texts.append("")
        self._set_full_source_texts(restored_source_texts)
        self._loading_text = True
        try:
            for index in range(3):
                visible = index < len(self._documents)
                self._source_panels[index].setVisible(visible)
                self._source_editors[index].setReadOnly(self._single_card_enabled)
                self._choose_buttons[index].setVisible(visible)
                self._choose_buttons[index].setEnabled(visible)
                if visible:
                    label = self._labels[index] if index < len(self._labels) else f"模型{index + 1}"
                    self._choose_buttons[index].setText(f"模型{index + 1}")
                    self._choose_buttons[index].setToolTip(f"当前句采用模型{index+1} · {label}")
                    preview = (
                        self._source_line_text(index, self._current_row_index)
                        if self._single_card_enabled
                        else self._source_text(index)
                    )
                    self._source_editors[index].setPlainText(preview)
                else:
                    self._source_editors[index].clear()
        finally:
            self._loading_text = False
        self._set_source_labels_for_mode()
        self._workspace_title.setText("OCR 对比 · 逐句裁决")
        # clear() disables the switch.  A suspended multi-model session must
        # explicitly restore its review controls together with its documents.
        self._sync_review_mode_controls()
        self._image_review_mode_btn.setEnabled(True)
        summary = getattr(self._comparison, "summary", "多模型 OCR 对比")
        restored_ai = sum(
            1 for item in self._canonical_source_decisions.values()
            if str(item.get("status", "") or "") == "accepted"
        )
        self._summary.setText(
            f"已恢复多模型 OCR 对比：{' · '.join(self._labels)}。{summary}"
            f"切换前的人工选择、源文本和累计 AI 裁决均已保留（有效 AI {restored_ai} 条）。"
        )
        self._choose_label.setVisible(True)
        self._row_state.setVisible(True)
        self._result_panel.setVisible(True)
        self._result_title.setText("融合结果（真正一致与两模型共同候选均自动保留；真正分歧需裁决）")
        self._auto_btn.setEnabled(True)
        self._realign_btn.setEnabled(True)
        self._restore_btn.setEnabled(self._initial_payload is not None)
        self._unicode_normalize_btn.setEnabled(True)
        self._export_texts_btn.setEnabled(True)
        self._single_export_btn.setEnabled(False)
        self._export_ai_package_btn.setEnabled(True)
        self._export_source_correction_btn.setEnabled(True)
        self._import_source_correction_btn.setEnabled(True)
        self._export_fusion_skeleton_btn.setEnabled(True)
        self._export_ai_repair_epub_btn.setEnabled(True)
        self._import_ai_repair_result_btn.setEnabled(True)
        self._ai_adjudicate_btn.setEnabled(not self._ai_import_busy)
        self._import_ai_package_btn.setEnabled(True)
        self._apply_btn.setText("✓ 应用融合稿")
        self._apply_btn.setEnabled(True)
        self._suspended_multi_state = None
        self._render_fusion_window(self._current_row_index, force=True)
        self._update_unresolved_summary()
        self._refresh_source_highlights()
        if self._comparison is not None and self._comparison.rows:
            self._select_row(self._current_row_index)
        self._refresh_single_source_controls()

    def _load_available_single_result(self) -> None:
        doc = self._available_single_doc
        if doc is None:
            QMessageBox.warning(self, "没有可载入结果", "请先在 OCR 识别页完成一次单模型 OCR。")
            return
        if self._mode == "multi":
            answer = QMessageBox.question(
                self, "切换到单 OCR 结果",
                "当前正在显示多模型 OCR 对比。切换后会暂存当前文本、对齐和人工选择，"
                "可用“返回多模型对比”完整恢复。继续吗？",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
        self._load_single_result(doc, self._available_single_label, self._available_single_generation)

    def _load_single_result(
        self, doc: UnifiedDocument, label: str, generation: int | None = None
    ) -> None:
        available_doc = self._available_single_doc
        available_label = self._available_single_label
        available_generation = self._available_single_generation
        suspended = self._capture_multi_state() if self._mode == "multi" else self._suspended_multi_state
        self.clear(preserve_available_single=True)
        self._suspended_multi_state = suspended
        # clear() intentionally keeps the registered source; restore explicit
        # locals as a guard against future reset changes.
        self._available_single_doc = available_doc or doc
        self._available_single_label = available_label or str(label or "单模型 OCR")
        self._available_single_generation = available_generation
        self._mode = "single"
        self._single_doc = doc
        self._single_original_doc = doc
        self._primary_doc = doc
        self._documents = [doc]
        self._labels = [str(label or getattr(doc.metadata, "source_engine", "") or "单模型 OCR")]
        self._loaded_single_generation = (
            self._available_single_generation if generation is None else int(generation)
        )
        self._loading_text = True
        try:
            for index in range(3):
                visible = index == 0
                self._source_panels[index].setVisible(visible)
                self._choose_buttons[index].setVisible(False)
                self._choose_buttons[index].setEnabled(False)
                self._source_editors[index].setReadOnly(True)
                self._source_editors[index].setExtraSelections([])
                if visible:
                    self._source_labels[index].setText(
                        f"单 OCR · {self._labels[0]}（只读预览；修改请使用 AI 包或图文对照）"
                    )
                    self._source_editors[index].setPlainText(self._single_document_preview_text(doc))
                else:
                    self._source_editors[index].clear()
        finally:
            self._loading_text = False
        self._workspace_title.setText("OCR 对比 · 单结果校对")
        self._sync_review_mode_controls()
        self._image_review_mode_btn.setEnabled(True)
        self._summary.setText(
            f"已手动载入单 OCR：{self._labels[0]} · {len(doc.text_blocks())} 个正文块。"
            "该结果不会伪装成双模型比较；可在本页导出/导入单 OCR AI 包。"
        )
        self._choose_label.setVisible(False)
        self._row_state.setVisible(False)
        self._result_panel.setVisible(False)
        self._auto_btn.setEnabled(False)
        self._realign_btn.setEnabled(False)
        self._restore_btn.setEnabled(False)
        self._unicode_normalize_btn.setEnabled(True)
        self._export_texts_btn.setEnabled(False)
        self._export_ai_package_btn.setEnabled(False)
        self._export_source_correction_btn.setEnabled(False)
        self._import_source_correction_btn.setEnabled(False)
        self._export_fusion_skeleton_btn.setEnabled(False)
        self._export_ai_repair_epub_btn.setEnabled(False)
        self._import_ai_repair_result_btn.setEnabled(False)
        self._ai_adjudicate_btn.setEnabled(False)
        self._import_ai_package_btn.setEnabled(False)
        self._apply_btn.setText("✓ 应用单OCR结果")
        self._apply_btn.setEnabled(True)
        self._refresh_single_source_controls()

    def _export_single_roundtrip_package(self):
        doc = self._single_doc
        if self._mode != "single" or doc is None:
            QMessageBox.warning(self, "没有单 OCR 结果", "请先点击“从 OCR 识别载入”。")
            return
        from engine.ocr_roundtrip_package import export_single_package, save_package
        title = safe_result_filename(str(getattr(doc.metadata, "title", "") or ""), default="single_ocr")
        path, selected_filter = QFileDialog.getSaveFileName(
            self, "导出单 OCR 大模型校对包", f"{title}_单OCR原格式校对包.json",
            "JSON 校对包 (*.json);;Markdown 校对包 (*.md)",
        )
        if not path:
            return
        if not Path(path).suffix:
            path += ".md" if "Markdown" in selected_filter else ".json"
        try:
            package = export_single_package(doc)
            written = save_package(package, path)
        except Exception as exc:
            show_error_dialog(self, "导出单 OCR 校对包失败", str(exc))
            return
        QMessageBox.information(
            self, "导出完成",
            f"已导出 {len(package.get('editable_items', []))} 个可校对正文块：\n{written}\n\n"
            "只修改 edited_text 或 Markdown 校对结果区，不要改动 ID 和结构清单。",
        )

    def _import_single_roundtrip_package(self):
        from engine.ocr_roundtrip_package import import_single_package, load_package
        path, _ = QFileDialog.getOpenFileName(
            self, "导入单 OCR 大模型校对包", "", "OCR 校对包 (*.json *.md *.markdown)",
        )
        if not path:
            return
        current = self._single_doc or self._available_single_doc or self._primary_doc
        try:
            package = load_package(path)
            imported = import_single_package(package, current_document=current)
        except Exception as exc:
            show_error_dialog(self, "导入单 OCR 校对包失败", str(exc))
            return
        self._available_single_doc = imported
        self._available_single_label = "外部 AI 校对后的单 OCR"
        self._available_single_generation += 1
        self._load_single_result(
            imported, self._available_single_label, self._available_single_generation
        )
        self.single_doc_applied.emit(imported)
        QMessageBox.information(
            self, "单 OCR 校对包已应用",
            "修改文字已按 block ID 完整覆盖并进入 Formatter、文本替换、文本对比、图文对照和 EPUB。\n"
            "同一来源被更新，没有新增重复副本，也没有执行全文查找替换。",
        )

    def prepare_large_result_load(self, labels, row_count: int = 0) -> int:
        """Paint the workspace before heavy QTextDocument assignment begins."""
        self.clear()
        generation = self._result_load_generation
        model_text = " · ".join(str(item) for item in (labels or [])) or "多模型 OCR"
        count_text = f"，约 {int(row_count)} 句" if row_count else ""
        self._summary.setText(
            f"正在载入 OCR 对比：{model_text}{count_text}。"
            "大文档将按需创建候选控件，请稍候…"
        )
        self._virtual_hint.setText("正在准备轻量裁决状态…")
        return generation

    def set_results(self, payload: dict, *, generation: int | None = None):
        if generation is not None and generation != self._result_load_generation:
            return
        self._suspended_multi_state = None
        documents = list(payload.get("documents") or [])[:3]
        comparison = payload.get("comparison")
        fused_doc = payload.get("fused")
        ruby_enabled = bool(
            payload.get(
                "ruby_enabled",
                getattr(getattr(fused_doc, "metadata", None), "ruby_preservation_enabled", False),
            )
        )
        ruby_overlay_doc = fused_doc if ruby_enabled else None
        self._ruby_overlay_doc = ruby_overlay_doc
        # Keep immutable worker results by reference instead of deep-copying
        # three 300-page books and the whole comparison on the GUI thread.
        # User decisions live in separate lightweight states; destructive
        # operations use copy-on-write only when explicitly requested.
        self._initial_payload = {
            "documents": tuple(documents),
            "labels": tuple(list(payload.get("labels") or [])[:3]),
            # The worker-owned comparison remains the immutable restore source.
            # The review UI keeps all user decisions in lightweight states and
            # only copies the comparison on explicit destructive operations.
            "comparison": comparison,
            "source_texts": tuple(payload.get("source_texts") or ()),
            "fused": ruby_overlay_doc,
            "ruby_enabled": ruby_enabled,
        }
        self._load_results(payload)

    def _load_results(self, payload: dict):
        self._mode = "multi"
        self._single_doc = None
        self._single_original_doc = None
        self._documents = list(payload.get("documents") or [])[:3]
        self._labels = list(payload.get("labels") or [])[:3]
        self._comparison = payload.get("comparison")
        fused_doc = payload.get("fused")
        ruby_enabled = bool(
            payload.get(
                "ruby_enabled",
                getattr(getattr(fused_doc, "metadata", None), "ruby_preservation_enabled", False),
            )
        )
        self._ruby_overlay_doc = fused_doc if ruby_enabled else None
        self._primary_doc = self._documents[0] if self._documents else None
        if self._comparison is None or len(self._documents) < 2:
            self.clear()
            return

        source_texts = list(payload.get("source_texts") or [])
        prepared_source_texts = []
        for index in range(len(self._documents)):
            prepared_text = (
                str(source_texts[index])
                if index < len(source_texts)
                else "\n".join(row.texts[index] for row in self._comparison.rows)
            )
            prepared_source_texts.append(prepared_text)
        self._set_full_source_texts(prepared_source_texts)
        self._single_card_preview_row = -1
        self._loading_text = True
        try:
            for index in range(3):
                visible = index < len(self._documents)
                self._source_panels[index].setVisible(visible)
                self._source_editors[index].setReadOnly(self._single_card_enabled)
                self._choose_buttons[index].setVisible(visible)
                self._choose_buttons[index].setEnabled(visible)
                if visible:
                    label = self._labels[index] if index < len(self._labels) else f"模型{index + 1}"
                    self._choose_buttons[index].setText(f"模型{index + 1}")
                    self._choose_buttons[index].setToolTip(
                        f"当前句采用模型{index+1} · {label}"
                    )
                    visible_text = (
                        self._source_line_text(index, self._current_row_index)
                        if self._single_card_enabled
                        else self._source_text(index)
                    )
                    self._source_editors[index].setUpdatesEnabled(False)
                    try:
                        self._source_editors[index].setPlainText(visible_text)
                    finally:
                        self._source_editors[index].setUpdatesEnabled(True)
                else:
                    self._source_editors[index].clear()
        finally:
            self._loading_text = False
        self._set_source_labels_for_mode()
        self._sources_dirty = False
        self._workspace_title.setText("OCR 对比 · 逐句裁决")
        self._sync_review_mode_controls()
        self._image_review_mode_btn.setEnabled(True)
        self._choose_label.setVisible(True)
        self._row_state.setVisible(True)
        self._result_panel.setVisible(True)
        self._result_title.setText("融合结果（真正一致与两模型共同候选均自动保留；真正分歧需裁决）")
        self._apply_btn.setText("✓ 应用融合稿")
        self._single_export_btn.setEnabled(False)
        self._export_ai_package_btn.setEnabled(True)
        self._export_source_correction_btn.setEnabled(True)
        self._import_source_correction_btn.setEnabled(True)
        self._export_fusion_skeleton_btn.setEnabled(True)
        self._export_ai_repair_epub_btn.setEnabled(True)
        self._import_ai_repair_result_btn.setEnabled(True)
        self._ai_adjudicate_btn.setEnabled(not self._ai_import_busy)
        self._import_ai_package_btn.setEnabled(True)
        self._rebuild_fusion_rows(auto_choose=False)
        self._set_review_mode("decision", force=True)
        self._refresh_source_highlights()
        self._summary.setText(
            f"模型：{' · '.join(self._labels)}。{self._comparison.summary} "
            "共同字符已标绿、差异字符已标红；真正分歧等待逐句裁决，第3模型未独立运行的两模型共同候选按 v8 规则自动保留。"
        )
        self._auto_btn.setEnabled(True)
        self._realign_btn.setEnabled(True)
        self._restore_btn.setEnabled(self._initial_payload is not None)
        self._unicode_normalize_btn.setEnabled(True)
        self._export_texts_btn.setEnabled(True)
        self._export_ai_package_btn.setEnabled(True)
        self._export_source_correction_btn.setEnabled(True)
        self._import_source_correction_btn.setEnabled(True)
        self._export_fusion_skeleton_btn.setEnabled(True)
        self._export_ai_repair_epub_btn.setEnabled(True)
        self._import_ai_repair_result_btn.setEnabled(True)
        self._ai_adjudicate_btn.setEnabled(not self._ai_import_busy)
        self._import_ai_package_btn.setEnabled(True)
        self._apply_btn.setEnabled(True)
        unresolved_rows = [state.row_index for state in self._fusion_states if state.unresolved]
        if self._review_only_enabled and unresolved_rows:
            self._select_row(unresolved_rows[0])
        else:
            self._select_row(0)
            if (
                self._comparison.conflict_rows
                or int(getattr(self._comparison, "provisional_consensus_rows", 0) or 0)
            ):
                self._jump_conflict(1, include_current=True)

    @staticmethod
    def _image_review_row_identity(row) -> str:
        column_ids = tuple(str(value) for value in (getattr(row, "column_ids", ()) or ()) if str(value))
        if column_ids:
            return "columns:" + "|".join(column_ids)
        return (
            f"block:{str(getattr(row, 'primary_block_id', '') or '')}:"
            f"{int(getattr(row, 'primary_segment_index', 0) or 0)}"
        )

    def _reapply_image_review_overrides(self) -> None:
        if self._comparison is None or not self._image_review_overrides:
            return
        from engine.ocr_compare_view_model import upsert_external_candidate
        for row_index, row in enumerate(self._comparison.rows):
            override = self._image_review_overrides.get(self._image_review_row_identity(row))
            if not isinstance(override, dict) or row_index >= len(self._fusion_states):
                continue
            upsert_external_candidate(
                self._fusion_states[row_index],
                str(override.get("text", "") or ""),
                display_label="图文对照人工校对",
                select=True,
                reason="由图文对照保存并同步；OCR 模型原文保持不变。",
                confidence=1.0,
                allow_empty=bool(override.get("delete_intentionally", False)),
                force_role_candidate=True,
                selection_origin="human_image_review",
            )

    def _fusion_decision_payload(self, row_index: int, *, origin: str = "ocr_compare") -> dict | None:
        if self._comparison is None or not 0 <= int(row_index) < len(self._fusion_states):
            return None
        row_index = int(row_index)
        row = self._comparison.rows[row_index]
        state = self._fusion_states[row_index]
        selected_index = state.selected_index
        candidate = None
        if selected_index is not None and 0 <= selected_index < len(state.candidates):
            candidate = state.candidates[selected_index]
        return {
            "row_index": row_index,
            "column_ids": [
                str(value) for value in (getattr(row, "column_ids", ()) or ()) if str(value)
            ],
            "resolved": candidate is not None,
            "text": str(getattr(candidate, "text", "") or "") if candidate is not None else "",
            "delete_intentionally": bool(
                getattr(candidate, "delete_intentionally", False)
            ) if candidate is not None else False,
            "selected_candidate_index": int(selected_index) if selected_index is not None else -1,
            "display_label": str(getattr(candidate, "display_label", "") or "") if candidate is not None else "",
            "reason": str(getattr(candidate, "reason", "") or "") if candidate is not None else "",
            "confidence": float(getattr(candidate, "confidence", 0.0) or 0.0) if candidate is not None else 0.0,
            "origin": str(origin or "ocr_compare"),
        }

    def _publish_fusion_decision(self, row_index: int, *, origin: str = "ocr_compare") -> None:
        payload = self._fusion_decision_payload(row_index, origin=origin)
        if payload is not None:
            self.fusion_decision_changed.emit(payload)

    def apply_image_review_update(self, payload: dict, *, refresh: bool = True) -> bool:
        """Publish one 图文对照 sentence as the selected final fusion candidate.

        This intentionally does *not* edit NDLOCR/48px/Apple Vision source text.
        The reviewed sentence becomes a synthetic manual candidate on the exact
        comparison row and therefore participates in export, recovery and EPUB.
        """
        if self._mode != "multi" or self._comparison is None or not self._fusion_states:
            return False
        if not isinstance(payload, dict):
            return False
        try:
            row_index = int(payload.get("row_index", -1))
        except (TypeError, ValueError, OverflowError):
            row_index = -1
        incoming_columns = tuple(
            str(value) for value in (payload.get("column_ids") or ()) if str(value)
        )
        # Prefer the shared stable row index, but recover by the complete physical
        # column identity when a restored/re-aligned session changed row numbering.
        # Earlier versions silently rejected this case while 图文仍 displayed
        # “已同步”, leaving the two workspaces contradictory.
        from engine.ocr_compare_view_model import resolve_stable_row_index
        resolved_index = resolve_stable_row_index(
            self._comparison.rows, row_index, incoming_columns
        )
        target_index = int(resolved_index) if resolved_index is not None else -1
        if not 0 <= target_index < len(self._comparison.rows) or target_index >= len(self._fusion_states):
            return False
        row_index = target_index
        row = self._comparison.rows[row_index]
        expected_columns = tuple(
            str(value) for value in (getattr(row, "column_ids", ()) or ()) if str(value)
        )
        text = str(payload.get("text", "") or "")
        delete_intentionally = bool(payload.get("delete_intentionally", False))
        if not text.strip() and not delete_intentionally:
            return False
        identity = self._image_review_row_identity(row)
        self._image_review_overrides[identity] = {
            "text": text,
            "column_ids": list(expected_columns),
            "segment_key": str(payload.get("segment_key", "") or ""),
            "delete_intentionally": delete_intentionally,
        }
        from engine.ocr_compare_view_model import upsert_external_candidate
        upsert_external_candidate(
            self._fusion_states[row_index],
            text,
            display_label="图文对照人工校对",
            select=True,
            reason="由图文对照保存并同步；OCR 模型原文保持不变。",
            confidence=1.0,
            allow_empty=delete_intentionally,
            force_role_candidate=True,
            selection_origin="human_image_review",
        )
        # Publish the same authoritative state to every linked review surface.
        # ``origin=image_review`` prevents MainWindow from echoing the event back
        # into the source widget while still allowing other consumers to observe it.
        self._publish_fusion_decision(row_index, origin="image_review")
        if refresh:
            # The authoritative decision is written first; review-only mode then
            # removes the resolved row immediately and advances to the next item.
            self._current_row_index = row_index
            self._render_fusion_window(row_index, force=True)
            self._update_unresolved_summary()
            if self._review_only_enabled:
                QTimer.singleShot(0, lambda: self._jump_next_group_from(row_index))
            else:
                self._select_row(row_index)
            self._summary.setText(
                f"图文对照已同步到 OCR 对比第 {row_index + 1} 句；"
                "已选中独立的‘图文对照人工校对’候选，三个 OCR 模型原文未被覆盖。"
            )
        return True

    def sync_image_review_document(self, doc: UnifiedDocument | None) -> int:
        """Import all checked image-review groups from an applied document."""
        if doc is None or self._mode != "multi":
            return 0
        applied = 0
        for block in getattr(doc, "blocks", []):
            metadata = block.metadata if isinstance(getattr(block, "metadata", None), dict) else {}
            checked = metadata.get("ocr_image_text_review_checked_segments") or {}
            groups = metadata.get("ocr_review_sentence_groups") or []
            if not isinstance(checked, dict) or not isinstance(groups, list):
                continue
            for group in groups:
                if not isinstance(group, dict):
                    continue
                try:
                    row_index = int(group.get("row_index", -1))
                except (TypeError, ValueError, OverflowError):
                    continue
                segment_key = f"{block.id}:r{row_index:06d}"
                if not checked.get(segment_key):
                    continue
                if self.apply_image_review_update({
                    "row_index": row_index,
                    "column_ids": list(group.get("column_ids") or []),
                    "text": str(group.get("text", "") or ""),
                    "segment_key": segment_key,
                    "reviewed": True,
                }, refresh=False):
                    applied += 1
        if applied:
            self._render_fusion_window(self._current_row_index, force=True)
            self._update_unresolved_summary()
            self._summary.setText(
                f"已从图文对照同步 {applied} 条人工融合结果；OCR 模型原文保持不变。"
            )
        return applied

    def _clear_fusion_widgets(self, *, dispose: bool = True):
        active = dict(self._fusion_widgets)
        while self._fusion_layout.count() > 1:
            item = self._fusion_layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.hide()
        self._fusion_widgets = {}
        self._fusion_window_indices = ()
        if dispose:
            for widget in active.values():
                widget.deleteLater()
            for widget in self._fusion_widget_cache.values():
                widget.deleteLater()
            self._fusion_widget_cache.clear()
            return
        for row_index, widget in active.items():
            self._fusion_widget_cache[row_index] = widget
            self._fusion_widget_cache.move_to_end(row_index)
        while len(self._fusion_widget_cache) > self._fusion_widget_cache_limit:
            _old_row, old_widget = self._fusion_widget_cache.popitem(last=False)
            old_widget.deleteLater()

    def _obtain_fusion_widget(self, row_index: int, state) -> _FusionDecisionRow:
        widget = self._fusion_widget_cache.pop(int(row_index), None)
        if widget is not None and not widget.is_compatible_with(state, self._labels):
            # Never reuse a row whose check box is bound to an old decision
            # object or an older candidate list.  That stale-widget bug could
            # show “✓ 选择” while export still saw the row as unresolved.
            widget.hide()
            widget.deleteLater()
            widget = None
        if widget is None:
            widget = _FusionDecisionRow(
                row_index,
                [candidate.text for candidate in state.candidates],
                self._labels,
                self._fusion_content,
                preferred_model_index=state.preferred_model_index,
                decision_state=state,
            )
            widget.focused.connect(lambda index, self=self: self._select_row(index))
            widget.resolved.connect(self._fusion_row_resolved)
            widget.reopened.connect(self._fusion_row_reopened)
        else:
            widget.sync_from_state()
        widget.set_review_only_candidates(self._review_only_enabled)
        widget.show()
        return widget

    def _rebuild_fusion_rows(self, *, auto_choose: bool):
        from engine.ocr_compare_view_model import build_fusion_states
        self._clear_fusion_widgets()
        if self._comparison is None:
            self._fusion_states = []
            return
        # The comparison rows already contain exactly the text loaded into the
        # source editors.  Reading every QTextBlock back here would add another
        # O(rows × models) GUI-thread pass for no benefit.
        self._fusion_states = build_fusion_states(
            self._comparison.rows,
            auto_choose=auto_choose,
        )
        self._reapply_image_review_overrides()
        self._render_fusion_window(self._current_row_index, force=True)
        self._refresh_decision_queue(force=True)
        self._update_unresolved_summary()

    def _render_fusion_window(self, current_row: int, *, force: bool = False):
        if self._comparison is None or not self._fusion_states:
            self._clear_fusion_widgets()
            self._virtual_hint.setText("")
            return
        from engine.ocr_compare_view_model import windowed_row_indices
        if self._single_card_enabled:
            current_row = max(0, min(int(current_row), len(self._fusion_states) - 1))
            indices = (current_row,)
        else:
            indices = tuple(windowed_row_indices(
                self._fusion_states,
                current_row,
                review_only=self._review_only_enabled,
                window_size=self._fusion_window_size,
            ))
        if not force and indices == self._fusion_window_indices:
            return
        self._clear_fusion_widgets(dispose=False)
        self._fusion_window_indices = indices
        for row_index in indices:
            state = self._fusion_states[row_index]
            widget = self._obtain_fusion_widget(row_index, state)
            self._fusion_layout.insertWidget(self._fusion_layout.count() - 1, widget)
            self._fusion_widgets[row_index] = widget
        total = len(self._fusion_states)
        eligible = sum(1 for state in self._fusion_states if (state.unresolved if self._review_only_enabled else True))
        if indices and self._single_card_enabled:
            self._virtual_hint.setText(
                f"单框逐句 · 当前 {indices[0] + 1}/{total} 句"
            )
        elif indices:
            self._virtual_hint.setText(
                f"按需显示 {len(indices)}/{eligible} 句 · 全部 {total} 句"
            )
        elif self._review_only_enabled:
            self._virtual_hint.setText(f"待判断 0 句 · 全部 {total} 句")
        else:
            self._virtual_hint.setText(f"全部 {total} 句")

    def clear(self, *, preserve_available_single: bool = True):
        self._result_load_generation += 1
        self._ai_import_generation.invalidate()
        self._ai_import_signal_refs.clear()
        self._pending_ai_import_apply = None
        self._ai_import_busy = False
        # Source-correction export/import/restore workers may still be finishing
        # in background.  A clear, book switch, or mode replacement makes every
        # prior callback stale so old-book decisions can never land in the new
        # OCR workspace.  The worker may finish naturally; GenerationGuard drops it.
        self._source_correction_generation.invalidate()
        self._source_correction_signal_refs.clear()
        self._source_correction_busy = False
        self._source_correction_lock_workspace = False
        if hasattr(self, "_source_correction_progress"):
            self._source_correction_progress.setVisible(False)
        if hasattr(self, "_restore_source_session_btn"):
            self._restore_source_session_btn.setEnabled(True)
        self._full_source_texts = []
        self._full_source_lines = []
        self._single_card_preview_row = -1
        if hasattr(self, "_source_area"):
            self._source_area.setEnabled(True)
        if hasattr(self, "_result_panel"):
            self._result_panel.setEnabled(True)
        self._mode = "empty"
        self._single_doc = None
        self._single_original_doc = None
        self._loaded_single_generation = -1
        self._documents = []
        self._labels = []
        self._comparison = None
        self._primary_doc = None
        self._initial_payload = None
        # A true clear/new-book boundary must never retain Ruby annotations
        # from the previous multi-model session. Temporary multi -> single
        # switching saves/restores this overlay explicitly in _capture_multi_state.
        self._ruby_overlay_doc = None
        self._fusion_states = []
        self._image_review_overrides = {}
        self._canonical_source_decisions = {}
        self._source_correction_import_history = []
        self._source_correction_imported_package_ids = set()
        self._loading_text = True
        try:
            for index, editor in enumerate(self._source_editors):
                editor.setUpdatesEnabled(False)
                try:
                    editor.clear()
                    editor.setExtraSelections([])
                finally:
                    editor.setUpdatesEnabled(True)
                self._source_labels[index].setText(f"模型{index + 1} · 未载入")
                self._source_editors[index].setReadOnly(False)
                self._source_panels[index].setVisible(True)
        finally:
            self._loading_text = False
        self._clear_fusion_widgets()
        self._decision_queue_signature = ()
        if hasattr(self, "_decision_queue"):
            self._decision_queue.clear()
            self._decision_queue_count.setText("0")
        self._virtual_hint.setText("")
        self._workspace_title.setText("OCR 对比 · 结果收件箱")
        self._summary.setText(
            "单模型 OCR 完成后请手动点击“从 OCR 识别载入”；多模型 OCR 完成后会自动载入。"
        )
        self._choose_label.setVisible(True)
        self._row_state.setVisible(True)
        self._result_panel.setVisible(True)
        self._result_title.setText("逐句裁决 · 当前候选")
        self._apply_btn.setText("✓ 应用融合稿")
        self._row_state.setText("当前句：—")
        self._detail.setText("当前句：—")
        if hasattr(self, "_source_correction_state"):
            self._source_correction_state.setText("尚未导入逐源纠错")
        self._auto_btn.setEnabled(False)
        self._sync_review_mode_controls()
        self._image_review_mode_btn.setEnabled(False)
        self._realign_btn.setEnabled(False)
        self._restore_btn.setEnabled(False)
        self._unicode_normalize_btn.setEnabled(False)
        self._export_texts_btn.setEnabled(False)
        self._single_export_btn.setEnabled(False)
        self._export_ai_package_btn.setEnabled(False)
        self._export_source_correction_btn.setEnabled(False)
        self._import_source_correction_btn.setEnabled(False)
        self._export_fusion_skeleton_btn.setEnabled(False)
        self._export_ai_repair_epub_btn.setEnabled(False)
        self._import_ai_repair_result_btn.setEnabled(False)
        self._ai_adjudicate_btn.setEnabled(False)
        self._import_ai_package_btn.setEnabled(False)
        self._apply_btn.setEnabled(False)
        if hasattr(self, "_next_sentence_btn"):
            self._next_sentence_btn.setEnabled(False)
        for button in self._choose_buttons:
            button.setEnabled(False)
        if not preserve_available_single:
            self._available_single_doc = None
            self._available_single_label = ""
            self._available_single_generation = 0
        self._refresh_single_source_controls()

    def reset_for_new_book(self):
        self._suspended_multi_state = None
        self._reference_path = ""
        self._last_source_correction_report = None
        self._source_correction_export_report = None
        self._canonical_source_decisions = {}
        self._source_correction_import_history = []
        self._source_correction_imported_package_ids = set()
        self.clear(preserve_available_single=False)

    def shutdown_cleanup(self) -> None:
        self._result_load_generation += 1
        self._ai_import_generation.invalidate()
        self._ai_import_signal_refs.clear()
        self._source_correction_generation.invalidate()
        self._source_correction_signal_refs.clear()
        self._source_correction_busy = False
        self._source_correction_lock_workspace = False

    def _current_row(self) -> int:
        return max(0, self._current_row_index)

    def current_row_index(self) -> int:
        """Return the stable multi-model comparison row currently in view."""
        return self._current_row()

    def select_source_row(self, row_index: int) -> None:
        """Select one stable comparison row from another proofreading view."""
        if self._comparison is None or not self._comparison.rows:
            return
        try:
            target = int(row_index)
        except (TypeError, ValueError, OverflowError):
            return
        target = max(0, min(target, len(self._comparison.rows) - 1))
        if target == self._current_row_index:
            return
        self._select_row(target)

    def _source_cursor_changed(self, source_index: int):
        if self._single_card_enabled:
            return
        if self._loading_text or self._syncing_cursor or self._comparison is None:
            return
        row = self._source_editors[source_index].textCursor().blockNumber()
        self._select_row(row, source_index=source_index)

    def _source_text_changed(self):
        if self._loading_text or self._comparison is None or self._single_card_enabled:
            return
        sender = self.sender()
        if sender in self._source_editors:
            index = self._source_editors.index(sender)
            self._set_full_source_text(index, sender.toPlainText())
        self._sources_dirty = True
        self._highlight_timer.start()
        self._summary.setText(
            "源 OCR 已手动修改。字符红绿会自动刷新；若增删了换行，点击“重新自动对齐”后再裁决或应用。"
        )

    def _select_row(self, row: int, source_index: int | None = None):
        if self._comparison is None or not self._comparison.rows:
            return
        row = max(0, min(row, len(self._comparison.rows) - 1))
        self._current_row_index = row
        self._active_source_index = source_index
        self._syncing_cursor = True
        self._syncing_scroll = True
        try:
            if self._single_card_enabled:
                self._update_single_card_source_preview(row)
            else:
                editors = self._source_editors[:len(self._documents)]
                if editors:
                    anchor_index = source_index if source_index is not None and 0 <= source_index < len(editors) else 0
                    anchor = editors[anchor_index]
                    block = anchor.document().findBlockByNumber(row)
                    if block.isValid() and anchor.textCursor().blockNumber() != row:
                        anchor.setTextCursor(QTextCursor(block))
                    anchor.ensureCursorVisible()
                    scroll_value = anchor.verticalScrollBar().value()
                    # Keep the three books visually aligned without forcing Qt to
                    # reposition three independent cursors and repaint three full
                    # documents for every navigation click.
                    for index, editor in enumerate(editors):
                        if index != anchor_index and editor.verticalScrollBar().value() != scroll_value:
                            editor.verticalScrollBar().setValue(scroll_value)
        finally:
            self._syncing_scroll = False
            self._syncing_cursor = False

        self._render_fusion_window(row)
        for index, widget in self._fusion_widgets.items():
            widget.set_current(index == row)
        widget = self._fusion_widgets.get(row)
        if widget is not None:
            self._fusion_scroll.ensureWidgetVisible(widget, 0, 70)

        # Character-level painting is intentionally coalesced. Fast repeated
        # next/previous operations now perform one visible-window diff pass.
        self._highlight_timer.start()
        info = self._comparison.rows[row]
        if bool(getattr(info, "is_conflict", False)):
            conflict = "真正分歧"
        elif bool(getattr(info, "provisional_consensus", False)):
            conflict = "两模型共同候选"
        else:
            conflict = "真正一致"
        unresolved = row < len(self._fusion_states) and self._fusion_states[row].unresolved
        state = "待选择" if unresolved else "已确定"
        self._row_state.setText(
            f"当前句：{row + 1}/{len(self._comparison.rows)} · {conflict} · {state}"
        )
        warning = f"；提示：{'、'.join(info.warnings)}" if info.warnings else ""
        self._detail.setText(f"自动分析：{info.reason}{warning}")
        self._detail.setToolTip(self._detail.text())
        if hasattr(self, "_next_sentence_btn"):
            self._next_sentence_btn.setEnabled(row + 1 < len(self._comparison.rows))
        self._select_current_queue_item()
        self.current_row_changed.emit(int(row))

    def _visible_source_rows(self, editors: list[QPlainTextEdit]) -> list[int]:
        if self._comparison is None:
            return []
        row_count = len(self._comparison.rows)
        rows: set[int] = set()
        for editor in editors:
            try:
                first = max(0, editor.firstVisibleBlock().blockNumber())
                line_height = max(12, editor.fontMetrics().height())
                visible_count = max(18, editor.viewport().height() // line_height + 8)
            except Exception:
                first = max(0, self._current_row_index - 24)
                visible_count = 48
            rows.update(range(first, min(row_count, first + visible_count)))
        rows.update(range(
            max(0, self._current_row_index - 4),
            min(row_count, self._current_row_index + 5),
        ))
        return sorted(rows)

    def _refresh_source_highlights(self):
        if not self._workspace_active or self._comparison is None:
            return
        from engine.multi_ocr_compare import intraline_match_masks

        editors = self._source_editors[:len(self._documents)]
        if not editors:
            return
        if self._single_card_enabled:
            visible_rows = (self._current_row(),)
        else:
            row_count = min(
                [len(self._comparison.rows)]
                + [editor.document().blockCount() for editor in editors]
            )
            visible_rows = tuple(row for row in self._visible_source_rows(editors) if row < row_count)
        signature = (
            bool(self._single_card_enabled), int(self._current_row_index),
            int(self._highlight_source_revision), visible_rows,
        )
        if signature == self._last_highlight_signature:
            return
        self._last_highlight_signature = signature
        selections_by_editor: list[list[QTextEdit.ExtraSelection]] = [[] for _ in editors]

        for source_row in visible_rows:
            texts = tuple(self._source_line_text(index, source_row) for index in range(len(editors)))
            cached = self._highlight_mask_cache.get(source_row)
            if cached is not None and cached[0] == texts:
                masks = cached[1]
            else:
                masks = tuple(tuple(bool(value) for value in mask) for mask in intraline_match_masks(list(texts)))
                self._highlight_mask_cache[source_row] = (texts, masks)
            display_row = 0 if self._single_card_enabled else source_row
            for editor_index, (editor, text, mask) in enumerate(zip(editors, texts, masks)):
                block = editor.document().findBlockByNumber(display_row)
                if not block.isValid() or not text:
                    continue
                start_pos = 0
                while start_pos < len(text):
                    same = bool(mask[start_pos]) if start_pos < len(mask) else False
                    end_pos = start_pos + 1
                    while end_pos < len(text) and (
                        bool(mask[end_pos]) if end_pos < len(mask) else False
                    ) == same:
                        end_pos += 1
                    selection = QTextEdit.ExtraSelection()
                    cursor = QTextCursor(editor.document())
                    cursor.setPosition(block.position() + start_pos)
                    cursor.setPosition(block.position() + end_pos, QTextCursor.KeepAnchor)
                    selection.cursor = cursor
                    fmt = QTextCharFormat()
                    fmt.setBackground(QColor("#BDEFC9" if same else "#FFC7C7"))
                    fmt.setForeground(QColor("#202733"))
                    selection.format = fmt
                    selections_by_editor[editor_index].append(selection)
                    start_pos = end_pos

        if not self._single_card_enabled:
            row_count = min([len(self._comparison.rows)] + [editor.document().blockCount() for editor in editors])
            if 0 <= self._current_row_index < row_count:
                for editor_index, editor in enumerate(editors):
                    if self._active_source_index is not None and editor_index == self._active_source_index:
                        continue
                    block = editor.document().findBlockByNumber(self._current_row_index)
                    if not block.isValid():
                        continue
                    selection = QTextEdit.ExtraSelection()
                    cursor = QTextCursor(block)
                    cursor.select(QTextCursor.BlockUnderCursor)
                    selection.cursor = cursor
                    fmt = QTextCharFormat()
                    fmt.setFontUnderline(True)
                    fmt.setUnderlineColor(QColor("#1677FF"))
                    selection.format = fmt
                    selections_by_editor[editor_index].append(selection)

        for editor, selections in zip(editors, selections_by_editor):
            editor.setExtraSelections(selections)

    def _source_scroll_changed(self, source_index: int, value: int):
        if self._single_card_enabled:
            return
        if self._loading_text or self._syncing_scroll:
            return
        self._syncing_scroll = True
        try:
            for index, editor in enumerate(self._source_editors[:len(self._documents)]):
                if index != source_index:
                    editor.verticalScrollBar().setValue(value)
        finally:
            self._syncing_scroll = False
        if self._workspace_active:
            self._highlight_timer.start()

    def set_workspace_active(self, active: bool) -> None:
        active = bool(active)
        if active == self._workspace_active:
            return
        self._workspace_active = active
        if not active:
            self._highlight_timer.stop()
            return
        self._last_highlight_signature = None
        if self._comparison is not None:
            self._highlight_timer.start()

    def _choose_current_from_model(self, model_index: int):
        if self._comparison is None or model_index >= len(self._documents):
            return
        if self._sources_dirty:
            QMessageBox.information(self, "请先刷新对齐", "源 OCR 已修改，请先点击“重新自动对齐”。")
            return
        row = self._current_row()
        if row >= len(self._fusion_states):
            return
        widget = self._fusion_widgets.get(row)
        if widget is not None:
            chosen = widget.choose_model(model_index)
        else:
            chosen = self._fusion_states[row].choose_model(model_index)
            if chosen:
                self._fusion_row_resolved(row)
        if not chosen:
            QMessageBox.warning(self, "没有该候选", "当前融合候选中没有该模型的有效文字。")
            return
        label = self._labels[model_index] if model_index < len(self._labels) else f"模型{model_index + 1}"
        self._detail.setText(f"手动裁决：当前句采用模型{model_index + 1} · {label}，其他候选已收起。")
        self._select_row(row)

    def _alignment_counts_valid(self, *, show_warning: bool = True) -> bool:
        if self._comparison is None:
            return False
        expected = len(self._comparison.rows)
        counts = [self._source_line_count(index) for index in range(len(self._documents))]
        if all(count == expected for count in counts):
            return True
        if show_warning:
            QMessageBox.warning(
                self, "对齐行数已改变",
                f"当前对齐为 {expected} 行；各 OCR 栏现在为：{counts}。\n"
                "允许新增或删除换行，请点击“重新自动对齐”后再继续。",
            )
        return False

    def _realign_and_auto(self):
        if self._comparison is None or len(self._documents) < 2:
            return
        from engine.multi_ocr_compare import realign_ocr_texts
        self._sync_full_source_cache_from_editors()
        source_texts = [self._source_text(index) for index in range(len(self._documents))]
        template = self._initial_payload.get("comparison") if self._initial_payload else self._comparison
        try:
            comparison = realign_ocr_texts(source_texts, self._labels, template)
        except Exception as exc:
            show_error_dialog(self, "重新自动对齐失败", str(exc))
            return
        self._comparison = comparison
        self._set_full_source_texts([
            "\n".join(row.texts[model_index] for row in comparison.rows)
            for model_index in range(len(self._documents))
        ])
        self._loading_text = True
        try:
            for model_index, editor in enumerate(self._source_editors[:len(self._documents)]):
                editor.setUpdatesEnabled(False)
                try:
                    editor.setReadOnly(self._single_card_enabled)
                    editor.setPlainText(
                        self._source_line_text(model_index, self._current_row())
                        if self._single_card_enabled
                        else self._source_text(model_index)
                    )
                finally:
                    editor.setUpdatesEnabled(True)
        finally:
            self._loading_text = False
        self._set_source_labels_for_mode()
        self._sources_dirty = False
        self._rebuild_fusion_rows(auto_choose=False)
        self._refresh_source_highlights()
        self._summary.setText(
            f"已接受增删换行并重新自动对齐。{comparison.summary} "
            "红绿字符差异与融合候选已重建；真正分歧需重新裁决，两模型共同候选按 v8 规则自动保留。"
        )
        self._select_row(min(self._current_row(), max(0, len(comparison.rows) - 1)))

    @staticmethod
    def _normalization_report_text(report) -> str:
        lines = list(report.summary_lines()) if report is not None else []
        if not lines:
            return "未发现需要修复或仅比较处理的 Unicode 码位差异。"
        head = (
            f"正文无损修复 {int(report.texts_changed or 0)} 个文本单元、"
            f"{int(report.total_changes or 0)} 处；"
            f"仅比较处理 {int(getattr(report, 'total_compare_only_changes', 0) or 0)} 处。\n"
            "删除 OCR 字符：0；汉字/异体字替换：0。"
        )
        return head + "\n" + "\n".join(f"• {line}" for line in lines[:12])

    def _standardize_unicode_variants(self):
        """Normalize representation-only OCR differences in the current copy."""
        from engine.ocr_unicode_standardizer import (
            comparison_keys_for_texts,
            normalize_document_copy,
            normalize_japanese_ocr_text,
            normalize_text_collection_with_keys,
        )

        if self._mode == "single":
            if self._single_doc is None:
                QMessageBox.warning(self, "没有 OCR 结果", "请先从 OCR 识别载入单 OCR 结果。")
                return
            normalized_doc, report = normalize_document_copy(self._single_doc)
            if not report.changed:
                QMessageBox.information(
                    self, "标准化检查完成",
                    "当前单 OCR 已使用统一 Unicode 码位，不需要修复。",
                )
                return
            if self._single_original_doc is None:
                self._single_original_doc = self._single_doc
            self._single_doc = normalized_doc
            self._primary_doc = normalized_doc
            self._documents = [normalized_doc]
            self._loading_text = True
            try:
                self._source_editors[0].setPlainText(
                    self._single_document_preview_text(normalized_doc)
                )
            finally:
                self._loading_text = False
            self._restore_btn.setEnabled(True)
            self._summary.setText(
                "已对当前单 OCR 副本执行无损 Unicode 标准化；未删除字符、未替换汉字，原始 OCR 未覆盖，"
                "点击“恢复初始”可撤销，点击“应用单OCR结果”后才进入后续流程。"
            )
            QMessageBox.information(
                self, "无损标准化完成", self._normalization_report_text(report)
            )
            return

        if self._mode != "multi" or self._comparison is None or len(self._documents) < 2:
            QMessageBox.warning(self, "没有对比结果", "请先载入两份或三份 OCR 结果。")
            return

        self._sync_full_source_cache_from_editors()
        source_texts = [self._source_text(index) for index in range(len(self._documents))]
        normalized_texts, comparison_key_texts, report = (
            normalize_text_collection_with_keys(source_texts)
        )

        # Candidate editors may contain AI/manual text that is not in the source
        # columns.  Include those changes in the report and preserve them below.
        old_states = list(self._fusion_states)
        candidate_snapshots: list[list[dict]] = []
        for row_index, state in enumerate(old_states):
            row_candidates: list[dict] = []
            row = self._comparison.rows[row_index] if row_index < len(self._comparison.rows) else None
            original_row_texts = list(getattr(row, "texts", []) or [])
            for candidate_index, candidate in enumerate(state.candidates):
                normalized_candidate, candidate_report = normalize_japanese_ocr_text(candidate.text)
                is_selected = state.selected_index == candidate_index
                is_external = bool(candidate.synthetic and candidate.display_label != "字符级融合建议")
                is_manual_model_edit = False
                if candidate.model_indices:
                    source_values = [
                        original_row_texts[index]
                        for index in candidate.model_indices
                        if 0 <= index < len(original_row_texts)
                    ]
                    is_manual_model_edit = bool(source_values) and all(
                        str(candidate.text or "") != str(value or "") for value in source_values
                    )
                if is_external or is_manual_model_edit:
                    report.merge(candidate_report)
                if is_external or is_manual_model_edit or is_selected:
                    row_candidates.append({
                        "text": normalized_candidate,
                        "selected": is_selected,
                        "external": is_external,
                        "manual_model_edit": is_manual_model_edit,
                        "display_label": str(candidate.display_label or ""),
                        "reason": str(candidate.reason or ""),
                        "confidence": float(candidate.confidence or 0.0),
                        "delete_intentionally": bool(candidate.delete_intentionally),
                        "transaction_id": str(candidate.transaction_id or ""),
                        "transaction_operation": str(candidate.transaction_operation or ""),
                        "transaction_member_ids": tuple(candidate.transaction_member_ids or ()),
                        "audit_level": str(candidate.audit_level or ""),
                        "audit_flags": tuple(candidate.audit_flags or ()),
                        "selection_origin": str(getattr(state, "selection_origin", "") or "") if is_selected else "",
                    })
            candidate_snapshots.append(row_candidates)

        if not report.changed:
            QMessageBox.information(
                self, "标准化检查完成",
                "当前各 OCR 结果与候选已使用统一 Unicode 码位，不需要修复。",
            )
            return

        old_conflicts = int(getattr(self._comparison, "conflict_rows", 0) or 0)
        current_row = self._current_row()
        normalized_lines = [self._split_source_lines(text) for text in normalized_texts]
        comparison_key_lines = [
            self._split_source_lines(text) for text in comparison_key_texts
        ]
        expected_rows = len(self._comparison.rows)
        same_boundaries = (
            all(len(lines) == expected_rows for lines in normalized_lines)
            and all(len(lines) == expected_rows for lines in comparison_key_lines)
        )

        try:
            if same_boundaries:
                from engine.multi_ocr_compare import refresh_comparison_after_text_standardization
                comparison = copy.deepcopy(self._comparison)
                for row_index, row in enumerate(comparison.rows):
                    row.texts[:len(self._documents)] = [
                        normalized_lines[model_index][row_index]
                        for model_index in range(len(self._documents))
                    ]
                    row.comparison_keys = tuple(
                        comparison_key_lines[model_index][row_index]
                        for model_index in range(len(self._documents))
                    )
                    row.comparison_key_sources = tuple(
                        str(value or "") for value in row.texts
                    )
                comparison = refresh_comparison_after_text_standardization(comparison)
            else:
                from engine.multi_ocr_compare import realign_ocr_texts
                comparison = realign_ocr_texts(
                    normalized_texts, self._labels, self._comparison
                )
                for row in comparison.rows:
                    row.comparison_keys = tuple(
                        comparison_keys_for_texts(row.texts)
                    )
                    row.comparison_key_sources = tuple(
                        str(value or "") for value in row.texts
                    )
                comparison = refresh_comparison_after_text_standardization(comparison)
        except Exception as exc:
            show_error_dialog(self, "无损标准化失败", str(exc))
            return

        self._comparison = comparison
        self._set_full_source_texts(normalized_texts)
        self._loading_text = True
        try:
            for model_index, editor in enumerate(self._source_editors[:len(self._documents)]):
                editor.setUpdatesEnabled(False)
                try:
                    editor.setReadOnly(self._single_card_enabled)
                    editor.setPlainText(
                        self._source_line_text(model_index, current_row)
                        if self._single_card_enabled
                        else self._source_text(model_index)
                    )
                finally:
                    editor.setUpdatesEnabled(True)
        finally:
            self._loading_text = False
        self._sources_dirty = False
        self._rebuild_fusion_rows(auto_choose=False)

        # Restore AI candidates, manually edited candidate cards and explicit
        # choices after the comparison rows have been rebuilt.
        from engine.ocr_compare_view_model import upsert_external_candidate
        for row_index, snapshots in enumerate(candidate_snapshots):
            if row_index >= len(self._fusion_states):
                break
            state = self._fusion_states[row_index]
            for snapshot in snapshots:
                text = str(snapshot.get("text", "") or "")
                selected = bool(snapshot.get("selected", False))
                if snapshot.get("external"):
                    upsert_external_candidate(
                        state, text,
                        display_label=str(snapshot.get("display_label") or "外部候选"),
                        select=selected,
                        reason=str(snapshot.get("reason") or ""),
                        confidence=float(snapshot.get("confidence") or 0.0),
                        allow_empty=bool(snapshot.get("delete_intentionally")),
                        transaction_id=str(snapshot.get("transaction_id") or ""),
                        transaction_operation=str(snapshot.get("transaction_operation") or ""),
                        transaction_member_ids=tuple(snapshot.get("transaction_member_ids") or ()),
                        audit_level=str(snapshot.get("audit_level") or ""),
                        audit_flags=tuple(snapshot.get("audit_flags") or ()),
                        selection_origin=str(snapshot.get("selection_origin") or "restored_human") if selected else "",
                    )
                    continue
                if selected and state.choose_text(
                    text, origin=str(snapshot.get("selection_origin") or "restored_human")
                ):
                    continue
                if snapshot.get("manual_model_edit"):
                    upsert_external_candidate(
                        state, text,
                        display_label="人工编辑候选（标准化保留）",
                        select=selected,
                        reason="标准化前已在候选卡中手动修改，已作为独立候选保留。",
                        allow_empty=bool(snapshot.get("delete_intentionally")),
                        selection_origin=(
                            str(snapshot.get("selection_origin") or "human_manual_edit")
                            if selected else ""
                        ),
                    )

        self._render_fusion_window(current_row, force=True)
        self._refresh_source_highlights()
        self._update_unresolved_summary()
        self._restore_btn.setEnabled(self._initial_payload is not None)
        if self._comparison.rows:
            self._select_row(min(current_row, len(self._comparison.rows) - 1))

        removed_conflicts = max(0, old_conflicts - int(self._comparison.conflict_rows or 0))
        conflict_note = (
            f"；消除 {removed_conflicts} 句仅由码位差异造成的假冲突"
            if removed_conflicts else ""
        )
        self._summary.setText(
            f"Unicode 无损标准化完成{conflict_note}。未删除 OCR 内容，"
            "未替换汉字/异体字；兼容码位只参与临时比较，不写回正文。"
            "对齐、物理列 ID 和结构保持不变，候选已重新计算。"
        )
        QMessageBox.information(
            self, "无损标准化完成",
            self._normalization_report_text(report) +
            (f"\n\n假冲突减少：{removed_conflicts} 句" if removed_conflicts else ""),
        )

    def _restore_initial(self):
        if self._mode == "single":
            original = self._single_original_doc
            if original is None or original is self._single_doc:
                return
            label = self._labels[0] if self._labels else self._available_single_label or "单模型 OCR"
            generation = self._loaded_single_generation
            self._load_single_result(original, label, generation)
            self._summary.setText(
                "已恢复标准化前的单 OCR 原始结果；Unicode 标准化副本已撤销。"
            )
            return
        if not self._initial_payload:
            return
        payload = {
            "documents": list(self._initial_payload.get("documents") or []),
            "labels": list(self._initial_payload.get("labels") or []),
            "comparison": self._initial_payload.get("comparison"),
            "source_texts": list(self._initial_payload.get("source_texts") or []),
            "fused": self._initial_payload.get("fused"),
        }
        self._load_results(payload)
        self._summary.setText(
            "已恢复本次多模型 OCR 的初始文字、红绿差异、对齐与融合候选。"
            f"{self._comparison.summary if self._comparison else ''}"
        )

    def _auto_select_all(self):
        if self._comparison is None:
            return
        if self._sources_dirty or not self._alignment_counts_valid(show_warning=False):
            self._realign_and_auto()
            if self._sources_dirty or not self._alignment_counts_valid(show_warning=False):
                return
        from engine.multi_ocr_compare import choose_best_text, refresh_row_character_fusion
        # Auto-select changes reason/confidence/chosen_index metadata.  Copy only
        # when the user explicitly requests this operation, never during the
        # initial 300-page result handoff.
        self._comparison = copy.deepcopy(self._comparison)
        for row_index, row in enumerate(self._comparison.rows):
            texts = [
                self._source_line_text(model_index, row_index)
                for model_index in range(len(self._documents))
            ]
            choice, confidence, reason, warnings = choose_best_text(texts)
            row.texts[:len(texts)] = texts
            row.chosen_index = choice
            row.confidence = confidence
            row.reason = reason
            row.warnings = warnings
            refresh_row_character_fusion(row, self._labels)
        self._rebuild_fusion_rows(auto_choose=True)
        self._summary.setText(
            f"已按当前 OCR 文字自动选优并收起所有候选。{self._comparison.summary} "
            "任何已选候选框中的文字仍可直接手动修改。"
        )
        self._select_row(self._current_row())

    def _apply_review_filter(self):
        self._render_fusion_window(self._current_row(), force=True)

    def _set_single_card_mode(self, checked: bool):
        """Show one sentence and one decision frame without losing full OCR text."""
        enabled = bool(checked)
        if enabled == self._single_card_enabled:
            return
        if enabled:
            self._sync_full_source_cache_from_editors()
        self._single_card_enabled = enabled
        self._single_card_preview_row = -1
        if self._mode != "multi" or self._comparison is None:
            return

        current = self._current_row()
        if enabled and self._review_only_enabled:
            unresolved = [state.row_index for state in self._fusion_states if state.unresolved]
            if unresolved and (
                current >= len(self._fusion_states) or not self._fusion_states[current].unresolved
            ):
                current = unresolved[0]
        if enabled:
            self._update_single_card_source_preview(current, force=True)
            self._summary.setText(
                "已开启单框逐句：每个模型只显示当前句，下方只显示一个对比框；选择后自动进入下一句。"
            )
        else:
            self._restore_full_source_editors()
            self._summary.setText(
                "已恢复完整多模型文本视图；逐句选择和候选修改均已保留。"
            )
        self._render_fusion_window(current, force=True)
        self._select_row(current)

    def _set_review_only(self, checked: bool):
        self._review_only_enabled = bool(checked)
        current = self._current_row()
        unresolved = [state.row_index for state in self._fusion_states if state.unresolved]
        if self._review_only_enabled and (
            current >= len(self._fusion_states) or not self._fusion_states[current].unresolved
        ):
            if unresolved:
                current = unresolved[0]
            else:
                self._summary.setText("所有真正分歧均已完成裁决；两模型共同候选已按 v8 规则自动保留。")
        self._render_fusion_window(current, force=True)
        if self._fusion_states:
            self._select_row(current)

    def _fusion_row_resolved(self, row_index: int):
        # Atomic external repairs are selected as one transaction. Choosing a
        # non-transaction candidate in any member invalidates the old group
        # selection instead of leaving a partially applied boundary repair.
        if not getattr(self, "_atomic_selection_sync", False) and 0 <= row_index < len(self._fusion_states):
            state = self._fusion_states[row_index]
            selected_index = state.selected_index
            selected_candidate = (
                state.candidates[selected_index]
                if selected_index is not None and 0 <= selected_index < len(state.candidates)
                else None
            )
            selected_tx = str(getattr(selected_candidate, "transaction_id", "") or "")
            row_transactions = {
                str(getattr(candidate, "transaction_id", "") or "")
                for candidate in state.candidates
                if str(getattr(candidate, "transaction_id", "") or "")
            }
            self._atomic_selection_sync = True
            try:
                if selected_tx:
                    for member_state in self._fusion_states:
                        candidate_index = next((
                            index for index, candidate in enumerate(member_state.candidates)
                            if str(getattr(candidate, "transaction_id", "") or "") == selected_tx
                        ), None)
                        if candidate_index is not None:
                            member_state.selected_index = candidate_index
                            member_state.selection_origin = "human_ocr_compare"
                            member_state.review_indices = member_state._build_review_indices()
                    self._summary.setText(f"已成组选择原子修复事务：{selected_tx}")
                else:
                    for transaction_id in row_transactions:
                        for member_index, member_state in enumerate(self._fusion_states):
                            transaction_indices = [
                                index for index, candidate in enumerate(member_state.candidates)
                                if str(getattr(candidate, "transaction_id", "") or "") == transaction_id
                            ]
                            if member_state.selected_index in transaction_indices:
                                member_state.selected_index = None
                                member_state.selection_origin = ""
                                member_state.review_indices = member_state._build_review_indices()
                    # Keep the user's explicit non-transaction selection on this row.
                    state.selected_index = selected_index
            finally:
                self._atomic_selection_sync = False
            self._render_fusion_window(row_index, force=True)

        # Selection is stored in the lightweight decision state. Keep the
        # original worker comparison immutable so “恢复初始” stays O(1).
        self._update_unresolved_summary()
        # Publish every member whose selection may have changed as part of an
        # atomic transaction, not just the clicked row.
        affected_rows = {int(row_index)}
        if 0 <= row_index < len(self._fusion_states):
            chosen = self._fusion_states[row_index]
            if chosen.selected_index is not None and 0 <= chosen.selected_index < len(chosen.candidates):
                transaction_id = str(getattr(chosen.candidates[chosen.selected_index], "transaction_id", "") or "")
                if transaction_id:
                    for member_index, member_state in enumerate(self._fusion_states):
                        if member_state.selected_index is None or not 0 <= member_state.selected_index < len(member_state.candidates):
                            continue
                        if str(getattr(member_state.candidates[member_state.selected_index], "transaction_id", "") or "") == transaction_id:
                            affected_rows.add(member_index)
        for affected_row in sorted(affected_rows):
            self._publish_fusion_decision(affected_row, origin="ocr_compare")
        if self._single_card_enabled:
            self._refresh_decision_queue(force=False)
            if self._auto_advance_check.isChecked():
                if self._review_only_enabled:
                    QTimer.singleShot(0, lambda: self._jump_next_group_from(row_index))
                else:
                    QTimer.singleShot(0, lambda: self._jump_next_sentence_from(row_index))
            else:
                self._select_row(row_index)
            return
        if self._review_only_enabled:
            QTimer.singleShot(0, lambda: self._jump_next_group_from(row_index))

    def _fusion_row_reopened(self, row_index: int):
        if getattr(self, "_atomic_selection_sync", False) or not 0 <= row_index < len(self._fusion_states):
            return
        transaction_ids = {
            str(getattr(candidate, "transaction_id", "") or "")
            for candidate in self._fusion_states[row_index].candidates
            if str(getattr(candidate, "transaction_id", "") or "")
        }
        if not transaction_ids:
            self._render_fusion_window(row_index, force=True)
            self._update_unresolved_summary()
            self._publish_fusion_decision(row_index, origin="ocr_compare")
            self._refresh_decision_queue(force=True)
            self._summary.setText("已重新打开当前句，图文对照同步恢复为待确认。")
            return
        self._atomic_selection_sync = True
        try:
            for transaction_id in transaction_ids:
                for state in self._fusion_states:
                    transaction_indices = [
                        index for index, candidate in enumerate(state.candidates)
                        if str(getattr(candidate, "transaction_id", "") or "") == transaction_id
                    ]
                    if state.selected_index in transaction_indices:
                        state.selected_index = None
                        state.selection_origin = ""
                        state.review_indices = state._build_review_indices()
        finally:
            self._atomic_selection_sync = False
        self._render_fusion_window(row_index, force=True)
        self._update_unresolved_summary()
        affected_rows = {int(row_index)}
        for member_index, state in enumerate(self._fusion_states):
            if any(str(getattr(candidate, "transaction_id", "") or "") in transaction_ids for candidate in state.candidates):
                affected_rows.add(member_index)
        for affected_row in sorted(affected_rows):
            self._publish_fusion_decision(affected_row, origin="ocr_compare")
        self._refresh_decision_queue(force=True)
        self._summary.setText("已撤销整组原子修复选择，事务成员全部恢复为待确认。")

    def _jump_previous_group(self):
        """Jump to the previous unresolved decision without changing any selection."""
        if self._comparison is None or not self._fusion_states:
            return
        current = self._current_row()
        total = len(self._fusion_states)
        for offset in range(1, total + 1):
            index = (current - offset) % total
            if self._fusion_states[index].unresolved:
                self._select_row(index)
                self._summary.setText(f"已定位到上一组待判断候选：第 {index + 1}/{total} 句。")
                return
        self._summary.setText("所有不一致候选均已完成选择；没有上一组待判断内容。")

    def _jump_next_sentence(self):
        """Move OCR 对比 to the next stable sentence without changing any decision."""
        if self._comparison is None or not self._fusion_states:
            return
        self._jump_next_sentence_from(self._current_row())

    def _jump_next_sentence_from(self, row_index: int):
        if self._comparison is None or not self._fusion_states:
            return
        next_index = int(row_index) + 1
        if next_index < len(self._fusion_states):
            self._select_row(next_index)
            self._summary.setText(
                f"已自动进入下一句：第 {next_index + 1}/{len(self._fusion_states)} 句。"
            )
            return
        self._render_fusion_window(row_index, force=True)
        if hasattr(self, "_next_sentence_btn"):
            self._next_sentence_btn.setEnabled(False)
        self._summary.setText("已完成最后一句；没有下一句。")

    def _jump_next_group_from(self, row_index: int):
        if self._comparison is None or not self._fusion_states:
            return
        total = len(self._fusion_states)
        for offset in range(1, total + 1):
            index = (row_index + offset) % total
            if self._fusion_states[index].unresolved:
                self._select_row(index)
                self._summary.setText(
                    f"已自动进入下一组待判断候选：第 {index + 1}/{total} 句。"
                )
                return
        self._render_fusion_window(row_index, force=True)
        self._summary.setText("所有不一致候选均已完成选择；没有下一组待判断内容。")

    def _jump_next_group(self):
        """Jump only to unresolved decision groups, skipping exact/finished rows."""
        if self._comparison is None or not self._fusion_states:
            return
        if self._sources_dirty or not self._alignment_counts_valid(show_warning=False):
            self._realign_and_auto()
            if self._sources_dirty or not self._alignment_counts_valid(show_warning=False):
                return
        current = self._current_row()
        total = len(self._fusion_states)
        for offset in range(1, total + 1):
            index = (current + offset) % total
            if self._fusion_states[index].unresolved:
                self._select_row(index)
                self._summary.setText(
                    f"已定位到下一组待判断候选：第 {index + 1}/{total} 句。"
                    "完全相同和已经选择的组已自动跳过。"
                )
                return
        self._summary.setText("所有不一致候选均已完成选择；没有下一组待判断内容。")

    @staticmethod
    def _atomic_write_utf8(path: Path, text: str) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        temp = path.with_name(f".{path.name}.tmp")
        try:
            temp.write_text(text, encoding="utf-8")
            temp.replace(path)
        finally:
            if temp.exists():
                temp.unlink(missing_ok=True)

    def _comparison_with_current_source_texts(self):
        """Copy comparison only for export, preserving current model editor edits."""
        if self._comparison is None:
            return None
        # Even when the dirty flag was missed by an editor/undo edge case, a
        # changed line count must never be exported against stale row IDs.
        if not self._alignment_counts_valid(show_warning=False):
            return None
        comparison = copy.deepcopy(self._comparison)
        for row_index, row in enumerate(comparison.rows):
            row.texts[:len(self._documents)] = [
                self._source_line_text(model_index, row_index)
                for model_index in range(len(self._documents))
            ]
        return comparison

    def _export_multi_roundtrip_package(self):
        if self._comparison is None or len(self._documents) < 2:
            QMessageBox.warning(self, "没有多模型结果", "请先完成多模型 OCR。")
            return
        if self._sources_dirty and not self._alignment_counts_valid(show_warning=False):
            QMessageBox.information(
                self,
                "请先重新对齐",
                "各 OCR 栏的行数已改变。请先点击“重新对齐”，再导出大模型对比包。",
            )
            return
        comparison = self._comparison_with_current_source_texts()
        if comparison is None:
            QMessageBox.warning(self, "无法导出", "当前 OCR 对齐状态不完整。")
            return
        result_lines = []
        delete_flags = []
        for row_index, state in enumerate(self._fusion_states):
            value = state.output_text()
            if state.selected_index is None and row_index < len(comparison.rows):
                value = comparison.rows[row_index].output_text
            result_lines.append(str(value or ""))
            delete_flags.append(state.output_delete_intentionally())
        from engine.ocr_roundtrip_package import export_multi_package, save_package
        title = safe_result_filename(
            str(getattr(getattr(self._primary_doc, "metadata", None), "title", "") or ""),
            default="multi_ocr",
        )
        path, selected_filter = QFileDialog.getSaveFileName(
            self,
            "导出多模型 OCR 大模型对比包",
            f"{title}_多模型OCR对比融合包.json",
            "JSON 校对包 (*.json);;Markdown 校对包 (*.md)",
        )
        if not path:
            return
        if not Path(path).suffix:
            path += ".md" if "Markdown" in selected_filter else ".json"
        try:
            package = export_multi_package(
                self._documents,
                self._labels,
                comparison,
                result_lines=result_lines,
                delete_flags=delete_flags,
                ruby_overlay_source=self._ruby_overlay_doc,
            )
            written = save_package(package, path)
        except Exception as exc:
            show_error_dialog(self, "导出多模型 AI 对比包失败", str(exc))
            return
        QMessageBox.information(
            self,
            "导出完成",
            f"已导出 {len(package.get('model_sources', []))} 个 OCR 模型、"
            f"{len(package.get('editable_items', []))} 个对齐句组：\n{written}\n\n"
            "交给大模型时只修改 edited_text 或 Markdown 的“大模型校对结果”区域。",
        )

    def _current_comparison_documents_for_source_correction(self):
        """Compatibility helper; heavy synchronisation now runs in a worker."""
        if self._comparison is None or len(self._documents) < 2:
            raise ValueError("请先完成并载入多模型 OCR。")
        comparison = self._comparison_with_current_source_texts()
        if comparison is None:
            raise ValueError("当前 OCR 行数与对齐不一致，请先点击“重新对齐”。")
        from engine.multi_ocr_source_correction import documents_with_comparison_texts
        documents = documents_with_comparison_texts(self._documents, comparison)
        return documents, comparison

    def _set_source_correction_busy(self, busy: bool, message: str = "", *, lock_workspace: bool = False):
        self._source_correction_busy = bool(busy)
        self._source_correction_lock_workspace = bool(busy and lock_workspace)
        multi_ready = self._mode == "multi" and self._comparison is not None and len(self._documents) >= 2
        enabled = multi_ready and not self._source_correction_busy and not self._ai_import_busy
        for button in (
            self._auto_btn, self._realign_btn, self._unicode_normalize_btn,
            self._export_texts_btn, self._export_ai_package_btn,
            self._export_source_correction_btn, self._import_source_correction_btn,
            self._export_fusion_skeleton_btn, self._export_ai_repair_epub_btn,
            self._import_ai_repair_result_btn, self._ai_adjudicate_btn,
            self._import_ai_package_btn, self._apply_btn,
        ):
            button.setEnabled(enabled)
        self._restore_btn.setEnabled(enabled and self._initial_payload is not None)
        self._restore_source_session_btn.setEnabled(not busy and not self._ai_import_busy)
        self._source_correction_progress.setVisible(bool(busy))
        if busy:
            self._source_correction_progress.setValue(0)
            self._source_correction_progress.setFormat("准备 OCR 裁决任务…")
        workspace_enabled = not self._source_correction_lock_workspace and not self._ai_import_busy
        self._source_area.setEnabled(workspace_enabled)
        self._result_panel.setEnabled(workspace_enabled)
        if message:
            self._summary.setText(message)

    def _on_source_correction_progress(self, token: int, stage: str, current: int, total: int):
        if not self._source_correction_generation.is_current(token):
            return
        total = max(1, int(total or 1))
        current = max(0, min(int(current or 0), total))
        value = min(99, int(current * 100 / total))
        self._source_correction_progress.setValue(value)
        self._source_correction_progress.setFormat(f"{stage} {current}/{total}")
        self._source_correction_state.setText(str(stage or "OCR 裁决任务进行中…"))
        self._summary.setText(f"{stage}：{current}/{total}。任务在后台执行，窗口仍可响应。")

    def _on_source_correction_error(self, token: int, title: str, message: str):
        self._source_correction_signal_refs.pop(token, None)
        if not self._source_correction_generation.is_current(token):
            return
        self._set_source_correction_busy(False)
        self._source_correction_state.setText("OCR 裁决任务失败")
        show_error_dialog(self, title, str(message or "未知错误"))

    def _export_model_source_correction_package(self):
        if self._comparison is None or len(self._documents) < 2:
            QMessageBox.warning(self, "没有多模型结果", "请先完成多模型 OCR 并载入 OCR 对比。")
            return
        if self._source_correction_busy or self._ai_import_busy:
            QMessageBox.information(self, "任务进行中", "当前已有逐源纠错或 AI 导入任务在后台执行。")
            return
        comparison = self._comparison_with_current_source_texts()
        if comparison is None:
            QMessageBox.warning(self, "无法准备 AI OCR 裁决包", "当前 OCR 行数与对齐不一致，请先点击“重新对齐”。")
            return
        title = safe_result_filename(
            str(getattr(getattr(self._primary_doc, "metadata", None), "title", "") or ""),
            default="multi_ocr",
        )
        path, _ = QFileDialog.getSaveFileName(
            self, "导出多模型 AI OCR 裁决包",
            f"{title}_OCR多模型AI裁决包_v3.zip", "ZIP 纠错包 (*.zip)",
        )
        if not path:
            return
        token = self._source_correction_generation.begin()
        signals = WorkerSignals()
        self._source_correction_signal_refs[token] = signals
        signals.phase_progress.connect(
            lambda stage, current, total, t=token: self._on_source_correction_progress(t, stage, current, total)
        )
        signals.error.connect(
            lambda message, t=token: self._on_source_correction_error(t, "导出 AI OCR 裁决包失败", message)
        )
        signals.finished.connect(lambda result, t=token: self._on_source_correction_export_ready(t, result))
        documents = list(self._documents)
        labels = list(self._labels)
        recovery_selection_records = self._capture_current_fusion_selection_records()
        recovery_selections = {
            key: str(record.get("text", "") or "")
            for key, record in recovery_selection_records.items()
            if str(record.get("text", "") or "")
        }
        recovery_decisions = [dict(item) for item in self._canonical_source_decisions.values()]
        recovery_row_index = int(self._current_row_index)
        recovery_ruby_overlay = self._ruby_overlay_doc
        output_path = str(path)
        self._set_source_correction_busy(
            True, "正在后台同步物理列并导出 AI OCR 裁决包；上一轮已接受结果将作为可复审参考保留…", lock_workspace=False,
        )

        def worker():
            try:
                from engine.multi_ocr_source_correction import (
                    documents_with_comparison_texts, export_source_correction_bundle,
                )
                def progress(stage, current, total):
                    signals.phase_progress.emit(stage, current, total)
                synced = documents_with_comparison_texts(
                    documents, comparison, progress_callback=progress,
                )
                report = export_source_correction_bundle(
                    synced, labels, comparison, output_path, progress_callback=progress,
                    fusion_selections=recovery_selections,
                    fusion_selection_records=recovery_selection_records,
                    canonical_decisions=recovery_decisions,
                    review_prior_decisions=True,
                    current_row_index=recovery_row_index,
                    ruby_overlay_source=recovery_ruby_overlay,
                )
                signals.finished.emit(report)
            except Exception as exc:
                signals.error.emit(str(exc))

        threading.Thread(
            target=worker, name=f"source-correction-export-{token}", daemon=True,
        ).start()

    def _on_source_correction_export_ready(self, token: int, result: object):
        self._source_correction_signal_refs.pop(token, None)
        if not self._source_correction_generation.is_current(token):
            return
        if not isinstance(result, dict):
            self._on_source_correction_error(token, "导出 AI OCR 裁决包失败", "后台导出没有返回有效结果。")
            return
        report = dict(result)
        self._source_correction_export_report = report
        self._set_source_correction_busy(False)
        self._source_correction_progress.setValue(100)
        self._source_correction_state.setText(
            f"已导出 · 复审旧结果 {report.get('prior_decision_review_rows', 0)} · "
            f"共同候选自动保留 {report.get('provisional_consensus_rows', 0)} · "
            f"本轮待审 {report.get('pending_review_rows', 0)} · "
            f"包ID {str(report.get('package_id', ''))[:8]}"
        )
        QMessageBox.information(
            self, "OCR 逐模型纠错／最终裁决包已导出",
            f"真正分歧总数：{report.get('editable_conflict_rows', 0)}\n"
            f"两模型共同候选（自动保留）：{report.get('provisional_consensus_rows', 0)}\n"
            f"此前裁决保持锁定：{report.get('prefilled_prior_decision_rows', 0)}\n"
            f"此前已接受结果重新开放复审：{report.get('prior_decision_review_rows', 0)}\n"
            f"其中旧逐模型结果迁移：{report.get('prefilled_legacy_migration_rows', 0)}\n"
            f"本轮真正分歧待审：{report.get('pending_conflict_rows', 0)}\n"
            f"本轮共同候选待审：0（按 v8 自动保留）\n"
            f"本轮合计待审：{report.get('pending_review_rows', 0)}\n"
            f"过期裁决重新待审：{report.get('stale_prior_decision_rows', 0)}\n"
            f"锁定真正一致行：{report.get('locked_consensus_rows', 0)}\n"
            f"视觉证据：{report.get('image_count', 0)} 张\n"
            f"可恢复 OCR 会话：{'是' if report.get('recovery_snapshot_included') else '否'}\n\n"
            f"大模型可在 editable_conflict.model_edits 中只修正错误模型，"
            f"也可选填 ai_verdict.final_text 作为最终融合裁决；"
            f"上一轮 accepted 结果在新包中只作为参考，可由后续 AI 提交更好的 final_text：\n{report.get('path', '')}",
        )

    def set_recovery_page_image_provider(self, provider) -> None:
        """Provide current Page Manager images for post-crash path rebinding."""
        self._recovery_page_image_provider = provider if callable(provider) else None

    def _current_recovery_page_images(self) -> list[str]:
        provider = self._recovery_page_image_provider
        if not callable(provider):
            return []
        try:
            return [str(value) for value in (provider() or []) if str(value)]
        except Exception:
            return []

    def _restore_model_source_correction_session(self):
        if self._source_correction_busy or self._ai_import_busy:
            QMessageBox.information(self, "任务进行中", "当前已有逐源纠错或 AI 导入任务在后台执行。")
            return
        path, _ = QFileDialog.getOpenFileName(
            self, "恢复多模型 OCR 裁决会话", "", "AI OCR 裁决包/旧逐模型包 (*.zip)",
        )
        if not path:
            return
        if self._comparison is not None and self._documents:
            answer = QMessageBox.question(
                self, "替换当前 OCR 对比会话",
                "恢复会替换当前 OCR 对比中的三份模型文档和候选状态，但不会重新 OCR。继续吗？",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
        token = self._source_correction_generation.begin()
        signals = WorkerSignals()
        self._source_correction_signal_refs[token] = signals
        signals.phase_progress.connect(
            lambda stage, current, total, t=token: self._on_source_correction_progress(t, stage, current, total)
        )
        signals.error.connect(
            lambda message, t=token: self._on_source_correction_error(t, "恢复多模型 OCR 会话失败", message)
        )
        signals.finished.connect(lambda result, t=token: self._on_source_session_restore_ready(t, result))
        page_images = self._current_recovery_page_images()
        source_path = str(path)
        self._set_source_correction_busy(
            True, "正在后台恢复压缩 OCR 文档并重新建立对齐；不会调用任何 OCR 模型…", lock_workspace=True,
        )

        def worker():
            try:
                from engine.multi_ocr_source_correction import load_source_correction_recovery
                from engine.ocr_compare_view_model import build_fusion_states
                def progress(stage, current, total):
                    signals.phase_progress.emit(stage, current, total)
                documents, labels, comparison, report = load_source_correction_recovery(
                    source_path, replacement_page_images=page_images, progress_callback=progress,
                )
                prepared = [
                    "\n".join(str(row.texts[index] if index < len(row.texts) else "") for row in comparison.rows)
                    for index in range(len(documents))
                ]
                states = build_fusion_states(comparison.rows, auto_choose=False)
                from engine.multi_ocr_source_correction import apply_canonical_decisions_to_fusion_states
                decisions = [item for item in (report.get("canonical_decisions") or []) if isinstance(item, dict)]
                apply_canonical_decisions_to_fusion_states(states, comparison, decisions)
                signals.finished.emit({
                    "documents": documents, "labels": labels, "comparison": comparison,
                    "report": report, "prepared": prepared, "fusion_states": states,
                    "canonical_decisions": decisions,
                })
            except Exception as exc:
                signals.error.emit(str(exc))

        threading.Thread(target=worker, name=f"source-session-restore-{token}", daemon=True).start()

    def _on_source_session_restore_ready(self, token: int, result: object):
        self._source_correction_signal_refs.pop(token, None)
        if not self._source_correction_generation.is_current(token):
            return
        if not isinstance(result, dict):
            self._on_source_correction_error(token, "恢复多模型 OCR 会话失败", "后台恢复没有返回有效结果。")
            return
        try:
            documents = list(result.get("documents") or [])
            labels = list(result.get("labels") or [])
            comparison = result.get("comparison")
            report = dict(result.get("report") or {})
            restored_ruby_overlay = report.get("ruby_overlay")
            self.clear(preserve_available_single=True)
            self._initial_payload = {
                "documents": tuple(documents), "labels": tuple(labels),
                "comparison": comparison, "source_texts": tuple(result.get("prepared") or ()),
                "ruby_overlay": restored_ruby_overlay,
            }
            self._ruby_overlay_doc = restored_ruby_overlay
            self._labels = labels
            decisions = [item for item in (result.get("canonical_decisions") or report.get("canonical_decisions") or []) if isinstance(item, dict)]
            self._canonical_source_decisions = {
                tuple(str(value) for value in (item.get("column_ids") or [])): dict(item)
                for item in decisions if item.get("column_ids")
            }
            decision_keys = set(self._canonical_source_decisions)
            restored_selections = {
                key: value for key, value in (report.get("fusion_selections") or {}).items()
                if key not in decision_keys
            }
            restored_records = {
                key: value for key, value in (report.get("fusion_selection_records") or {}).items()
                if key not in decision_keys
            }
            self._replace_multi_source_workspace(
                documents, comparison, preserve_selections=restored_selections,
                preserve_selection_records=restored_records,
                prepared=result.get("prepared") or [], fusion_states=result.get("fusion_states") or [],
            )
            self._mode = "multi"
            # _replace_multi_source_workspace runs while clear() still marks
            # the tab as empty.  Re-sync after switching to multi so restored
            # sessions can use the visible "显示全文对比" control immediately.
            self._sync_review_mode_controls()
            self._current_row_index = min(
                max(0, int(report.get("current_row_index", 0) or 0)),
                max(0, len(comparison.rows) - 1),
            )
            self._workspace_title.setText("OCR 对比 · 已恢复纠错会话")
            self._choose_label.setVisible(True)
            self._row_state.setVisible(True)
            self._result_panel.setVisible(True)
            self._auto_btn.setEnabled(True)
            self._realign_btn.setEnabled(True)
            self._restore_btn.setEnabled(True)
            self._unicode_normalize_btn.setEnabled(True)
            self._export_texts_btn.setEnabled(True)
            self._export_ai_package_btn.setEnabled(True)
            self._export_source_correction_btn.setEnabled(True)
            self._import_source_correction_btn.setEnabled(True)
            self._export_fusion_skeleton_btn.setEnabled(True)
            self._export_ai_repair_epub_btn.setEnabled(True)
            self._import_ai_repair_result_btn.setEnabled(True)
            self._ai_adjudicate_btn.setEnabled(True)
            self._import_ai_package_btn.setEnabled(True)
            self._apply_btn.setEnabled(True)
            self._select_row(self._current_row_index)
        except Exception as exc:
            self._on_source_correction_error(token, "载入恢复会话失败", str(exc))
            return
        self._set_source_correction_busy(False)
        rebind = report.get("image_rebind") or {}
        self._source_correction_state.setText(
            f"会话已恢复 · {len(documents)} 模型 · {len(comparison.rows)} 句"
        )
        try:
            from engine.multi_ocr_compare import build_fused_document
            result_lines = [state.output_text() for state in self._fusion_states]
            delete_flags = [state.output_delete_intentionally() for state in self._fusion_states]
            fused = build_fused_document(
                self._primary_doc, comparison, result_lines, delete_flags=delete_flags,
                ruby_overlay_source=self._ruby_overlay_doc,
            )
        except Exception:
            fused = self._primary_doc
        self._ruby_overlay_doc = fused
        self.multi_session_restored.emit({
            "documents": documents, "labels": labels, "comparison": comparison,
            "fused": fused, "report": report,
        })
        QMessageBox.information(
            self, "多模型 OCR 会话已恢复",
            f"模型：{len(documents)}\n对齐句：{len(comparison.rows)}\n"
            f"重新绑定图片：{rebind.get('rebound', 0)}\n\n"
            "已直接恢复 OCR 文字、物理列、候选和人工选择，没有重新运行 OCR。",
        )

    def _capture_current_fusion_selection_records(self) -> dict[tuple[str, ...], dict]:
        """Capture selected text *and* deletion/provenance for crash-safe recovery."""
        records: dict[tuple[str, ...], dict] = {}
        if self._comparison is None:
            return records
        for row, state in zip(self._comparison.rows, self._fusion_states):
            selected = state.selected_index
            if selected is None or not 0 <= selected < len(state.candidates):
                continue
            candidate = state.candidates[selected]
            key = tuple(str(item) for item in (row.column_ids or ()) if str(item))
            if not key:
                continue
            records[key] = {
                "column_ids": list(key),
                "text": str(getattr(candidate, "text", "") or ""),
                "delete_intentionally": bool(getattr(candidate, "delete_intentionally", False)),
                "display_label": str(getattr(candidate, "display_label", "") or ""),
                "reason": str(getattr(candidate, "reason", "") or ""),
                "confidence": float(getattr(candidate, "confidence", 0.0) or 0.0),
                "selection_origin": str(getattr(state, "selection_origin", "") or ""),
            }
        return records

    def _capture_current_fusion_selections(self) -> dict[tuple[str, ...], str]:
        """Legacy text-only view retained for old recovery/import callers."""
        return {
            key: str(record.get("text", "") or "")
            for key, record in self._capture_current_fusion_selection_records().items()
            if str(record.get("text", "") or "")
        }

    def _replace_multi_source_workspace(
        self, documents, comparison, *, preserve_selections=None,
        preserve_selection_records=None, prepared=None, fusion_states=None
    ):
        self._documents = list(documents)
        self._primary_doc = self._documents[0] if self._documents else None
        self._comparison = comparison
        if prepared is None:
            prepared = [
                "\n".join(str(row.texts[index] if index < len(row.texts) else "") for row in comparison.rows)
                for index in range(len(self._documents))
            ]
        else:
            prepared = list(prepared)
        self._set_full_source_texts(prepared)
        self._loading_text = True
        try:
            for index, editor in enumerate(self._source_editors):
                visible = index < len(self._documents)
                self._source_panels[index].setVisible(visible)
                if not visible:
                    editor.clear()
                    continue
                editor.setUpdatesEnabled(False)
                try:
                    editor.setReadOnly(self._single_card_enabled)
                    editor.setPlainText(
                        self._source_line_text(index, self._current_row_index)
                        if self._single_card_enabled else self._source_text(index)
                    )
                finally:
                    editor.setUpdatesEnabled(True)
        finally:
            self._loading_text = False
        self._sources_dirty = False
        self._set_source_labels_for_mode()
        if fusion_states is None:
            self._rebuild_fusion_rows(auto_choose=False)
        else:
            self._clear_fusion_widgets()
            self._fusion_states = list(fusion_states)
            self._render_fusion_window(self._current_row_index, force=True)
            self._update_unresolved_summary()
        preserved = 0
        from engine.ocr_compare_view_model import upsert_external_candidate
        record_map = dict(preserve_selection_records or {})
        for key, text in (preserve_selections or {}).items():
            record_map.setdefault(key, {"text": str(text or "")})
        for row, state in zip(self._comparison.rows, self._fusion_states):
            key = tuple(str(item) for item in (row.column_ids or ()) if str(item))
            record = record_map.get(key)
            if not isinstance(record, dict):
                continue
            selected_text = str(record.get("text", "") or "")
            delete_intentionally = bool(record.get("delete_intentionally", False))
            display_label = str(record.get("display_label", "") or "恢复的人工融合结果")
            reason = str(record.get("reason", "") or "从逐源纠错恢复会话中的已选融合结果重建。")
            confidence = float(record.get("confidence", 1.0) or 0.0)
            selection_origin = str(record.get("selection_origin", "") or "restored_human")
            if selected_text and state.choose_text(selected_text, origin=selection_origin):
                preserved += 1
                continue
            if upsert_external_candidate(
                state, selected_text,
                display_label=display_label,
                select=True,
                reason=reason,
                confidence=confidence,
                allow_empty=delete_intentionally,
                force_role_candidate=True,
                selection_origin=selection_origin,
            ) is not None:
                preserved += 1
        self._render_fusion_window(self._current_row_index, force=True)
        self._refresh_source_highlights()
        self._update_unresolved_summary()
        if self._comparison.rows:
            self._select_row(min(self._current_row_index, len(self._comparison.rows) - 1))
        return preserved

    def _import_model_source_correction_result(self):
        if self._comparison is None or len(self._documents) < 2:
            QMessageBox.warning(self, "没有多模型结果", "请先完成多模型 OCR。")
            return
        if self._source_correction_busy or self._ai_import_busy:
            QMessageBox.information(self, "任务进行中", "当前已有逐源纠错或 AI 导入任务在后台执行。")
            return
        path, _ = QFileDialog.getOpenFileName(
            self, "导入 AI OCR 裁决结果", "",
            "AI OCR 裁决/旧逐模型结果 (*.json *.zip);;JSON (*.json);;ZIP (*.zip)",
        )
        if not path:
            return
        if not self._alignment_counts_valid(show_warning=False):
            QMessageBox.warning(self, "无法导入", "当前 OCR 行数与对齐不一致，请先点击“重新对齐”。")
            return
        # Import is an overlay operation, so it can validate against the existing
        # immutable comparison directly.  Avoid the former GUI-thread deep copy
        # of thousands of rows and full-text editor reads before the worker starts.
        comparison = self._comparison
        token = self._source_correction_generation.begin()
        signals = WorkerSignals()
        self._source_correction_signal_refs[token] = signals
        signals.phase_progress.connect(
            lambda stage, current, total, t=token: self._on_source_correction_progress(t, stage, current, total)
        )
        signals.error.connect(
            lambda message, t=token: self._on_source_correction_error(t, "导入 AI OCR 裁决失败", message)
        )
        signals.finished.connect(lambda result, t=token: self._on_source_correction_import_ready(t, result))
        # Keep the original model objects and the current alignment by reference.
        # The worker only validates the package and derives lightweight overlay
        # decisions; it never clones books, rewrites OCR, or realigns rows.
        documents = list(self._documents)
        labels = list(self._labels)
        source_path = str(path)
        self._set_source_correction_busy(
            True,
            "正在后台校验 AI 纠错并建立非破坏式融合覆盖；原始 OCR 和当前分歧保持不变…",
            lock_workspace=False,
        )

        def worker():
            try:
                from engine.multi_ocr_source_correction import import_source_corrections

                def progress(stage, current, total):
                    signals.phase_progress.emit(stage, current, total)

                _same_documents, _same_comparison, report = import_source_corrections(
                    source_path, documents, labels, comparison, progress_callback=progress,
                )
                decisions = [
                    item for item in (report.get("canonical_decisions") or [])
                    if isinstance(item, dict)
                ]
                signals.finished.emit({
                    "report": report,
                    "canonical_decisions": decisions,
                })
            except Exception as exc:
                signals.error.emit(str(exc))

        threading.Thread(
            target=worker, name=f"source-correction-import-{token}", daemon=True,
        ).start()

    def _on_source_correction_import_ready(self, token: int, result: object):
        self._source_correction_signal_refs.pop(token, None)
        if not self._source_correction_generation.is_current(token):
            return
        if not isinstance(result, dict):
            self._on_source_correction_error(token, "导入 AI OCR 裁决失败", "后台导入没有返回有效结果。")
            return
        try:
            report = dict(result.get("report") or {})
            decisions = [
                item for item in (
                    result.get("canonical_decisions")
                    or report.get("canonical_decisions")
                    or []
                ) if isinstance(item, dict)
            ]
            from engine.multi_ocr_source_correction import (
                apply_canonical_decisions_to_fusion_states, merge_canonical_decision_overlays,
            )
            existing_decisions = [dict(item) for item in self._canonical_source_decisions.values()]
            merged_decisions, merge_stats = merge_canonical_decision_overlays(existing_decisions, decisions)
            effective_decisions = [
                dict(item) for item in (merge_stats.get("changed_accepted_decisions") or [])
                if isinstance(item, dict)
            ]
            affected_keys = {
                tuple(str(value) for value in (item.get("column_ids") or []) if str(value))
                for item in effective_decisions
            }
            preserved = sum(
                1
                for row, state in zip(self._comparison.rows, self._fusion_states)
                if state.selected_index is not None
                and tuple(str(value) for value in (row.column_ids or ()) if str(value)) not in affected_keys
            )
            self._canonical_source_decisions = {
                tuple(str(value) for value in (item.get("column_ids") or []) if str(value)): dict(item)
                for item in merged_decisions if item.get("column_ids")
            }
            # Only newly accepted or genuinely improved rows are selected again.
            # Re-importing an identical package is idempotent and cannot steal a
            # later manual selection; unresolved later rows keep prior good AI.
            overlay_applied = apply_canonical_decisions_to_fusion_states(
                self._fusion_states, self._comparison, effective_decisions,
            )
            # Only the virtualised judgement window is rebuilt.  The three OCR
            # documents, source editors, alignment and full-text buffers are left
            # untouched, eliminating the former post-import freeze.
            self._render_fusion_window(self._current_row_index, force=True)
            self._update_unresolved_summary()
            if self._comparison.rows:
                self._select_row(min(self._current_row_index, len(self._comparison.rows) - 1))
        except Exception as exc:
            self._on_source_correction_error(token, "载入 AI 纠错覆盖失败", str(exc))
            return
        package_id = str(report.get("package_id", "") or "")
        duplicate_package = bool(package_id and package_id in self._source_correction_imported_package_ids)
        if package_id:
            self._source_correction_imported_package_ids.add(package_id)
        history_entry = {
            "package_id": package_id,
            "accepted_in_package": int(report.get("accepted_canonical_decisions", 0) or 0),
            "new_accepted": int(merge_stats.get("new_accepted_rows", 0) or 0),
            "replaced_accepted": int(merge_stats.get("replaced_accepted_rows", 0) or 0),
            "preserved_prior": int(merge_stats.get("preserved_prior_rows", 0) or 0),
            "effective_applied": int(overlay_applied or 0),
            "duplicate_package": duplicate_package,
        }
        if not duplicate_package:
            self._source_correction_import_history.append(history_entry)
        # Persist cumulative audit state for later fusion/skeleton exports.
        report["cumulative_import_count"] = len(self._source_correction_import_history)
        report["cumulative_canonical_decisions"] = [
            dict(item) for item in self._canonical_source_decisions.values()
        ]
        report["cumulative_accepted_canonical_decisions"] = sum(
            1 for item in self._canonical_source_decisions.values()
            if str(item.get("status", "") or "") == "accepted"
        )
        report["cumulative_merge_stats"] = {
            key: value for key, value in merge_stats.items()
            if key != "changed_accepted_decisions"
        }
        report["cumulative_import_history"] = copy.deepcopy(self._source_correction_import_history)
        self._last_source_correction_report = report
        self._set_source_correction_busy(False)
        self._source_correction_progress.setValue(100)
        unresolved_decisions = int(report.get("unresolved_canonical_decisions", 0) or 0)
        legacy_migrated = int(report.get("legacy_migrated_accepted_decisions", 0) or 0)
        resumed_locked = int(report.get("prefilled_resolved_decisions", 0) or 0)
        proposed_cells = int(report.get("proposed_model_cells", 0) or 0)
        proposed_rows = int(report.get("proposed_model_rows", 0) or 0)
        normalized_provisional = int(report.get("normalized_legacy_provisional_rows", 0) or 0)
        visible_disagreements = int(report.get("resolved_history_rows_annotated", 0) or 0)
        import_rounds = len(self._source_correction_import_history)
        cumulative_accepted = sum(
            1 for item in self._canonical_source_decisions.values()
            if str(item.get("status", "") or "") == "accepted"
        )
        improved = int(merge_stats.get("replaced_accepted_rows", 0) or 0)
        newly_added = int(merge_stats.get("new_accepted_rows", 0) or 0)
        self._source_correction_state.setText(
            f"AI裁决累计 {import_rounds} 包 · 当前有效 {cumulative_accepted} · "
            f"本包新增 {newly_added} / 改进 {improved} · 待判断 {unresolved_decisions}"
        )
        self._summary.setText(
            f"AI OCR 裁决已累积合并：当前保留 {cumulative_accepted} 条有效 AI 裁决；"
            f"本包新增 {newly_added} 条、改进替换 {improved} 条。缺失/未决行不会清掉之前结果；"
            f"原三模型 OCR、物理列和对齐均未修改。"
        )
        # Notify downstream workspaces without replacing/copying model documents.
        # The MainWindow recognises the overlay flag and deliberately skips the
        # expensive restored-session path.
        self.multi_session_restored.emit({
            "documents": list(self._documents),
            "labels": list(self._labels),
            "comparison": self._comparison,
            "fused": None,
            "report": report,
        })
        validation_mode = str(report.get("identity_validation_mode", "") or "")
        if validation_mode == "stable_model_slot_column_ids_and_text_compatible":
            identity_note = (
                "\n当前块 ID、布局哈希或行分组与导出时不同；程序已按模型槽位、稳定物理列 ID "
                "和文本兼容度安全绑定，但仍未改写任何 OCR。"
            )
        else:
            identity_note = ""
        proposed_labels = [
            str(value) for value in (report.get("proposed_model_labels") or []) if str(value)
        ]
        proposed_text = "、".join(proposed_labels) or "无逐模型修改"
        merge_conflicts = int(report.get("three_way_merge_conflicts", 0) or 0)
        QMessageBox.information(
            self, "AI OCR 纠错已非破坏式导入",
            f"原始 OCR 实际回写：0 列 / 0 模型行\n"
            f"原始多模型对齐：保持不变\n"
            f"JSON 中逐模型修改建议：{proposed_cells} 列 / {proposed_rows} 模型行\n"
            f"涉及模型：{proposed_text}\n"
            f"本次真正新增/改进并采用 AI 候选：{overlay_applied}\n"
            f"累计导入 AI 裁决包：{import_rounds}\n"
            f"当前累计有效 AI 裁决：{cumulative_accepted}\n"
            f"本包新增裁决：{newly_added}；改进替换：{improved}\n"
            f"继续可见的原始分歧：{visible_disagreements}\n"
            f"三方证据冲突（仅报告，不覆盖）：{merge_conflicts}\n"
            f"旧逐模型结果安全迁移：{legacy_migrated}\n"
            f"旧式共同候选自动恢复：{normalized_provisional}\n"
            f"从续作包恢复的已完成裁决：{resumed_locked}\n"
            f"仍需最终判断：{unresolved_decisions}\n"
            f"拒绝占位符裁决：{report.get('rejected_placeholder_decisions', 0)}\n"
            f"拒绝可疑拉丁字母裁决：{report.get('rejected_suspicious_ascii_decisions', 0)}\n"
            f"保留未受影响人工选择：{preserved}\n"
            f"{identity_note}\n\n"
            "AI 结果按稳定列 ID 累积合并；后续已接受结果可替换同句旧 AI，未决结果不会反向清空。"
            "NDLOCR、48px、Apple Vision 等原文和原分歧始终保留。",
        )

    def _export_fusion_and_skeleton(self):
        if self._comparison is None or self._primary_doc is None or len(self._documents) < 2:
            QMessageBox.warning(self, "没有多模型结果", "请先完成多模型 OCR。")
            return
        try:
            package, _comparison = self._current_multi_package_for_external_repair()
        except Exception as exc:
            show_error_dialog(self, "无法准备融合结果", str(exc))
            return
        title = safe_result_filename(
            str(getattr(getattr(self._primary_doc, "metadata", None), "title", "") or ""),
            default="multi_ocr",
        )
        path, _ = QFileDialog.getSaveFileName(
            self,
            "导出融合结果与骨架 EPUB",
            f"{title}_融合结果与骨架EPUB.zip",
            "ZIP 包 (*.zip)",
        )
        if not path:
            return
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            from engine.multi_ocr_source_correction import export_fusion_and_skeleton_bundle
            report = export_fusion_and_skeleton_bundle(
                self._primary_doc,
                package,
                path,
                correction_audit=self._last_source_correction_report,
                vertical=True,
            )
        except Exception as exc:
            show_error_dialog(self, "导出融合结果与骨架 EPUB 失败", str(exc))
            return
        finally:
            QApplication.restoreOverrideCursor()
        QMessageBox.information(
            self,
            "融合结果与骨架 EPUB 已导出",
            f"正文条目：{report.get('row_count', 0)}\n"
            f"锁定 Ruby：{report.get('ruby_pair_count', 0)} 组"
            f"（{'开启' if report.get('ruby_enabled') else '关闭'}）\n"
            "已包含锁定 Ruby sidecar、AI 正文模板、最终 EPUB 构建器和 Ruby 验证器。\n"
            f"融合 JSON 和稳定 ID 骨架 EPUB 已打包：\n{report.get('path', path)}",
        )

    def _canonical_export_blockers(self, comparison) -> list[str]:
        """Block stale/unsafe derivative text before EPUB or AI-package export."""
        from engine.multi_ocr_source_correction import canonical_text_safety_issues

        blockers: list[str] = []
        if len(comparison.rows) != len(self._fusion_states):
            blockers.append(
                f"融合状态行数 {len(self._fusion_states)} 与当前对齐行数 {len(comparison.rows)} 不一致；"
                "请重新载入或重新对齐当前多模型会话"
            )
            return blockers
        for row_index, (row, state) in enumerate(zip(comparison.rows, self._fusion_states)):
            key = tuple(str(value) for value in (row.column_ids or ()))
            selected_index = getattr(state, "selected_index", None)
            if selected_index is not None and not 0 <= int(selected_index) < len(state.candidates):
                blockers.append(f"第 {row_index + 1} 句的候选索引已失效，请重新选择")
                continue
            selected_text = state.output_text()
            if bool(getattr(state, "unresolved", False)):
                classification = (
                    "两模型共同候选" if bool(getattr(row, "provisional_consensus", False))
                    else "OCR 真正分歧"
                )
                blockers.append(f"第 {row_index + 1} 句仍未完成 OCR 最终裁决（{classification}）")
                continue
            if not selected_text and not state.output_delete_intentionally():
                blockers.append(f"第 {row_index + 1} 句融合结果为空，且未标记为有意删除")
                continue
            for issue in canonical_text_safety_issues(selected_text):
                blockers.append(f"第 {row_index + 1} 句：{issue}")
            decision = self._canonical_source_decisions.get(key)
            if not decision or decision.get("status") != "accepted":
                continue
            final_text = str(decision.get("final_text", "") or "")
            if not final_text or selected_text == final_text:
                continue
            candidate = (
                state.candidates[state.selected_index]
                if state.selected_index is not None and 0 <= state.selected_index < len(state.candidates)
                else None
            )
            label = str(getattr(candidate, "display_label", "") or "")
            from engine.ocr_compare_view_model import selection_supersedes_ai_verdict
            explicit_override = selection_supersedes_ai_verdict(state, label)
            # Any candidate explicitly checked by the user—including an original
            # NDLOCR/48px/Apple candidate—is authoritative and may supersede the
            # imported AI verdict.  Only an untouched automatic baseline is stale.
            if not explicit_override and label not in {
                "图文对照人工校对", "恢复的人工融合结果", "人工最终裁决"
            }:
                blockers.append(
                    f"第 {row_index + 1} 句仍采用自动旧结果，未采用最新 AI 裁决；"
                    "可勾选任一候选作为人工最终选择"
                )
        return blockers

    def _current_multi_package_for_external_repair(self):
        """Create the current sealed package without changing active selections."""
        if self._comparison is None or len(self._documents) < 2 or self._primary_doc is None:
            raise ValueError("请先完成并载入多模型 OCR。")
        if self._sources_dirty and not self._alignment_counts_valid(show_warning=False):
            raise ValueError("各 OCR 栏的行数已改变，请先点击“重新对齐”。")
        comparison = self._comparison_with_current_source_texts()
        if comparison is None:
            raise ValueError("当前 OCR 对齐状态不完整。")
        blockers = self._canonical_export_blockers(comparison)
        if blockers:
            preview = "\n".join(f"• {value}" for value in blockers[:12])
            more = f"\n另有 {len(blockers) - 12} 项。" if len(blockers) > 12 else ""
            first = blockers[0]
            raise ValueError(
                "当前权威正文尚未通过导出前致命检查：\n" + preview + more
                + "\n请在 OCR 对比/图文对照中完成判断后再导出。"
                + f"\n首项阻断：{first}"
            )
        result_lines: list[str] = []
        delete_flags: list[bool] = []
        for row_index, state in enumerate(self._fusion_states):
            value = state.output_text()
            if state.selected_index is None and row_index < len(comparison.rows):
                value = comparison.rows[row_index].output_text
            result_lines.append(str(value or ""))
            delete_flags.append(state.output_delete_intentionally())
        from engine.ocr_roundtrip_package import export_multi_package
        package = export_multi_package(
            self._documents,
            self._labels,
            comparison,
            result_lines=result_lines,
            delete_flags=delete_flags,
            ruby_overlay_source=self._ruby_overlay_doc,
        )
        # AI 修复包只使用当前多模型 OCR、页面结构和原始出版图片。
        # 出版参考 EPUB 属于文字对比页的独立功能，不得被静默附加到
        # OCR 修复包，也不得成为导出的前置条件。
        package["canonical_text_authority"] = {
            "schema": "novel_formatter.canonical_text_authority.v1",
            "raw_ocr_documents_immutable": True,
            "decision_count": len(self._canonical_source_decisions),
            "decisions": [dict(item) for item in self._canonical_source_decisions.values()],
            "derivative_text_rebuilt_from_current_fusion_states": True,
        }
        package.pop("publication_reference", None)
        return package, comparison

    def _choose_ai_repair_reference_option(self, package: dict):
        """Choose package profile and optional publication evidence explicitly."""
        dialog = QDialog(self)
        dialog.setWindowTitle("AI 修复包导出选项")
        dialog.setModal(True)
        layout = QVBoxLayout(dialog)
        note = QLabel(
            "标准紧凑包保留完整融合证据、稳定正文、原子跨度、页面列总账、必要视觉证据和审计工具，"
            "但不重复保存同一份全文、页面上下文和出版图片。\n"
            "完整取证包用于调试分列与人工检查全部风险，文件数和体积会明显增加。"
        )
        note.setWordWrap(True)
        layout.addWidget(note)

        mode_row = QHBoxLayout()
        mode_row.addWidget(QLabel("AI 修复包模式："))
        mode_combo = NoWheelComboBox()
        mode_combo.addItem("V4 多模型分歧裁决包（默认推荐）", "disagreement_v4")
        mode_combo.addItem("V3 标准紧凑包（兼容）", "compact")
        mode_combo.addItem("V3 完整取证包（调试）", "forensic")
        mode_row.addWidget(mode_combo, 1)
        layout.addLayout(mode_row)
        estimate_label = QLabel()
        estimate_label.setWordWrap(True)
        layout.addWidget(estimate_label)

        include = QCheckBox("包含出版参考证据（可选，默认关闭）")
        layout.addWidget(include)
        path_row = QHBoxLayout()
        path_edit = QLineEdit()
        path_edit.setReadOnly(True)
        path_edit.setPlaceholderText("未选择出版参考 EPUB")
        browse = QPushButton("选择 EPUB…")
        path_row.addWidget(path_edit, 1)
        path_row.addWidget(browse)
        layout.addLayout(path_row)
        browse.setEnabled(False)
        path_edit.setEnabled(False)
        include.toggled.connect(browse.setEnabled)
        include.toggled.connect(path_edit.setEnabled)

        def choose_file():
            path, _ = QFileDialog.getOpenFileName(dialog, "选择出版参考 EPUB", "", "EPUB 电子书 (*.epub)")
            if path:
                path_edit.setText(path)
        browse.clicked.connect(choose_file)

        estimate_cache = {}
        def update_estimate():
            package_mode = str(mode_combo.currentData() or "disagreement_v4")
            try:
                if package_mode not in estimate_cache:
                    from engine.ai_publication_bundle_v2 import estimate_export_size
                    estimate_cache[package_mode] = estimate_export_size(package, package_mode=package_mode)
                estimate = estimate_cache[package_mode]
                estimate_label.setText(
                    f"预计导出：约 {estimate.get('estimated_zip_size_mb', 0)} MB；"
                    f"文件约 {estimate.get('estimated_file_count', 0)} 个；"
                    f"视觉复核页约 {estimate.get('visual_page_count', 0)} 页。"
                    "实际结果取决于页面几何核验和图片压缩率。"
                )
            except Exception as exc:
                estimate_label.setText(f"暂时无法预测体积：{exc}")
        mode_combo.currentIndexChanged.connect(update_estimate)
        update_estimate()

        buttons = QHBoxLayout()
        buttons.addStretch(1)
        cancel = QPushButton("取消")
        confirm = QPushButton("开始导出")
        buttons.addWidget(cancel)
        buttons.addWidget(confirm)
        layout.addLayout(buttons)
        cancel.clicked.connect(dialog.reject)

        def accept_dialog():
            if include.isChecked() and not path_edit.text().strip():
                QMessageBox.warning(dialog, "尚未选择 EPUB", "请先选择出版参考 EPUB，或取消勾选该选项。")
                return
            dialog.accept()
        confirm.clicked.connect(accept_dialog)
        if dialog.exec() != QDialog.Accepted:
            return None
        return (
            bool(include.isChecked()),
            path_edit.text().strip() or None,
            str(mode_combo.currentData() or "disagreement_v4"),
        )

    def _export_ai_repair_epub(self):
        # AI 修复包 v3 仍作为兼容导出选项；默认使用 V4 多模型分歧裁决包。
        if self._comparison is None or self._primary_doc is None or len(self._documents) < 2:
            QMessageBox.warning(self, "没有多模型结果", "请先完成多模型 OCR。")
            return
        mode = "one_pass"
        try:
            package, _comparison = self._current_multi_package_for_external_repair()
        except Exception as exc:
            show_error_dialog(self, "无法准备 AI 修复包", str(exc))
            return
        reference_option = self._choose_ai_repair_reference_option(package)
        if reference_option is None:
            return
        include_reference, reference_path, package_mode = reference_option
        parent = QFileDialog.getExistingDirectory(
            self,
            "选择 AI 修复包 V4 的保存位置",
            str(Path.home()),
        )
        if not parent:
            return
        title = "AI修复包"
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            from engine.ai_repair_epub import export_ai_publication_bundle
            report = export_ai_publication_bundle(
                self._primary_doc,
                package,
                parent,
                mode=mode,
                vertical=True,
                bundle_name=title,
                create_zip=True,
                include_publication_reference=include_reference,
                publication_reference_path=reference_path,
                package_mode=package_mode,
            )
        except Exception as exc:
            show_error_dialog(self, "导出 AI 修复包失败", str(exc))
            return
        finally:
            QApplication.restoreOverrideCursor()
        mode_value = str(report.get("package_mode", "") or "")
        mode_label = {
            "disagreement_v4": "V4 多模型分歧裁决包",
            "compact": "V3 标准紧凑包",
            "forensic": "V3 完整取证包",
        }.get(mode_value, mode_value or "AI 修复包")
        zip_path = Path(str(report.get("zip_path", "") or ""))
        zip_mb = round(zip_path.stat().st_size / (1024 * 1024), 1) if zip_path.is_file() else 0
        self._summary.setText(
            f"已导出 {mode_label}：{report.get('stable_item_count', 0)} 个正文条目，"
            f"锁定 {report.get('locked_consensus_count', 0)} 条、需复核 {report.get('review_required_count', 0)} 条，"
            f"视觉复核 {report.get('visual_evidence_page_count', 0)} 页，ZIP {zip_mb} MB。"
        )
        QMessageBox.information(
            self,
            "AI 修复包导出完成",
            f"模式：{mode_label}\n"
            f"文件夹：{report.get('folder', '')}\n"
            f"整包 ZIP：{report.get('zip_path', '')}\n"
            f"实际 ZIP：{zip_mb} MB\n\n"
            f"入口命令：{Path(report.get('guide', '')).name}\n"
            f"完整融合 JSON：{Path(report.get('fusion_json', '')).name}\n"
            f"结构预检：{Path(report.get('preflight', '')).name}\n"
            f"独立重建源：{Path(report.get('rebuild_source', '')).name}\n"
            f"框架 EPUB：{Path(report.get('primary_framework_epub', report.get('framework_epub', ''))).name}\n"
            f"建议最终文件名：{report.get('final_output_name', '')}\n\n"
            f"正文条目：{report.get('editable_count', 0)}\n"
            f"逻辑章节：{report.get('chapter_count', 0)}\n"
            f"成品图片：{report.get('publication_resource_count', 0)}\n"
            f"锁定一致条目：{report.get('locked_consensus_count', 0)}\n"
            f"需要文字复核：{report.get('review_required_count', 0)}\n"
            f"原子跨度：{report.get('atomic_span_count', 0)}\n"
            f"独立插图页：{report.get('standalone_image_xhtml_count', 0)}\n"
            f"视觉证据页：{report.get('visual_evidence_page_count', 0)}\n"
            f"视觉图片文件：{report.get('visual_evidence_file_count', 0)}\n"
            f"选择性视觉裁切记录：{report.get('visual_evidence_exported_crop_count', 0)}\n"
            f"致命未映射正文列：{report.get('fatal_unmapped_body_slot_count', 0)}\n"
            f"出版参考证据：{'已显式包含' if report.get('publication_reference_included') else '未包含'}\n\n"
            + ("上传整个 ZIP。大模型只能裁决 03_conflict_items.jsonl 中的 ID，必须运行 "
             "tools/apply_decisions.py 和 tools/validate_epub.py，并交付最终 EPUB 与审计文件。"
             if mode_value == "disagreement_v4" else
             "上传整个 ZIP。12_stable_text_map.jsonl 是唯一默认文字母本；full_fusion_evidence.json 完整融合证据只保存一次。"
             "大模型必须运行 tools/validate_final_epub.py，并同时交付最终 EPUB 与完整审计文件。"),
        )

    def _import_ai_repair_result(self):
        if self._comparison is None or self._primary_doc is None or len(self._documents) < 2:
            QMessageBox.warning(self, "没有多模型结果", "请先载入与修复文件对应的多模型 OCR。")
            return
        path, _ = QFileDialog.getOpenFileName(
            self,
            "导入外部 AI 修复结果（推荐稀疏 JSON）",
            "",
            "推荐：稀疏 JSON (*.json);;兼容：AI 修复 EPUB (*.epub);;全部支持格式 (*.json *.epub)",
        )
        if not path:
            return
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            package, _comparison = self._current_multi_package_for_external_repair()
            from engine.ai_repair_epub import load_ai_repair_result
            updates, report = load_ai_repair_result(path, expected_package=package)
            from engine.ocr_compare_view_model import upsert_external_candidate
            row_to_index = {
                str(item.get("row_id") or item.get("item_id") or ""): index
                for index, item in enumerate(package.get("editable_items") or [])
            }
            applied = 0
            review_only = 0
            for update in updates:
                row_index = row_to_index.get(str(update.get("item_id", "") or ""))
                if row_index is None or row_index >= len(self._fusion_states):
                    continue
                needs_review = bool(update.get("needs_review", False))
                reason = str(update.get("reason", "") or "")
                evidence = update.get("evidence") or []
                audit_flags = list(update.get("audit_flags") or [])
                baseline_status = str(update.get("baseline_status", "") or "")
                transaction_id = str(update.get("transaction_id", "") or "")
                if evidence:
                    reason = (reason + "；证据：" + "、".join(str(value) for value in evidence)).strip("；")
                if baseline_status == "stale_conflict":
                    reason = (reason + "；导出后本地同一区域已修改，结果已过期，禁止自动选择").strip("；")
                elif baseline_status == "baseline_mismatch_no_text":
                    reason = (reason + "；基线哈希已过期且结果未携带 baseline_text，无法三方合并").strip("；")
                elif baseline_status == "auto_merged_non_overlapping":
                    reason = (reason + "；已生成非重叠三方合并候选，请人工确认").strip("；")
                if audit_flags:
                    reason = (reason + "；审计：" + "、".join(str(value) for value in audit_flags)).strip("；")
                state = self._fusion_states[row_index]
                previous_selected = state.selected_index
                confidence_value = update.get("confidence", 0.0)
                confidence_labels = {
                    "exact_reference": 1.0,
                    "high_consensus": 0.95,
                    "medium_context": 0.75,
                    "low_uncertain": 0.4,
                    "external_epub_edit": 0.7,
                }
                if isinstance(confidence_value, str) and confidence_value in confidence_labels:
                    confidence_value = confidence_labels[confidence_value]
                try:
                    confidence_value = float(confidence_value or 0.0)
                except (TypeError, ValueError, OverflowError):
                    confidence_value = 0.0
                audit_level = str(update.get("audit_level", "") or "")
                if transaction_id:
                    display_label = "外部AI跨条目事务（成组选择）"
                elif baseline_status in {"stale_conflict", "baseline_mismatch_no_text"} or audit_level == "high_risk":
                    display_label = "外部AI高风险建议（待人工）"
                elif baseline_status == "auto_merged_non_overlapping":
                    display_label = "外部AI三方合并建议（待人工）"
                else:
                    display_label = "外部AI修复建议（待人工）" if needs_review else "外部AI修复结果"
                upsert_external_candidate(
                    state,
                    str(update.get("edited_text", "") or ""),
                    display_label=display_label,
                    select=not needs_review,
                    confidence=confidence_value,
                    reason=reason,
                    allow_empty=bool(update.get("delete_intentionally", False)),
                    transaction_id=transaction_id,
                    transaction_operation=str(update.get("transaction_operation", "") or ""),
                    transaction_member_ids=list(update.get("transaction_member_ids") or []),
                    audit_level=audit_level,
                    audit_flags=audit_flags,
                    selection_origin=("ai_adjudication_result" if not needs_review else ""),
                )
                if needs_review:
                    state.selected_index = previous_selected
                    state.review_indices = state._build_review_indices()
                if needs_review:
                    review_only += 1
                else:
                    applied += 1
        except Exception as exc:
            show_error_dialog(self, "导入 AI 修复结果失败", str(exc))
            return
        finally:
            QApplication.restoreOverrideCursor()
        self._render_fusion_window(self._current_row_index, force=True)
        self._update_unresolved_summary()
        self._refresh_source_highlights()
        source_type = str(report.get("source_type", "") or "").upper()
        atomic_count = int(report.get("atomic_transaction_count", 0) or 0)
        stale_conflicts = int(report.get("stale_conflicts", 0) or 0)
        three_way_merges = int(report.get("three_way_merges", 0) or 0)
        self._summary.setText(
            f"已从 {source_type or 'AI修复文件'} 导入 {len(updates)} 条："
            f"自动选择 {applied}，待人工 {review_only}，原子事务 {atomic_count}，"
            f"过期冲突 {stale_conflicts}，三方合并 {three_way_merges}；原始 OCR 和结构未被覆盖。"
        )
        QMessageBox.information(
            self,
            "AI 修复结果已载入",
            f"读取修改：{len(updates)} 条\n"
            f"已选择：{applied} 条\n"
            f"待人工：{review_only} 条\n"
            f"原子事务：{int(report.get('atomic_transaction_count', 0) or 0)} 组\n"
            f"过期冲突：{int(report.get('stale_conflicts', 0) or 0)} 条\n"
            f"三方合并：{int(report.get('three_way_merges', 0) or 0)} 条\n\n"
            "原子事务在任一成员上选择/撤销时会整组同步；确认后再点击“应用融合稿”。",
        )

    def _repair_multi_roundtrip_package(self):
        """Repair a legacy exported package without touching the active book."""
        from engine.ocr_roundtrip_package import (
            load_package,
            repair_multi_package_alignment,
            save_package,
        )
        path, _ = QFileDialog.getOpenFileName(
            self,
            "选择需要修复的旧版多模型 OCR 包",
            "",
            "OCR 校对包 (*.json *.md *.markdown)",
        )
        if not path:
            return
        source = Path(path)
        default_name = source.with_name(f"{source.stem}_对齐修复{source.suffix}")
        output, selected_filter = QFileDialog.getSaveFileName(
            self,
            "保存对齐修复包",
            str(default_name),
            "JSON 校对包 (*.json);;Markdown 校对包 (*.md)",
        )
        if not output:
            return
        if not Path(output).suffix:
            output += ".md" if "Markdown" in selected_filter else ".json"
        self._repair_ai_package_btn.setEnabled(False)
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            package = load_package(path)
            repaired, report = repair_multi_package_alignment(package)
            written = save_package(repaired, output)
        except Exception as exc:
            show_error_dialog(self, "修复旧版多模型对齐包失败", str(exc))
            return
        finally:
            QApplication.restoreOverrideCursor()
            self._repair_ai_package_btn.setEnabled(True)
        QMessageBox.information(
            self,
            "旧版对齐包修复完成",
            f"已修复 {int(report.get('repair_operations', 0) or 0)} 处相邻错位，"
            f"涉及 {int(report.get('repaired_rows', 0) or 0)} 行。\n"
            f"仍有 {int(report.get('remaining_empty_cells', 0) or 0)} 个单模型空白单元需要复核。\n"
            f"用户已修改的 edited_text 保留 {int(report.get('preserved_manual_edits', 0) or 0)} 行。\n\n"
            f"输出：{written}",
        )

    def _run_ai_adjudication(self):
        if self._comparison is None or len(self._documents) < 2 or self._primary_doc is None:
            QMessageBox.warning(self, "没有多模型结果", "请先完成多模型 OCR 并载入 OCR 对比。")
            return
        if self._ai_import_busy or self._source_correction_busy:
            QMessageBox.information(self, "任务进行中", "当前已有 AI 或逐源纠错任务，请稍候。")
            return
        if not self._alignment_counts_valid(show_warning=False):
            QMessageBox.information(self, "请先重新对齐", "各 OCR 栏行数已改变。请先点击“重新对齐”。")
            return
        settings = ensure_ai_settings(
            self,
            "请先在 AI 设置中选择服务商、模型并填写 API Key。AI 审定会强制 temperature=0、top_p=0.1，并使用结构化 JSON。",
        )
        if settings is None:
            return
        # OCR adjudication is deterministic extraction, not creative reasoning.
        # Keep the user's global AI profile untouched while disabling costly
        # DeepSeek thinking and bounding sparse JSON completion size here.
        from dataclasses import replace
        settings = replace(
            settings,
            temperature=0.0,
            json_mode=True,
            deepseek_thinking=False,
            max_tokens=max(2000, min(12000, int(getattr(settings, "max_tokens", 12000) or 12000))),
        )
        dialog = OCRAIAdjudicationDialog(self)
        if dialog.exec() != QDialog.Accepted:
            return
        config = dialog.values()

        comparison = self._comparison_with_current_source_texts()
        if comparison is None:
            QMessageBox.warning(self, "无法审定", "当前 OCR 对齐状态不完整。")
            return
        result_lines: list[str] = []
        delete_flags: list[bool] = []
        for row_index, state in enumerate(self._fusion_states):
            value = state.output_text()
            if state.selected_index is None and row_index < len(comparison.rows):
                value = comparison.rows[row_index].output_text
            result_lines.append(str(value or ""))
            delete_flags.append(state.output_delete_intentionally())

        token = self._ai_import_generation.begin()
        signals = WorkerSignals()
        self._ai_import_signal_refs[token] = signals
        cancel_event = threading.Event()
        self._ai_adjudication_cancel_event = cancel_event
        self._ai_adjudication_report = None
        self._ai_adjudication_output_paths = None
        signals.log.connect(lambda raw, t=token: self._on_ai_adjudication_progress(t, raw))
        signals.error.connect(lambda details, t=token: self._on_ai_adjudication_error(t, details))
        signals.finished.connect(lambda result, t=token: self._on_ai_adjudication_ready(t, result))
        self._ai_adjudication_progress.setValue(0)
        self._ai_adjudication_progress.setFormat("准备证据…")
        self._set_ai_import_busy(
            True,
            "正在本地整理风险条目、物理列、前后页上下文和出版参考摘录；一致低风险行不会发送给 AI…",
        )

        documents = list(self._documents)
        labels = list(self._labels)
        current_primary = self._primary_doc
        ruby_overlay_doc = self._ruby_overlay_doc
        title = safe_result_filename(
            str(getattr(getattr(self._primary_doc, "metadata", None), "title", "") or ""),
            default="multi_ocr",
        )

        def worker():
            try:
                from ai.provider_factory import create_provider
                from engine.ocr_ai_adjudicator import (
                    AdjudicationOptions,
                    adjudicate_package,
                    save_adjudication_outputs,
                )
                from engine.ocr_roundtrip_package import export_multi_package, import_multi_package
                from engine.ocr_compare_view_model import build_fusion_states, upsert_external_candidate

                package = export_multi_package(
                    documents,
                    labels,
                    comparison,
                    result_lines=result_lines,
                    delete_flags=delete_flags,
                    ruby_overlay_source=ruby_overlay_doc,
                )
                options = AdjudicationOptions(
                    batch_pages=int(config["batch_pages"]),
                    overlap_pages=int(config["overlap_pages"]),
                    risk_only=bool(config["risk_only"]),
                    independent_audit=bool(config["independent_audit"]),
                    request_retries=2,
                    max_prompt_tokens=int(config["max_prompt_tokens"]),
                    auto_apply_medium=bool(config["auto_apply_medium"]),
                )

                def report(event):
                    signals.log.emit(json.dumps(event, ensure_ascii=False))

                with create_provider(settings) as provider:
                    reviewed_package, audit_report = adjudicate_package(
                        provider,
                        package,
                        options=options,
                        reference_path=config["reference_path"],
                        glossary_path=config["glossary_path"],
                        progress_callback=report,
                        cancel_check=cancel_event.is_set,
                    )
                package_path, report_path = save_adjudication_outputs(
                    reviewed_package,
                    audit_report,
                    config["output_dir"],
                    base_name=title,
                )
                fused, imported_comparison, lines = import_multi_package(
                    reviewed_package,
                    current_primary=current_primary,
                )
                fusion_states = build_fusion_states(imported_comparison.rows, auto_choose=False)
                uncertain_ids = set(str(value) for value in (audit_report.get("low_uncertain") or []))
                report_by_id = {
                    str(entry.get("item_id", "") or ""): entry
                    for entry in (audit_report.get("items") or [])
                    if isinstance(entry, dict)
                }
                package_items = list(reviewed_package.get("editable_items") or [])
                if len(lines) == len(fusion_states):
                    for row_index, (state, text) in enumerate(zip(fusion_states, lines)):
                        row_id = str(package_items[row_index].get("row_id", "") or "") if row_index < len(package_items) else ""
                        report_entry = report_by_id.get(row_id, {})
                        if row_id in uncertain_ids:
                            proposed = str(report_entry.get("proposed_text", "") or "")
                            reason = str(report_entry.get("reason", "证据不足或独立审计未通过") or "")
                            # q/protocol failures have no actual proposal. Do not
                            # duplicate the original text as a fake AI candidate.
                            if proposed.strip() and proposed.strip() != state.output_text().strip():
                                upsert_external_candidate(
                                    state,
                                    proposed,
                                    display_label="AI审定建议（待人工）",
                                    select=False,
                                    reason=reason,
                                )
                            else:
                                state.selected_index = None
                                state.selection_origin = ""
                                state.review_indices = state._build_review_indices()
                            state.local_reocr_recommended = True
                            state.fusion_reason = reason or "AI审定未静默写入"
                            continue
                        # Rows absent from the sparse audit report were not
                        # changed by AI (including skipped low-risk rows). Keep
                        # their original model/character-fusion decision intact.
                        if not report_entry or bool(report_entry.get("needs_human_review", False)):
                            continue
                        before = str(report_entry.get("before", "") or "")
                        after = str(report_entry.get("after", text) or "")
                        if after == before and not bool(report_entry.get("delete_intentionally", False)):
                            continue
                        upsert_external_candidate(
                            state,
                            after,
                            display_label="AI审定结果",
                            select=True,
                            reason=str(report_entry.get("reason", "") or ""),
                            allow_empty=bool(report_entry.get("delete_intentionally", False)),
                            selection_origin="ai_adjudication_result",
                        )
                source_texts = [
                    "\n".join(row.texts[index] for row in imported_comparison.rows)
                    for index in range(len(imported_comparison.labels))
                ]
                signals.finished.emit({
                    "fused": fused,
                    "comparison": imported_comparison,
                    "lines": list(lines),
                    "fusion_states": fusion_states,
                    "source_texts": source_texts,
                    "path": str(package_path),
                    "ai_adjudication_report": audit_report,
                    "ai_adjudication_paths": (str(package_path), str(report_path)),
                })
            except Exception:
                import traceback
                signals.error.emit(traceback.format_exc())

        threading.Thread(
            target=worker,
            name=f"ocr-ai-adjudication-{token}",
            daemon=True,
        ).start()

    def _cancel_ai_adjudication(self):
        event = self._ai_adjudication_cancel_event
        if event is None:
            return
        event.set()
        self._ai_adjudication_cancel_btn.setEnabled(False)
        self._summary.setText("正在取消 AI 审定；已完成批次会被丢弃，不会写入半成品融合稿…")

    def _on_ai_adjudication_progress(self, token: int, raw: str) -> None:
        if not self._ai_import_generation.is_current(token):
            return
        try:
            event = json.loads(raw)
        except Exception:
            self._summary.setText(str(raw or "AI 审定中…"))
            return
        stage = str(event.get("stage", "AI 审定") or "AI 审定")
        current = int(event.get("current", 0) or 0)
        total = max(1, int(event.get("total", 1) or 1))
        value = min(99, max(0, int(current * 100 / total)))
        self._ai_adjudication_progress.setValue(value)
        self._ai_adjudication_progress.setFormat(f"{stage} {current}/{total}")
        page_start = int(event.get("page_start", 0) or 0)
        page_end = int(event.get("page_end", 0) or 0)
        page_note = f"；第 {page_start}–{page_end} 页" if page_start else ""
        token_estimate = int(event.get("estimated_tokens", 0) or 0)
        token_note = f"；本请求约 {token_estimate / 1000:.1f}k 输入 tokens" if token_estimate else ""
        target_rows = int(event.get("target_rows", 0) or 0)
        target_note = f"；风险条目 {target_rows}" if target_rows else ""
        self._summary.setText(f"AI OCR 审定：{stage} {current}/{total}{page_note}{target_note}{token_note}")

    def _on_ai_adjudication_error(self, token: int, details: str) -> None:
        self._ai_import_signal_refs.pop(token, None)
        if not self._ai_import_generation.is_current(token):
            return
        cancelled = self._ai_adjudication_cancel_event is not None and self._ai_adjudication_cancel_event.is_set()
        self._ai_adjudication_cancel_event = None
        self._ai_adjudication_progress.setVisible(False)
        self._ai_adjudication_cancel_btn.setVisible(False)
        self._set_ai_import_busy(False)
        if cancelled or "AdjudicationCancelled" in str(details):
            self._summary.setText("AI 审定已取消；当前融合稿没有被半途改写。")
            return
        show_error_dialog(self, "AI 审定融合稿失败", str(details or "未知错误"))

    def _on_ai_adjudication_ready(self, token: int, result: object) -> None:
        if not self._ai_import_generation.is_current(token):
            return
        if not isinstance(result, dict):
            self._on_ai_adjudication_error(token, "AI 审定后台没有返回有效结果。")
            return
        self._ai_adjudication_cancel_event = None
        self._ai_adjudication_cancel_btn.setVisible(False)
        self._ai_adjudication_progress.setValue(100)
        self._ai_adjudication_progress.setFormat("AI 审定与独立审计完成")
        self._ai_adjudication_report = result.get("ai_adjudication_report")
        paths = result.get("ai_adjudication_paths")
        if isinstance(paths, (list, tuple)) and len(paths) >= 2:
            self._ai_adjudication_output_paths = (str(paths[0]), str(paths[1]))
        self._on_ai_import_ready(token, result)

    def _set_ai_import_busy(self, busy: bool, message: str = "") -> None:
        self._ai_import_busy = bool(busy)
        multi_ready = self._mode == "multi" and self._comparison is not None
        enabled = multi_ready and not self._ai_import_busy
        for button in (
            self._auto_btn, self._realign_btn, self._export_texts_btn,
            self._export_ai_package_btn, self._export_ai_repair_epub_btn, self._import_ai_repair_result_btn,
            self._export_source_correction_btn, self._import_source_correction_btn, self._export_fusion_skeleton_btn,
            self._ai_adjudicate_btn, self._import_ai_package_btn, self._apply_btn,
        ):
            button.setEnabled(enabled)
        self._restore_btn.setEnabled(enabled and self._initial_payload is not None)
        self._repair_ai_package_btn.setEnabled(not self._ai_import_busy)
        self._single_import_btn.setEnabled(not self._ai_import_busy)
        running_adjudication = self._ai_adjudication_cancel_event is not None
        self._ai_adjudication_cancel_btn.setVisible(running_adjudication)
        self._ai_adjudication_cancel_btn.setEnabled(running_adjudication)
        self._ai_adjudication_progress.setVisible(running_adjudication)
        workspace_enabled = not self._ai_import_busy and not self._source_correction_lock_workspace
        self._source_area.setEnabled(workspace_enabled)
        self._result_panel.setEnabled(workspace_enabled)
        if message:
            self._summary.setText(message)

    def _import_multi_roundtrip_package(self):
        if self._primary_doc is None:
            QMessageBox.warning(self, "没有结构底稿", "请先载入当前书的多模型 OCR 结果。")
            return
        if self._ai_import_busy or self._source_correction_busy:
            QMessageBox.information(self, "正在导入", "当前已有多模型 AI 或逐源纠错任务，请稍候。")
            return
        path, _ = QFileDialog.getOpenFileName(
            self,
            "导入多模型 OCR 大模型融合包",
            "",
            "OCR 校对包 (*.json *.md *.markdown)",
        )
        if not path:
            return

        token = self._ai_import_generation.begin()
        signals = WorkerSignals()
        self._ai_import_signal_refs[token] = signals
        signals.log.connect(lambda text, t=token: self._on_ai_import_progress(t, text))
        signals.error.connect(lambda text, t=token: self._on_ai_import_error(t, text))
        signals.finished.connect(lambda result, t=token: self._on_ai_import_ready(t, result))
        current_primary = self._primary_doc
        source_path = str(path)
        self._set_ai_import_busy(
            True,
            "正在后台读取并校验多模型 AI 修订包；界面不会再因 20MB 以上 JSON 解析而无响应…",
        )

        def worker():
            try:
                from engine.ocr_roundtrip_package import import_multi_package, load_package
                from engine.ocr_compare_view_model import (
                    build_fusion_states,
                    upsert_external_candidate,
                )

                signals.log.emit("正在后台读取 JSON／Markdown…")
                package = load_package(source_path)
                signals.log.emit("正在校验 row ID、结构哈希、列 ID 和不可变清单…")
                fused, imported_comparison, lines = import_multi_package(
                    package,
                    current_primary=current_primary,
                )
                signals.log.emit("正在后台建立轻量候选状态…")
                fusion_states = build_fusion_states(
                    imported_comparison.rows,
                    auto_choose=False,
                )
                if len(lines) == len(fusion_states):
                    package_items = list(package.get("editable_items") or [])
                    for row_index, (state, text) in enumerate(zip(fusion_states, lines)):
                        delete_intentionally = (
                            package_items[row_index].get("delete_intentionally", False) is True
                        ) if row_index < len(package_items) else False
                        upsert_external_candidate(
                            state,
                            str(text or ""),
                            display_label="外部AI融合结果",
                            select=True,
                            allow_empty=delete_intentionally,
                            selection_origin="external_ai_package",
                        )
                source_texts = [
                    "\n".join(row.texts[index] for row in imported_comparison.rows)
                    for index in range(len(imported_comparison.labels))
                ]
                signals.finished.emit({
                    "fused": fused,
                    "comparison": imported_comparison,
                    "lines": list(lines),
                    "fusion_states": fusion_states,
                    "source_texts": source_texts,
                    "path": source_path,
                })
            except Exception as exc:
                signals.error.emit(str(exc))

        threading.Thread(
            target=worker,
            name=f"multi-ai-package-import-{token}",
            daemon=True,
        ).start()

    def _on_ai_import_progress(self, token: int, text: str) -> None:
        if not self._ai_import_generation.is_current(token):
            return
        self._summary.setText(str(text or "正在导入多模型 AI 包…"))

    def _on_ai_import_error(self, token: int, message: str) -> None:
        self._ai_import_signal_refs.pop(token, None)
        if not self._ai_import_generation.is_current(token):
            return
        self._set_ai_import_busy(False)
        show_error_dialog(self, "导入多模型 AI 融合包失败", str(message or "未知错误"))

    def _on_ai_import_ready(self, token: int, result: object) -> None:
        self._ai_import_signal_refs.pop(token, None)
        if not self._ai_import_generation.is_current(token):
            return
        if not isinstance(result, dict):
            self._on_ai_import_error(token, "后台导入没有返回有效结果。")
            return
        imported_comparison = result.get("comparison")
        lines = list(result.get("lines") or [])
        if imported_comparison is None or not lines:
            self._on_ai_import_error(token, "AI 修订包没有可应用的逐句结果。")
            return

        restore_comparison = (
            len(getattr(imported_comparison, "labels", []) or []) == len(self._documents)
        )
        self._pending_ai_import_apply = {
            "token": token,
            "result": result,
            "restore_comparison": restore_comparison,
            "editor_index": 0,
        }
        if restore_comparison:
            self._comparison = imported_comparison
            self._labels = list(imported_comparison.labels)
            imported_source_texts = [str(value or "") for value in (result.get("source_texts") or [])]
            while len(imported_source_texts) < len(self._documents):
                imported_source_texts.append("")
            self._set_full_source_texts(imported_source_texts)
        self._summary.setText("校验完成，正在分批刷新 OCR 对比界面…")
        QTimer.singleShot(0, self._apply_next_ai_import_editor)

    def _apply_next_ai_import_editor(self) -> None:
        pending = self._pending_ai_import_apply
        if not isinstance(pending, dict):
            return
        token = int(pending.get("token", -1))
        if not self._ai_import_generation.is_current(token):
            self._pending_ai_import_apply = None
            return
        if not pending.get("restore_comparison"):
            self._complete_ai_import_apply()
            return

        index = int(pending.get("editor_index", 0) or 0)
        if index >= len(self._documents):
            self._complete_ai_import_apply()
            return
        pending["editor_index"] = index + 1
        editor = self._source_editors[index]
        target_text = (
            self._source_line_text(index, self._current_row())
            if self._single_card_enabled
            else self._source_text(index)
        )
        # The common case (same exported package, only edited_text changed)
        # avoids rebuilding QTextDocument entirely.
        if editor.toPlainText() != target_text:
            self._loading_text = True
            editor.setUpdatesEnabled(False)
            try:
                editor.setReadOnly(self._single_card_enabled)
                editor.setPlainText(target_text)
            finally:
                editor.setUpdatesEnabled(True)
                self._loading_text = False
        self._summary.setText(
            f"正在刷新模型栏 {index + 1}/{len(self._documents)}；其余步骤继续在事件循环间隙执行…"
        )
        QTimer.singleShot(0, self._apply_next_ai_import_editor)

    def _complete_ai_import_apply(self) -> None:
        pending = self._pending_ai_import_apply
        self._pending_ai_import_apply = None
        if not isinstance(pending, dict):
            return
        token = int(pending.get("token", -1))
        if not self._ai_import_generation.is_current(token):
            return
        result = pending.get("result") or {}
        imported_comparison = result.get("comparison")
        lines = list(result.get("lines") or [])
        restore_comparison = bool(pending.get("restore_comparison"))

        if restore_comparison:
            self._fusion_states = list(result.get("fusion_states") or [])
            self._sources_dirty = False
            self._set_source_labels_for_mode()
        elif len(lines) == len(self._fusion_states):
            from engine.ocr_compare_view_model import upsert_external_candidate
            for state, text in zip(self._fusion_states, lines):
                upsert_external_candidate(
                    state,
                    str(text or ""),
                    display_label="外部AI融合结果",
                    select=True,
                    selection_origin="external_ai_package",
                )

        current = min(self._current_row(), max(0, len(self._fusion_states) - 1))
        self._clear_fusion_widgets()
        self._render_fusion_window(current, force=True)
        if self._single_card_enabled:
            self._update_single_card_source_preview(current, force=True)
        self._refresh_source_highlights()
        self._update_unresolved_summary()
        if self._fusion_states:
            self._select_row(current)

        fused = result.get("fused")
        repair_count = int(getattr(imported_comparison, "alignment_shift_repairs", 0) or 0)
        empty_count = int(getattr(imported_comparison, "unresolved_empty_cells", 0) or 0)
        repair_note = f"；已自动复位旧版相邻句错位 {repair_count} 处" if repair_count else ""
        empty_note = f"；仍有 {empty_count} 处单模型物理列为空，已标为低置信复核" if empty_count else ""
        adjudication_report = result.get("ai_adjudication_report")
        adjudication_paths = result.get("ai_adjudication_paths")
        self._set_ai_import_busy(False)
        if isinstance(adjudication_report, dict):
            stats = adjudication_report.get("stats") or {}
            usage = adjudication_report.get("usage") or {}
            applied = int(stats.get("applied_changes", 0) or 0)
            uncertain = int(stats.get("uncertain_items", 0) or 0)
            targets = int(stats.get("target_items", 0) or 0)
            skipped = int(stats.get("skipped_low_risk", 0) or 0)
            token_total = int(usage.get("total_tokens", 0) or 0)
            token_note = f"；API 用量 {token_total / 1000:.1f}k tokens" if token_total else ""
            mode = str(adjudication_report.get("mode", "") or "")
            mode_note = "出版参考真值模式" if mode == "reference_truth" else "无参考版高精度候选模式"
            self._summary.setText(
                f"✅ AI 审定完成：风险条目 {targets}，自动采用 {applied}，保留人工复核 {uncertain}，"
                f"跳过低风险一致项 {skipped}；{mode_note}{token_note}。结构与物理列未改变。"
            )
        else:
            self._summary.setText(
                f"✅ 已严格导入外部大模型融合包：{len(lines)} 句均按 row ID 完整覆盖；"
                f"原始多模型候选、封面、插图、目录、坐标和列 ID 保持不变{repair_note}{empty_note}。"
            )
        if fused is not None:
            self.doc_applied.emit(fused)

        if isinstance(adjudication_report, dict):
            stats = adjudication_report.get("stats") or {}
            paths = list(adjudication_paths or []) if isinstance(adjudication_paths, (list, tuple)) else []
            detail_lines = [
                f"AI 仅处理了 {int(stats.get('target_items', 0) or 0)} 个风险条目；"
                f"{int(stats.get('skipped_low_risk', 0) or 0)} 个一致低风险条目未发送，节省 tokens。",
                f"自动写入 {int(stats.get('applied_changes', 0) or 0)} 处；"
                f"{int(stats.get('uncertain_items', 0) or 0)} 处证据不足或审计失败，仍保留原融合稿等待人工复核。",
                "校订模型只返回稀疏 edited_text；独立审计不读取第一遍解释，且所有结果均通过本地长度、语言和来源覆盖检查。",
                "row ID、block ID、页码、坐标、物理列、封面、插图、目录和 EPUB 结构均由程序锁定。",
            ]
            if paths:
                detail_lines.append(f"审定融合包：{paths[0]}")
                if len(paths) > 1:
                    detail_lines.append(f"审计报告：{paths[1]}")
            if adjudication_report.get("mode") != "reference_truth":
                detail_lines.append("未提供出版版真值：本结果只称为高精度融合候选，不声称出版级或 100% 准确。")
            QMessageBox.information(self, "AI 审定融合稿已应用", "\n".join(detail_lines))
        else:
            detail_lines = [
                "大模型结果已完全替换融合正文并进入 Formatter、文本替换、文本对比和 EPUB。",
                "JSON 读取、结构校验和候选状态构建均在后台完成；模型栏按事件循环分批刷新。",
                "导入按 row ID 写回，不执行全文替换，因此不会产生重复替换。",
            ]
            if repair_count:
                detail_lines.append(f"检测并修复了 {repair_count} 处旧版相邻句错位。")
            if empty_count:
                detail_lines.append(f"仍有 {empty_count} 处仅一个模型识别到文字，已保留并标记为低置信候选。")
            QMessageBox.information(self, "多模型 AI 融合包已应用", "\n".join(detail_lines))

    def _export_separate_texts(self):
        if self._comparison is None or not self._documents:
            QMessageBox.warning(self, "没有结果", "请先运行多模型 OCR。")
            return
        target_dir = QFileDialog.getExistingDirectory(self, "选择分别导出 OCR 文本的文件夹")
        if not target_dir:
            return
        folder = Path(target_dir)
        title = safe_result_filename(
            str(getattr(getattr(self._primary_doc, "metadata", None), "title", "") or ""),
            default="ocr_compare",
        )
        written: list[Path] = []
        try:
            self._sync_full_source_cache_from_editors()
            for index, editor in enumerate(self._source_editors[:len(self._documents)]):
                label = self._labels[index] if index < len(self._labels) else f"模型{index + 1}"
                label_stem = safe_result_filename(label, default=f"模型{index + 1}")
                path = folder / f"{title}_{index + 1:02d}_{label_stem}.txt"
                text = self._source_text(index).replace("\r\n", "\n").replace("\r", "\n")
                if text and not text.endswith("\n"):
                    text += "\n"
                self._atomic_write_utf8(path, text)
                written.append(path)

            unresolved = [state for state in self._fusion_states if state.unresolved]
            if not unresolved and not self._sources_dirty and self._alignment_counts_valid(show_warning=False):
                fused_text = "\n".join(state.output_text() for state in self._fusion_states)
                if fused_text and not fused_text.endswith("\n"):
                    fused_text += "\n"
                fused_path = folder / f"{title}_融合结果.txt"
                self._atomic_write_utf8(fused_path, fused_text)
                written.append(fused_path)

        except Exception as exc:
            show_error_dialog(self, "分别导出文本失败", str(exc))
            return

        note = ""
        if any(state.unresolved for state in self._fusion_states):
            note = "\n融合稿仍有未选择候选，本次只导出了各 OCR 原文。"
        elif self._sources_dirty:
            note = "\n源 OCR 尚未重新对齐，本次只导出了各 OCR 原文。"
        QMessageBox.information(
            self,
            "分别导出完成",
            f"已导出 {len(written)} 个 UTF-8 文本文件到：\n{folder}{note}",
        )

    def _jump_conflict(self, direction: int, include_current: bool = False):
        if self._comparison is None or not self._comparison.rows:
            return
        current = self._current_row()
        total = len(self._comparison.rows)
        start = 0 if include_current else 1
        for offset in range(start, total + 1):
            index = (current + direction * offset) % total
            unresolved = index < len(self._fusion_states) and self._fusion_states[index].unresolved
            row = self._comparison.rows[index]
            review_risk = bool(
                row.is_conflict
                or getattr(row, "historical_ocr_disagreement", False)
            )
            if unresolved or (not self._review_only_enabled and review_risk):
                self._select_row(index)
                return
        self._summary.setText("当前没有需要跳转的未决分歧或已保留历史分歧。")

    @staticmethod
    def _reattach_ruby_overlay(overlay, target) -> int:
        """Compatibility wrapper around the central Ruby side-channel API."""
        if overlay is None or target is None:
            return 0
        from adapters.findtext_centernet_ruby import apply_ruby_overlay
        report = apply_ruby_overlay(target, overlay)
        return int(report.get("target_blocks", 0) or 0)

    def _update_unresolved_summary(self):
        unresolved = sum(1 for state in self._fusion_states if state.unresolved)
        if self._comparison is not None:
            self._apply_btn.setText(
                "✓ 应用融合稿" if not unresolved else f"✓ 应用融合稿（待选 {unresolved}）"
            )
        total = len(self._fusion_states)
        self._virtual_hint.setText(
            f"待判断 {unresolved} 句 · 全部 {total} 句"
            if self._review_only_enabled
            else f"全部 {total} 句"
        )
        self._refresh_decision_queue(force=False)
        if hasattr(self, "_prev_group_btn"):
            self._prev_group_btn.setEnabled(unresolved > 0)
        if hasattr(self, "_next_group_btn"):
            self._next_group_btn.setEnabled(unresolved > 0)

    def _apply_result(self):
        if self._mode == "single":
            if self._single_doc is None:
                QMessageBox.warning(self, "没有单 OCR 结果", "请先从 OCR 识别载入结果。")
                return
            self.single_doc_applied.emit(self._single_doc)
            self._summary.setText("已将当前单 OCR 结果应用到工作流；来源仍保留在 OCR 对比页。")
            QMessageBox.information(
                self, "单 OCR 结果已应用",
                "当前单 OCR 结果已进入 Formatter、文本替换、文本对比、图文对照和 EPUB。",
            )
            return
        if self._comparison is None or self._primary_doc is None:
            QMessageBox.warning(self, "没有结果", "请先运行多模型 OCR。")
            return
        if self._sources_dirty or not self._alignment_counts_valid(show_warning=False):
            self._realign_and_auto()
            QMessageBox.information(
                self, "已重新对齐",
                "源 OCR 的修改已经重新对齐并重建候选。请重新确认冲突句后再应用。",
            )
            return
        unresolved = [state.row_index for state in self._fusion_states if state.unresolved]
        if unresolved:
            self._select_row(unresolved[0])
            QMessageBox.warning(
                self, "仍有未选择候选",
                f"还有 {len(unresolved)} 句没有打钩选择。已跳到第一处；选择后其他候选会消失且不留空行。",
            )
            return
        lines = [state.output_text() for state in self._fusion_states]
        delete_flags = [state.output_delete_intentionally() for state in self._fusion_states]
        comparison_for_apply = copy.deepcopy(self._comparison)
        for row_index, row in enumerate(comparison_for_apply.rows):
            row.texts[:len(self._documents)] = [
                self._source_line_text(model_index, row_index)
                for model_index in range(len(self._documents))
            ]
            state = self._fusion_states[row_index]
            selected = state.selected_index
            if selected is not None and selected < len(state.candidates):
                models = state.candidates[selected].model_indices
                if models:
                    row.chosen_index = models[0]
        try:
            from engine.multi_ocr_compare import build_fused_document
            fused = build_fused_document(
                self._primary_doc,
                comparison_for_apply,
                lines,
                delete_flags=delete_flags,
                ruby_overlay_source=self._ruby_overlay_doc,
            )
            ruby_blocks = int(
                (getattr(fused.metadata, "ruby_overlay_transfer_report", {}) or {}).get("target_blocks", 0)
            )
        except Exception as exc:
            show_error_dialog(self, "应用 OCR 融合稿失败", str(exc))
            return
        if ruby_blocks:
            fused.add_log(
                "ruby_preservation",
                f"应用融合稿时保留 Ruby 结构覆盖：{ruby_blocks} 个文字块",
                ruby_blocks,
            )
        self.doc_applied.emit(fused)
        self._summary.setText("已将当前逐句裁决稿应用到工作流；源 OCR 和候选卡仍保留在本页。")
        QMessageBox.information(
            self, "OCR 融合稿已应用",
            "融合稿已进入 Formatter、文本替换、文本对比和 EPUB 工作流。\n"
            "每个候选框中的人工修改均已写入，模型原始结果没有被覆盖。",
        )


