class OCRProofreadImageLabel(QLabel):
    """Aspect-ratio image viewer with coalesced high-quality rescaling."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._source_pixmap: QPixmap | None = None
        self._last_scaled_size = QSize()
        self._smooth_scale_timer = QTimer(self)
        self._smooth_scale_timer.setSingleShot(True)
        self._smooth_scale_timer.setInterval(70)
        self._smooth_scale_timer.timeout.connect(lambda: self._rescale(smooth=True))
        self.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)
        self.setMinimumSize(420, 320)
        self.setWordWrap(True)
        self.setStyleSheet(LIGHT_IMAGE_PREVIEW_STYLE)
        self.setText("完成 OCR 后，右侧显示当前句对应的单列或多列原图。")

    def set_image_path(self, path: str) -> bool:
        pixmap = QPixmap(str(path or ""))
        if pixmap.isNull():
            self._source_pixmap = None
            self.clear()
            self.setText("当前句没有可用的原图裁片。")
            return False
        self._source_pixmap = pixmap
        self._last_scaled_size = QSize()
        self.setText("")
        # Fast first paint keeps next/previous navigation immediate. One smooth
        # pass follows after resize/navigation events have settled.
        self._rescale(smooth=False)
        self._smooth_scale_timer.start()
        return True

    def clear_image(self, message: str = "尚未载入图文校对内容") -> None:
        self._smooth_scale_timer.stop()
        self._source_pixmap = None
        self._last_scaled_size = QSize()
        self.clear()
        self.setText(message)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if self._source_pixmap is None or self._source_pixmap.isNull():
            return
        self._rescale(smooth=False)
        self._smooth_scale_timer.start()

    def _rescale(self, *, smooth: bool = False) -> None:
        if self._source_pixmap is None or self._source_pixmap.isNull():
            return
        target = self.size()
        if target.width() <= 1 or target.height() <= 1:
            return
        if smooth and target == self._last_scaled_size:
            # The fast preview used the same dimensions; replace it once with a
            # smooth version. Repeated resize events are coalesced by the timer.
            pass
        mode = Qt.SmoothTransformation if smooth else Qt.FastTransformation
        self.setPixmap(self._source_pixmap.scaled(target, Qt.KeepAspectRatio, mode))
        self._last_scaled_size = QSize(target)


class OCRVerticalColumnTextWidget(QWidget):
    """Paint OCR column text vertically in the same right-to-left order as pixels."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._columns: list[str] = []
        self.setMinimumSize(180, 360)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        self.setToolTip("OCR逐列底稿：第一逻辑列显示在最右侧，与右边句图的阅读顺序一致。")

    def _layout_metrics(self):
        """Return the exact font/steps used by both sizing and painting.

        The old widget measured with the small inherited font but painted with a
        font two points larger.  Long Japanese columns were therefore clipped
        and ended with an ellipsis even though the matching image still
        contained more characters, making the two panes appear misaligned.
        """
        font = QFont(self.font())
        font.setPointSize(max(14, font.pointSize() + 2))
        metrics = QFontMetrics(font)
        char_step = max(24, metrics.height() + 5)
        column_step = max(42, metrics.horizontalAdvance("国") + 22)
        return font, metrics, char_step, column_step

    def set_columns(self, columns) -> None:
        values = [str(value or "").replace("\r", "").replace("\n", "") for value in (columns or [])]
        self._columns = values or [""]
        _font, _metrics, char_step, column_step = self._layout_metrics()
        margin_x = 12
        margin_y = 20
        width = max(180, margin_x * 2 + len(self._columns) * column_step)
        max_length = max((len(value) for value in self._columns), default=1)
        # Reserve exactly the same vertical step used by paintEvent.  The scroll
        # area can then reveal the complete physical column without wrapping,
        # truncating or moving its tail into a neighbouring visual column.
        height = max(360, margin_y * 2 + max_length * char_step + 16)
        self.setMinimumSize(QSize(width, height))
        self.resize(width, height)
        self.updateGeometry()
        self.update()

    def clear_columns(self, message: str = "完成 OCR 后显示逐列文字") -> None:
        self._columns = []
        self.setToolTip(message)
        self.setMinimumSize(180, 360)
        self.resize(180, 360)
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.fillRect(self.rect(), QColor("#FFFFFF"))
        painter.setPen(QPen(QColor("#CFE2F8"), 1))
        painter.drawRoundedRect(self.rect().adjusted(0, 0, -1, -1), 10, 10)
        if not self._columns:
            painter.setPen(QColor(MUTED))
            painter.drawText(self.rect().adjusted(18, 18, -18, -18), Qt.AlignCenter | Qt.TextWordWrap,
                             "完成 OCR 后显示逐列文字")
            return

        font, _metrics, char_step, column_step = self._layout_metrics()
        painter.setFont(font)
        margin_x = 12
        margin_y = 20

        for column_index, text in enumerate(self._columns):
            x_center = self.width() - margin_x - column_index * column_step - column_step // 2
            rect = QRect(
                x_center - column_step // 2 + 2,
                8,
                column_step - 4,
                self.height() - 16,
            )
            painter.setPen(QPen(QColor("#E4E9F0"), 1))
            painter.drawRoundedRect(rect, 6, 6)
            painter.setPen(QColor(INK))
            # Draw the complete immutable physical-column text.  Widget height
            # was sized from this same char_step, so no artificial ellipsis or
            # cross-column tail can appear.
            for char_index, char in enumerate(text):
                y = margin_y + char_index * char_step
                painter.drawText(
                    QRect(x_center - column_step // 2, y, column_step, char_step),
                    Qt.AlignHCenter | Qt.AlignTop,
                    char,
                )


class _ImageReviewFusionCandidateCard(QFrame):
    """Full-width, fully visible OCR candidate used by 图文对照."""

    chosen = Signal(int, str)

    def __init__(self, candidate_index: int, caption: str, text: str, *, confidence: float = 0.0, parent=None):
        super().__init__(parent)
        self.candidate_index = int(candidate_index)
        self.candidate_text = str(text or "")
        self.setObjectName("imageReviewFusionCard")
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Minimum)
        root = QVBoxLayout(self)
        root.setContentsMargins(10, 8, 10, 9)
        root.setSpacing(6)
        header = QHBoxLayout()
        title = str(caption or "候选")
        if confidence > 0:
            title += f" · {confidence:.0%}"
        self._caption = QLabel(title)
        self._caption.setWordWrap(True)
        self._caption.setStyleSheet("font-size:11px;font-weight:700;color:#1D4ED8;")
        header.addWidget(self._caption, 1)
        self._choose = QPushButton("使用此候选")
        self._choose.setMinimumHeight(27)
        self._choose.clicked.connect(self._emit_chosen)
        header.addWidget(self._choose)
        root.addLayout(header)
        # Use the same complete, scrollable text surface as OCR 对比 instead
        # of a compact QLabel.  Long candidates remain fully accessible and
        # selectable; no elision or tooltip-only text is used.
        self._body = QTextEdit()
        self._body.setReadOnly(True)
        self._body.setAcceptRichText(True)
        self._body.setLineWrapMode(QTextEdit.WidgetWidth)
        self._body.setMinimumSize(220, 96)
        self._body.setMaximumHeight(168)
        self._body.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.MinimumExpanding)
        self._body.setStyleSheet(
            "QTextEdit{background:#FFFFFF;border:1px solid #D7E3F4;border-radius:7px;"
            "padding:8px;font-size:13px;color:#111827;}" + EDITOR_SCROLLBAR_STYLE
        )
        root.addWidget(self._body, 1)
        self.set_candidate(candidate_index, caption, text, confidence=confidence)
        self.set_reference_text("")
        self.set_selected(False)

    def _emit_chosen(self) -> None:
        self.chosen.emit(self.candidate_index, self.candidate_text)

    def set_candidate(
        self, candidate_index: int, caption: str, text: str, *, confidence: float = 0.0
    ) -> None:
        self.candidate_index = int(candidate_index)
        self.candidate_text = str(text or "")
        title = str(caption or "候选")
        if confidence > 0:
            title += f" · {confidence:.0%}"
        self._caption.setText(title)

    @staticmethod
    def _rich_diff(text: str, marks) -> str:
        value = str(text or "")
        spans = sorted((max(0, int(a)), max(0, int(b)), str(kind)) for a, b, kind in (marks or ()))
        parts = []
        cursor = 0
        for start, end, kind in spans:
            start = min(len(value), max(cursor, start))
            end = min(len(value), max(start, end))
            if start > cursor:
                parts.append(html.escape(value[cursor:start]).replace("\n", "<br>"))
            if end > start:
                color = "#FFD1D1" if kind == "replace" else "#FFE4AD"
                foreground = "#8A1C1C" if kind == "replace" else "#7A3E00"
                parts.append(
                    f'<span style="background:{color};color:{foreground};font-weight:600;">'
                    + html.escape(value[start:end]).replace("\n", "<br>") + "</span>"
                )
                cursor = end
            else:
                parts.append('<span style="color:#D97706;font-weight:800;">▏</span>')
                cursor = start
        if cursor < len(value):
            parts.append(html.escape(value[cursor:]).replace("\n", "<br>"))
        return "".join(parts) or "<span style='color:#9CA3AF;'>（空候选）</span>"

    def set_reference_text(self, reference: str) -> None:
        try:
            from engine.ocr_compare_view_model import paired_candidate_diff_spans
            marks, _other, changes = paired_candidate_diff_spans(self.candidate_text, str(reference or ""))
        except Exception:
            marks, changes = (), 0
        self._body.setHtml(self._rich_diff(self.candidate_text, marks))
        base = self._caption.text().split(" · 差异 ", 1)[0]
        self._caption.setText(base + (f" · 差异 {changes} 处" if changes else " · 与当前稿一致"))

    def set_selected(self, selected: bool) -> None:
        if selected:
            self.setStyleSheet(
                "QFrame#imageReviewFusionCard{background:#EFF6FF;border:2px solid #2563EB;border-radius:10px;}"
            )
            self._choose.setText("✓ 当前采用")
            self._choose.setEnabled(False)
        else:
            self.setStyleSheet(
                "QFrame#imageReviewFusionCard{background:#F8FAFC;border:1px solid #CBD5E1;border-radius:10px;}"
            )
            self._choose.setText("使用此候选")
            self._choose.setEnabled(True)


class OCRImageTextReviewTab(QWidget):
    """One immutable OCR sentence per page: editable text left, source pixels right."""

    doc_applied = Signal(object)
    # Emitted after every successful sentence save.  OCRCompareTab consumes this
    # as a final-fusion decision; model OCR sources remain immutable.
    row_review_saved = Signal(object)
    # The exact MultiOcrRow index currently displayed.
    source_row_changed = Signal(int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._source_doc: UnifiedDocument | None = None
        self._review_doc: UnifiedDocument | None = None
        self._pending_source_doc: UnifiedDocument | None = None
        self._pending_source_label = ""
        self._document_load_generation = GenerationGuard()
        self._document_load_signal_refs: dict[int, WorkerSignals] = {}
        self._document_load_busy = False
        self._workspace_active = False
        self._pending_jump_source_row = -1
        self._entries = []
        self._entry_index_by_source_row: dict[int, int] = {}
        self._entry_indices_by_block: dict[int, tuple[int, ...]] = {}
        self._index = -1
        self._dirty = False
        self._reviewed_count = 0
        self._changed_count = 0
        self._source_name = ""
        self._initial_text_by_key: dict[str, str] = {}
        self._session_dirty_keys: set[str] = set()
        self._cache_dir: tempfile.TemporaryDirectory | None = None
        self._horizontal_document = False
        self._current_review_image_path = ""
        self._fusion_candidate_buttons: list[QWidget] = []
        self._fusion_candidate_grid_columns = 0
        self._candidate_reflow_pending = False
        self._image_render_generation = GenerationGuard()
        self._image_render_signal_refs: dict[int, ImageReviewRenderSignals] = {}
        # Sentence crops are serialized and latest-request-wins.  Rapid next/prev
        # navigation therefore cannot create hundreds of simultaneous PIL/PNG
        # workers that compete for CPU and disk.
        self._image_render_busy = False
        self._queued_image_request = None
        self._image_path_cache: dict[str, str] = {}
        self._image_prefetch_pending: set[str] = set()
        self._image_cache_lock = threading.Lock()
        self._pending_judgement_indices: set[int] = set()
        self._has_judgement_entries = False
        self._ocr_disagreement_indices: list[int] = []
        self._pending_ocr_sync_rows: set[int] = set()
        self._pending_ocr_compare_decisions: dict[tuple[str, ...], dict] = {}
        self._suppress_row_review_emit = False
        self._apple_handwriting_active = False
        self._apple_handwriting_target_key = ""
        self._build()
        self._clipboard = QApplication.clipboard()
        self._clipboard.dataChanged.connect(self._on_apple_handwriting_clipboard_changed)
        self._apple_handwriting_timeout = QTimer(self)
        self._apple_handwriting_timeout.setSingleShot(True)
        self._apple_handwriting_timeout.timeout.connect(self._cancel_apple_handwriting_session)

    def _build(self) -> None:
        # wrap_in_card returns a horizontal surface layout.  Treating it as the
        # page's vertical layout placed header, image splitter, candidates and
        # navigation side by side, which caused the narrow columns and huge blank
        # areas visible on wide screens.  Install one expanding vertical surface
        # inside it and let every review section consume the complete width.
        outer_root = wrap_in_card(self)
        page_surface = QWidget()
        page_surface.setObjectName("imageTextReviewSurface")
        page_surface.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        outer_root.addWidget(page_surface, 1)
        root = QVBoxLayout(page_surface)
        root.setContentsMargins(8, 8, 8, 8)
        root.setSpacing(6)

        header = QHBoxLayout()
        header.setContentsMargins(0, 0, 0, 0)
        header.setSpacing(8)
        title = QLabel("图文逐句校对")
        title.setStyleSheet(f"font-size: 16px; font-weight: 700; color: {INK};")
        header.addWidget(title)
        self._source_label = QLabel("尚未接收 OCR 结果")
        self._source_label.setStyleSheet(f"color: {MUTED}; font-size: 11px;")
        header.addWidget(self._source_label, 1)
        self._review_summary = QLabel("0 / 0")
        self._review_summary.setStyleSheet(f"color: {MUTED}; font-size: 11px; font-weight: 600;")
        header.addWidget(self._review_summary)
        root.addLayout(header)

        content_splitter = QSplitter(Qt.Horizontal)
        content_splitter.setChildrenCollapsible(False)

        left_panel = QWidget()
        self._columns_panel = left_panel
        left_panel.setMinimumWidth(250)
        left_panel.setMaximumWidth(520)
        left_layout = QVBoxLayout(left_panel)
        left_layout.setContentsMargins(0, 0, 0, 0)
        left_layout.setSpacing(5)
        columns_header = QHBoxLayout()
        columns_title = QLabel("OCR 竖列（与原图列顺序对齐）")
        columns_title.setStyleSheet("font-weight: 700; font-size: 12px;")
        columns_header.addWidget(columns_title)
        self._columns_state = QLabel("")
        self._columns_state.setStyleSheet(f"color: {MUTED}; font-size: 10px;")
        columns_header.addWidget(self._columns_state, 1)
        left_layout.addLayout(columns_header)
        self._columns_scroll = QScrollArea()
        self._columns_scroll.setWidgetResizable(False)
        self._columns_scroll.setAlignment(Qt.AlignLeft | Qt.AlignTop)
        self._columns_scroll.setFrameShape(QFrame.NoFrame)
        self._columns_scroll.setStyleSheet("QScrollArea { background: #FFFFFF; border: none; }")
        self._vertical_columns = OCRVerticalColumnTextWidget()
        self._columns_scroll.setWidget(self._vertical_columns)
        left_layout.addWidget(self._columns_scroll, 1)
        content_splitter.addWidget(left_panel)

        right_panel = QWidget()
        right_layout = QVBoxLayout(right_panel)
        right_layout.setContentsMargins(0, 0, 0, 0)
        right_layout.setSpacing(6)

        image_card = QWidget()
        image_layout = QVBoxLayout(image_card)
        image_layout.setContentsMargins(0, 0, 0, 0)
        image_layout.setSpacing(5)
        image_header = QHBoxLayout()
