#  左侧导航栏
# ══════════════════════════════════════════════════════════════════════════════

class Sidebar(QWidget):
    section_changed = Signal(int)

    # 严格对应参考图的六个主功能区。OCR 对比、图文对照、PDF 文字层与文本替换
    # 通过主功能区顶部页签融合，业务对象并未删除。
    ITEMS = list(REFERENCE_SECTION_ITEMS)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName("mainSidebar")
        self.setMinimumWidth(116)
        self.setMaximumWidth(136)
        self.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Expanding)
        self.setStyleSheet(
            f"QWidget#mainSidebar {{ background:{SIDEBAR_BG}; border-right:1px solid {BORDER}; }}"
        )

        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 20, 8, 12)
        layout.setSpacing(6)

        mod_key = "⌘" if sys.platform == "darwin" else "Ctrl+"
        self._buttons: list[QToolButton] = []
        icon_root = Path(__file__).resolve().parent / "assets" / "ui_icons"
        for icon_name, label in self.ITEMS:
            btn = QToolButton()
            btn.setText(label)
            icon_path = icon_root / f"{icon_name}.svg"
            active_icon_path = icon_root / f"{icon_name}_active.svg"
            if icon_path.exists():
                icon = QIcon()
                icon.addFile(str(icon_path), QSize(18, 18), QIcon.Mode.Normal, QIcon.State.Off)
                if active_icon_path.exists():
                    icon.addFile(str(active_icon_path), QSize(18, 18), QIcon.Mode.Normal, QIcon.State.On)
                    icon.addFile(str(active_icon_path), QSize(18, 18), QIcon.Mode.Active, QIcon.State.On)
                btn.setIcon(icon)
                btn.setIconSize(QSize(18, 18))
            btn.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
            btn.setCheckable(True)
            btn.setAutoExclusive(True)
            btn.setCursor(QCursor(Qt.PointingHandCursor))
            btn.setStyleSheet(SIDEBAR_BTN_STYLE)
            btn.setMinimumHeight(40)
            btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            idx = len(self._buttons)
            btn.setToolTip(f"{label}（{mod_key}{idx + 1}）")
            btn.clicked.connect(partial(self._on_click, idx))
            layout.addWidget(btn)
            self._buttons.append(btn)

        self._buttons[0].setChecked(True)
        layout.addStretch(1)

    def _on_click(self, idx: int):
        self.section_changed.emit(idx)

    def select(self, idx: int):
        """程序化切换时同步高亮，不重复发出页面切换信号。"""
        if 0 <= idx < len(self._buttons):
            self._buttons[idx].setChecked(True)


