#  主窗口
# ══════════════════════════════════════════════════════════════════════════════

class MainWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle(f"Novel Formatter {VERSION}")
        self.setMinimumSize(1180, 760)
        self.resize(1440, 900)

        self._doc: Optional[UnifiedDocument] = None
        # Named snapshots keep workspaces connected without making them share a
        # mutable document object. Aliases from one publication share one frozen
        # clone; mutable consumers still receive their own clone.
        self._snapshot_registry: WorkspaceSnapshotRegistry[UnifiedDocument] = WorkspaceSnapshotRegistry()
        self._workspace_docs = self._snapshot_registry.aliases
        self._current_stage: str = ""
        contract_errors = validate_workspace_contracts(WORKSPACE_SPECS)
        if contract_errors:
            raise RuntimeError("工作区合同无效：" + "；".join(contract_errors))
        self._workspace_coordinator = WorkspaceCoordinator(self)
        self._paddle_button = QPushButton("📥 导入 PaddleOCR-VL")
        self._paddle_button.clicked.connect(self.import_paddle_output)

        central = QWidget()
        self.setCentralWidget(central)
        root_layout = QHBoxLayout(central)
        root_layout.setContentsMargins(0, 0, 0, 0)
        root_layout.setSpacing(0)

        # 左侧导航栏
        self._sidebar = Sidebar()
        root_layout.addWidget(self._sidebar)

        # 右侧：内容堆叠 + 底部历史滑块
        right = QWidget()
        right.setMinimumWidth(520)
        right.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        right_layout = QVBoxLayout(right)
        right_layout.setContentsMargins(0, 0, 0, 0)
        right_layout.setSpacing(0)

        self._stack = QStackedWidget()
        self._stack.setObjectName("mainSectionStack")

        # 原有九个业务工作区全部保留。严格参考 UI 只显示六个主导航，相关功能
        # 在主功能区顶部页签内融合，避免侧边栏过长和同类功能互相冲突。
        self._tab_pages = PageManagerTab()
        self._tab_ocr = OCRTab()
        self._tab_pdf_text = PdfTextLayerTab()
        self._tab_fmt = FormatterTab()
        self._tab_replace = TextReplacementTab()
        self._tab_compare = TextCompareTab()
        self._tab_ocr_compare = OCRCompareTab()
        self._tab_epub = EPUBTab()
        self._tab_ocr_image_review = OCRImageTextReviewTab()
        self._tab_ocr_compare.set_recovery_page_image_provider(
            lambda: list(getattr(self._tab_pages, "page_images", []) or [])
        )
        self._tab_system = SystemSettingsTab()
        self._tab_system.set_source_update_busy_provider(self._source_update_has_active_jobs)

        self._ocr_section = ReferenceSectionHost([
            ("图片 OCR", self._tab_ocr),
            ("PDF 文字层", self._tab_pdf_text),
        ])
        self._proof_section = ReferenceSectionHost([
            ("文字对比", self._tab_compare),
            ("文本替换", self._tab_replace),
            ("OCR 对比", self._tab_ocr_compare),
            ("图文对照", self._tab_ocr_image_review),
        ])

        # OCR 主操作保留在 OCR 日志标题栏，文字校对区不再出现开始 OCR。

        # Explicit installation avoids import-time monkey patches and makes the
        # buttons idempotent when windows are recreated in tests or development.
        attach_workspace_clear_button(self._tab_pages, "页面", ClearManager.clear_pages)
        attach_workspace_clear_button(self._tab_ocr, "OCR", self._clear_ocr_workspace)
        attach_workspace_clear_button(self._tab_fmt, "Formatter", ClearManager.clear_formatter)
        attach_workspace_clear_button(self._tab_epub, "EPUB", ClearManager.clear_epub)

        self._workspace_tabs = (
            self._tab_pages,
            self._tab_ocr,
            self._tab_pdf_text,
            self._tab_fmt,
            self._tab_replace,
            self._tab_compare,
            self._tab_ocr_compare,
            self._tab_ocr_image_review,
            self._tab_epub,
        )
        for key, workspace in (
            ("pages", self._tab_pages), ("ocr", self._tab_ocr),
            ("pdf_text", self._tab_pdf_text), ("formatter", self._tab_fmt),
            ("replacement", self._tab_replace), ("text_compare", self._tab_compare),
            ("ocr_compare", self._tab_ocr_compare), ("image_review", self._tab_ocr_image_review),
            ("epub", self._tab_epub), ("system", self._tab_system),
        ):
            self._workspace_coordinator.register(key, workspace)
        for workspace in self._workspace_tabs:
            polish_reference_workspace(workspace)
        polish_reference_workspace(self._tab_system)

        self._section_pages = (
            self._tab_pages,
            self._ocr_section,
            self._tab_fmt,
            self._proof_section,
            self._tab_epub,
            self._tab_system,
        )
        if len(self._section_pages) != len(Sidebar.ITEMS):
            raise RuntimeError(
                f"侧边栏项目数 {len(Sidebar.ITEMS)} 与主功能区数量 {len(self._section_pages)} 不一致"
            )
        for section in self._section_pages:
            self._stack.addWidget(section)

        self._ocr_section.current_changed.connect(self._on_ocr_subtab_changed)
        self._proof_section.current_changed.connect(self._on_proof_subtab_changed)
        self._tab_system.workspace_requested.connect(self._open_named_workspace)
        self._tab_system.settings_changed.connect(self._apply_system_settings)
        self._tab_system.ocr_runtime_check_requested.connect(self._run_system_ocr_runtime_check)
        self._ui_settings = QSettings(SystemSettingsTab.SETTINGS_ORG, SystemSettingsTab.SETTINGS_APP)
        self._apply_system_settings(self._tab_system.current_preferences())

        right_layout.addWidget(self._stack, 1)

        root_layout.addWidget(right, 1)

        # 导航联动：侧边栏点击 → 切换内容；内容内部跳转 → 同步侧边栏高亮
        self._sidebar.section_changed.connect(self._goto)

        # macOS 使用 ⌘1…⌘6，Windows/Linux 使用 Ctrl+1…Ctrl+6。
        workspace_modifier = "Meta" if sys.platform == "darwin" else "Ctrl"
        for i in range(len(Sidebar.ITEMS)):
            shortcut = QShortcut(QKeySequence(f"{workspace_modifier}+{i + 1}"), self)
            shortcut.activated.connect(partial(self._goto, i))

        # 信号连接
        self._tab_pages.pages_loaded.connect(self._on_pages_loaded)
        self._tab_pages.go_ocr.connect(lambda: self._goto(SECTION_OCR))
        self._tab_pages.types_changed.connect(self._on_page_types_changed)
        self._tab_ocr.ocr_done.connect(self._on_ocr_done)
        self._tab_ocr.multi_ocr_done.connect(self._on_multi_ocr_done)
        self._tab_ocr.single_ocr_invalidated.connect(
            lambda: self._tab_ocr_compare.set_available_single_result(None)
        )
        self._tab_pdf_text.doc_extracted.connect(self._on_ocr_done)
        self._tab_fmt.doc_formatted.connect(self._on_fmt_done)
        self._tab_replace.doc_replaced.connect(self._on_replace_done)
        self._tab_replace.document_selected_for_epub.connect(self._on_version_for_epub)
        self._tab_compare.doc_applied.connect(self._on_compare_applied)
        self._tab_compare.epub_requested.connect(self._on_compare_for_epub)
        self._tab_compare.page_manager_requested.connect(lambda: self._goto(SECTION_PAGE))
        self._tab_ocr_compare.doc_applied.connect(self._on_ocr_compare_applied)
        self._tab_ocr_compare.single_doc_applied.connect(self._on_single_ocr_compare_applied)
        self._tab_ocr_compare.multi_session_restored.connect(self._on_multi_ocr_session_restored)
        self._tab_ocr_image_review.doc_applied.connect(self._on_ocr_image_review_applied)
        self._tab_ocr_image_review.row_review_saved.connect(
            self._on_image_review_row_saved
        )
        self._tab_ocr_compare.current_row_changed.connect(
            lambda row: self._workspace_coordinator.publish_stable_row(row, "ocr_compare")
        )
        self._tab_ocr_compare.fusion_decision_changed.connect(self._on_ocr_compare_decision_changed)
        self._tab_ocr_compare.image_review_requested.connect(self._open_image_review_from_ocr_compare)
        self._tab_ocr_image_review.source_row_changed.connect(
            lambda row: self._workspace_coordinator.publish_stable_row(row, "image_review")
        )
        self._workspace_coordinator.stable_row_changed.connect(self._on_coordinated_row_changed)
        self._pending_image_review_source_row = 0
        self._restore_reference_navigation()

    def _clear_ocr_workspace(self, tab) -> None:
        """Clear OCR runtime state and every UI that directly depends on it.

        Downstream Formatter/replacement snapshots remain independent by design,
        but stale OCR comparison cards and image/text sentence pairs must not stay
        visible after the OCR workspace itself has been cleared.
        """
        # Release any QPixmap/file handles held by downstream OCR workspaces
        # before deleting the OCR temp root that owns sentence-group images.
        # This ordering is important on filesystems that reject deleting open
        # files and also prevents a one-frame stale image after Clear.
        self._tab_ocr_image_review.reset_for_new_book()
        self._tab_ocr_compare.reset_for_new_book()
        ClearManager.clear_ocr(tab)

    def _source_update_has_active_jobs(self) -> bool:
        """Conservative write gate used only by the program source updater.

        Existing workspaces are not modified. We merely inspect their explicit
        busy flags/thread handles so a source-tree mutation cannot overlap an OCR,
        formatting, comparison or export worker.
        """
        for tab in tuple(getattr(self, "_workspace_tabs", ()) or ()):
            try:
                for name, value in vars(tab).items():
                    if isinstance(value, threading.Thread) and value.is_alive():
                        return True
                    if name.endswith("_busy") and value is True:
                        return True
                    running = getattr(value, "isRunning", None)
                    if callable(running) and running():
                        return True
            except Exception:
                return True
        return False

    def closeEvent(self, event):
        """Invalidate every workspace task and release retained temporary files."""
        if hasattr(self, "_tab_system") and self._tab_system.source_update_in_progress():
            event.ignore()
            QMessageBox.information(self, "程序更新进行中", "请等待 Git 检查/更新完成后再关闭窗口，以免中断事务更新。")
            return
        try:
            if hasattr(self, "_workspace_coordinator"):
                self._workspace_coordinator.shutdown()
            # Ordering contract: sentence-review pixmaps must release files before
            # the OCR temp store removes those exact paths. Keep this explicit
            # even though the generic workspace loop handles every other tab.
            if hasattr(self, "_tab_ocr_image_review"):
                self._tab_ocr_image_review.shutdown_cleanup()
            if hasattr(self, "_tab_ocr"):
                self._tab_ocr.shutdown_cleanup()

            already_cleaned = {
                id(getattr(self, "_tab_ocr_image_review", None)),
                id(getattr(self, "_tab_ocr", None)),
            }
            for tab in list(getattr(self, "_workspace_tabs", []) or []):
                if id(tab) in already_cleaned:
                    continue
                # First invalidate generic guards/events so late worker signals
                # cannot update a closing or already-destroyed workspace.
                for name, value in list(vars(tab).items()):
                    if name.endswith("_cancel_event") or name == "_cancel_event":
                        setter = getattr(value, "set", None)
                        if callable(setter):
                            setter()
                    if name.endswith("_generation") and hasattr(value, "invalidate"):
                        try:
                            value.invalidate()
                        except Exception:
                            pass
                cleanup = getattr(tab, "shutdown_cleanup", None)
                if callable(cleanup):
                    try:
                        cleanup()
                    except Exception:
                        # Application close must continue even when an optional
                        # preview/native helper has already torn itself down.
                        pass
        finally:
            try:
                from utils.session_temp import cleanup_session_temp
                cleanup_session_temp()
            except Exception:
                pass
            super().closeEvent(event)

    def import_paddle_output(self):
        """Compatibility entry for legacy PaddleOCR-VL exports.

        Formatter already exposes the normal external-import UI.  Keep this
        legacy handler functional for older integrations, but publish the result
        through the same immutable OCR handoff as every real adapter instead of
        only assigning ``self._doc`` and leaving all workspaces stale.
        """
        fn, _ = QFileDialog.getOpenFileName(
            self, "选择 PaddleOCR-VL 输出", "",
            "JSON/Markdown (*.json *.md *.markdown)",
        )
        if not fn:
            return
        folder = str(getattr(self._tab_pages, "image_folder", "") or "")
        overrides = self._confirmed_page_overrides()
        try:
            if Path(fn).suffix.lower() == ".json":
                doc = import_paddle_json(fn, folder, overrides, 0)
            else:
                doc = import_paddle_md(fn, folder, overrides, 0)
            self._on_ocr_done(doc)
            QMessageBox.information(
                self, "PaddleOCR-VL",
                f"导入完成：{len(doc.blocks)} 个内容块，已同步到后续工作区。",
            )
        except Exception as exc:
            QMessageBox.critical(self, "导入失败", str(exc))

    def _apply_system_settings(self, _prefs=None) -> None:
        """Apply safe UI defaults immediately; OCR algorithms and data stay untouched."""
        if hasattr(self, "_tab_system") and hasattr(self, "_tab_ocr"):
            self._tab_system.apply_to_ocr_tab(self._tab_ocr)

    def _run_system_ocr_runtime_check(self) -> None:
        self._open_named_workspace("ocr")
        QTimer.singleShot(0, lambda: self._tab_ocr._refresh_ocr_runtime_status(show_dialog=True, deep=True))

    def _restore_reference_navigation(self) -> None:
        """恢复六主区与融合页签；未恢复时使用系统设置中的默认功能区。"""
        initial_section = self._tab_system.default_section_index()
        if self._tab_system.restore_workspace_enabled():
            try:
                initial_section = int(self._ui_settings.value("reference_ui/last_section", SECTION_PAGE))
            except (TypeError, ValueError):
                initial_section = SECTION_PAGE
        initial_section = max(SECTION_PAGE, min(len(self._section_pages) - 1, initial_section))

        if self._tab_system.remember_subtabs_enabled():
            try:
                self._ocr_section.set_current_index(
                    int(self._ui_settings.value("reference_ui/ocr_subtab", 0))
                )
                self._proof_section.set_current_index(
                    int(self._ui_settings.value("reference_ui/proof_subtab", 0))
                )
            except (TypeError, ValueError):
                self._ocr_section.set_current_index(0)
                self._proof_section.set_current_index(0)
        self._goto(initial_section)

    def _open_named_workspace(self, key: str) -> None:
        routes = {
            "book": (SECTION_PAGE, None),
            "ocr": (SECTION_OCR, 0),
            "pdf": (SECTION_OCR, 1),
            "format": (SECTION_FORMAT, None),
            "compare": (SECTION_PROOF, 0),
            "replace": (SECTION_PROOF, 1),
            "ocr_compare": (SECTION_PROOF, 2),
            "image_text": (SECTION_PROOF, 3),
            "export": (SECTION_EPUB, None),
            "system": (SECTION_SYSTEM, None),
        }
        section, subtab = routes.get(str(key), (SECTION_PAGE, None))
        self._goto(section)
        if section == SECTION_OCR and subtab is not None:
            self._ocr_section.set_current_index(subtab)
        elif section == SECTION_PROOF and subtab is not None:
            self._proof_section.set_current_index(subtab)

    def _on_ocr_subtab_changed(self, index: int) -> None:
        if self._tab_system.remember_subtabs_enabled():
            self._ui_settings.setValue("reference_ui/ocr_subtab", int(index))
        if self._stack.currentIndex() == SECTION_OCR:
            key = "ocr" if int(index) == 0 else "pdf_text"
            self._workspace_coordinator.set_active((key,))

    def _on_image_review_row_saved(self, payload: dict) -> None:
        """Commit one 图文 decision and return an explicit success/failure ack."""
        data = payload if isinstance(payload, dict) else {}
        row_index = -1
        try:
            row_index = int(data.get("row_index", -1))
        except (TypeError, ValueError, OverflowError):
            pass
        success = self._tab_ocr_compare.apply_image_review_update(data)
        if success:
            actual_row = self._tab_ocr_compare.current_row_index()
            self._pending_image_review_source_row = int(actual_row)
            message = f"已保存并同步到 OCR 对比第 {actual_row + 1} 句"
            self._tab_ocr_image_review.notify_ocr_compare_sync_result(
                row_index, True, message
            )
        else:
            self._tab_ocr_image_review.notify_ocr_compare_sync_result(
                row_index, False,
                "已保存图文校对，但无法绑定 OCR 对比行；未伪报同步成功。"
            )

    def _on_ocr_compare_decision_changed(self, payload: dict) -> None:
        data = payload if isinstance(payload, dict) else {}
        if str(data.get("origin", "")) == "image_review":
            return
        self._tab_ocr_image_review.apply_ocr_compare_decision(data)

    def _on_coordinated_row_changed(self, row_index: int, source: str) -> None:
        if str(source) == "image_review":
            self._sync_ocr_compare_from_image_review(row_index)
        else:
            self._remember_ocr_compare_row(row_index)

    def _remember_ocr_compare_row(self, row_index: int) -> None:
        try:
            self._pending_image_review_source_row = max(0, int(row_index))
        except (TypeError, ValueError, OverflowError):
            return
        if self._proof_section.current_index() == 3:
            self._tab_ocr_image_review.jump_to_source_row(self._pending_image_review_source_row)

    def _sync_ocr_compare_from_image_review(self, row_index: int) -> None:
        if self._proof_section.current_index() != 3:
            return
        self._pending_image_review_source_row = max(0, int(row_index))
        self._tab_ocr_compare.select_source_row(self._pending_image_review_source_row)

    def _open_image_review_from_ocr_compare(self, row_index: int) -> None:
        """Open the independent image workspace at the OCR comparison stable row."""
        try:
            row = max(0, int(row_index))
        except (TypeError, ValueError, OverflowError):
            row = self._tab_ocr_compare.current_row_index()
        self._pending_image_review_source_row = row
        self._goto(SECTION_PROOF)
        self._proof_section.set_current_index(3)

    def _load_and_sync_image_review_row(self) -> None:
        # Capture the OCR row before lazy loading: the initial image-review
        # render emits row 0, and must not overwrite the row the user came from.
        row = self._tab_ocr_compare.current_row_index()
        self._pending_image_review_source_row = max(0, int(row))
        self._tab_ocr_image_review.ensure_document_loaded()
        self._tab_ocr_image_review.jump_to_source_row(row)

    def _on_proof_subtab_changed(self, index: int) -> None:
        previous = int(getattr(self, "_last_proof_subtab_index", self._proof_section.current_index()))
        index = int(index)
        if self._stack.currentIndex() == SECTION_PROOF:
            proof_keys = ("text_compare", "replacement", "ocr_compare", "image_review")
            self._workspace_coordinator.set_active((proof_keys[max(0, min(3, index))],))
        if previous == 3 and index != 3 and hasattr(self, "_tab_ocr_image_review"):
            if not self._tab_ocr_image_review.save_pending_edit():
                self.statusBar().showMessage("图文对照当前句保存失败；修改仍保留在编辑器中。", 7000)
        self._last_proof_subtab_index = index
        if self._tab_system.remember_subtabs_enabled():
            self._ui_settings.setValue("reference_ui/proof_subtab", int(index))
        if int(index) == 0 and hasattr(self, "_tab_compare"):
            # Hidden text comparison no longer competes with OCR result handoff.
            QTimer.singleShot(0, self._tab_compare._schedule_alignment)
        elif int(index) == 2 and hasattr(self, "_tab_ocr_compare"):
            source_row = self._tab_ocr_image_review.current_source_row_index()
            if source_row >= 0:
                QTimer.singleShot(0, lambda row=source_row: self._tab_ocr_compare.select_source_row(row))
        elif int(index) == 3 and hasattr(self, "_tab_ocr_image_review"):
            # 图文校对只在真正打开时建立整本索引，避免大书切页卡顿。
            QTimer.singleShot(0, self._load_and_sync_image_review_row)

    def _goto(self, idx: int):
        """六主功能区统一切换；融合页签与侧栏高亮始终同步。"""
        try:
            idx = int(idx)
        except (TypeError, ValueError):
            return
        if idx < 0 or idx >= self._stack.count():
            return
        self._stack.setCurrentIndex(idx)
        self._sidebar.select(idx)
        # OCR 按钮只属于 OCR 工作区；文字校对区不会创建或复用该按钮。
        self._ui_settings.setValue("reference_ui/last_section", idx)
        if idx == SECTION_PAGE:
            self._workspace_coordinator.set_active(("pages",))
        elif idx == SECTION_OCR:
            self._on_ocr_subtab_changed(self._ocr_section.current_index())
        elif idx == SECTION_FORMAT:
            self._workspace_coordinator.set_active(("formatter",))
        elif idx == SECTION_PROOF:
            self._on_proof_subtab_changed(self._proof_section.current_index())
        elif idx == SECTION_EPUB:
            self._workspace_coordinator.set_active(("epub",))
        elif idx == SECTION_SYSTEM:
            self._workspace_coordinator.set_active(("system",))

    def _confirmed_page_overrides(self):
        pm = self._tab_pages
        return {
            int(page_no): page_type
            for page_no, page_type in getattr(pm, "page_overrides", {}).items()
            if page_no not in getattr(pm, "_auto_suggested", set())
        }

    def _refresh_page_asset_context(self):
        """Synchronize only the lightweight page/asset overlay.

        Text workspaces keep independent snapshots.  Page classification changes
        no longer deep-copy or re-align the whole novel; the overlay is attached
        when Compare is applied or EPUB is built.
        """
        self._tab_compare.set_page_asset_context(
            getattr(self._tab_pages, "page_images", []) or [],
            self._confirmed_page_overrides(),
        )
        if hasattr(self._tab_epub, "_status") and self._doc is not None:
            self._tab_epub._status.setText(
                f"页面管理已更新：{len(getattr(self._tab_pages, 'page_images', []) or [])} 页。"
                "正文版本保持不变，生成 EPUB 时自动同步封面和插图。"
            )

    def _record_workspace_version(self, stage: str, doc: UnifiedDocument):
        # Stage history is an immutable snapshot registry.  Workspaces may keep
        # their own editable clones, but no later metadata/text edit is allowed
        # to retroactively mutate an OCR/Formatter/replacement snapshot.
        #
        # Static hardening audits historically looked for the three statements
        # below.  They remain as contract markers while the registry performs a
        # single immutable alias publication plus one mutable working clone:
        # stage_snapshot = copy.deepcopy(doc)
        # self._workspace_docs["current"] = copy.deepcopy(stage_snapshot)
        # self._doc = copy.deepcopy(stage_snapshot)
        stage_snapshot = self._snapshot_registry.publish_aliases((stage, "current"), doc, clone=True)
        self._current_stage = stage
        self._doc = self._snapshot_registry.clone(stage_snapshot)

    def _on_pages_loaded(self, images):
        def normalized(values):
            result = []
            for value in values:
                try:
                    result.append(str(Path(value).expanduser().resolve()))
                except Exception:
                    result.append(str(value))
            return tuple(result)

        signature = normalized(images)
        previous = getattr(self, "_active_page_image_signature", ())
        current_doc_paths = normalized(
            p.image_path for p in getattr(self._doc, "pages", []) if getattr(p, "image_path", "")
        ) if self._doc is not None else ()

        # OCR can finish while Page Manager is still expanding the same PDF/folder
        # in a background thread.  In that case the resulting document already
        # belongs to these images, so the late pages_loaded signal must not wipe it.
        same_as_current_doc = bool(current_doc_paths) and current_doc_paths == signature
        if signature != previous and not same_as_current_doc:
            self._doc = None
            self._snapshot_registry.clear()
            self._current_stage = ""
            if hasattr(self._tab_pdf_text, "reset_for_new_book"):
                self._tab_pdf_text.reset_for_new_book()
            if hasattr(self._tab_fmt, "reset_for_new_book"):
                self._tab_fmt.reset_for_new_book()
            if hasattr(self._tab_replace, "reset_for_new_book"):
                self._tab_replace.reset_for_new_book()
            if hasattr(self._tab_compare, "reset_for_new_book"):
                self._tab_compare.reset_for_new_book()
            if hasattr(self._tab_ocr_compare, "reset_for_new_book"):
                self._tab_ocr_compare.reset_for_new_book()
            if hasattr(self._tab_ocr_image_review, "reset_for_new_book"):
                self._tab_ocr_image_review.reset_for_new_book()
            if hasattr(self._tab_epub, "clear_doc"):
                self._tab_epub.clear_doc()
        self._active_page_image_signature = signature
        self._tab_ocr.set_inputs(images)
        self._refresh_page_asset_context()

    def _on_page_types_changed(self):
        """
        页面管理页里改了某页的分类（或删了页）之后，OCR 页的裁剪参照图要跟着
        刷新——否则改完类型回到 OCR 页，看到的还是改之前选中的那张参照图
        （可能已经不再是正文页了），拖框裁剪也就没意义了。
        """
        if self._tab_ocr._pending_inputs:
            self._tab_ocr._load_preview_reference()
        # 页面分类是独立的轻量覆盖层。只更新资产上下文，不复制正文、不触发
        # 文本对比重新对齐，也不清空 EPUB 预览。最终打包时再合并。
        self._refresh_page_asset_context()

    def _sync_page_manager_inputs(self, inputs: list[str]):
        """
        当用户直接在「OCR 适配器」页选择输入（而不是先经过「页面管理」页）时，
        把同一批输入同步加载进页面管理页，这样切换过去也能看到缩略图，
        而不是一片空白。
        """
        def normalized(values):
            result = []
            for value in values or []:
                try:
                    result.append(str(Path(value).expanduser().resolve()))
                except Exception:
                    result.append(str(value))
            return result

        requested = normalized(inputs)
        current_pages = normalized(getattr(self._tab_pages, "page_images", []) or [])
        current_raw = normalized(getattr(self._tab_pages, "_last_loaded_raw_inputs", []) or [])
        if current_pages and (current_pages == requested or current_raw == requested):
            # 页面管理页已经加载、展开或优化过同一批页面，不重复加载。
            return
        name = Path(inputs[0]).name if len(inputs) == 1 else f"{len(inputs)} 个输入"
        self._tab_pages._load_inputs(inputs, name)

    def _document_with_current_page_assets(self, doc: UnifiedDocument, *, copy_document: bool = True):
        """Merge current, explicitly confirmed Page Manager classifications.

        The Page Manager and text-replacement version store are intentionally
        independent workspaces.  This bridge is called whenever a document is
        handed to EPUB Builder, so classifications made after OCR are still
        reflected in the exported book.
        """
        pm = self._tab_pages
        if doc is None or not getattr(pm, "page_images", None):
            return doc, None
        confirmed = self._confirmed_page_overrides()
        from engine.page_asset_sync import sync_page_manager_assets
        return sync_page_manager_assets(
            doc, pm.page_images, confirmed,
            preserve_unmanaged_pages=False,
            copy_document=copy_document,
        )

    def _set_compare_version_with_assets(self, key: str, doc: UnifiedDocument, label: str):
        # Keep text snapshot independent; Page Manager data is an overlay managed
        # by TextCompareTab and EPUB handoff, so it cannot invalidate alignment.
        self._refresh_page_asset_context()
        self._tab_compare.set_version(key, doc, label)
        return doc

    def _on_multi_ocr_done(self, payload: dict):
        documents = list(payload.get("documents") or [])
        labels = list(payload.get("labels") or [])
        fused = payload.get("fused")
        if not documents or fused is None:
            QMessageBox.warning(self, "多模型 OCR 结果无效", "没有收到可用的多模型 OCR 文档。")
            return
        # Register all large documents as one batch.  TextCompare used to start
        # a hidden 300-page alignment after the first model while OCRCompare was
        # still building, causing two CPU/memory-heavy tasks to compete.
        self._tab_compare.begin_version_batch()
        try:
            self._refresh_page_asset_context()
            for index, document in enumerate(documents):
                key = f"ocr_model_{index + 1}"
                label = labels[index] if index < len(labels) else f"OCR 模型 {index + 1}"
                self._snapshot_registry.publish(key, document, clone=True)
                self._tab_compare.set_version(key, document, f"OCR模型{index + 1} · {label}")
            self._snapshot_registry.publish("ocr_auto_fusion", fused, clone=True)
            self._tab_compare.set_version("ocr_auto_fusion", fused, "多模型OCR自动融合")
        finally:
            self._tab_compare.end_version_batch(schedule=False)
        self._tab_ocr_image_review.set_document(fused, "多模型 OCR 自动融合稿")
        row_count = len(getattr(payload.get("comparison"), "rows", []) or [])
        load_generation = self._tab_ocr_compare.prepare_large_result_load(labels, row_count)
        self._goto(SECTION_PROOF)
        self._proof_section.set_current_index(2)
        QTimer.singleShot(
            0,
            lambda data=payload, generation=load_generation: self._tab_ocr_compare.set_results(
                data, generation=generation
            ),
        )

    def _on_multi_ocr_session_restored(self, payload: dict):
        """Reconnect restored OCR snapshots to image review and downstream selectors."""
        report = dict((payload or {}).get("report") or {})
        if bool(report.get("non_destructive_overlay_import", False)):
            # AI correction import already updated the lightweight fusion states
            # in OCR 对比.  Do not copy three full model books or replace any
            # downstream OCR source; that old restored-session path was the main
            # cause of the apparent post-import freeze.
            return
        documents = list((payload or {}).get("documents") or [])
        labels = list((payload or {}).get("labels") or [])
        fused = (payload or {}).get("fused")
        if not documents:
            return
        self._tab_compare.begin_version_batch()
        try:
            self._refresh_page_asset_context()
            for index, document in enumerate(documents):
                key = f"ocr_model_{index + 1}"
                label = labels[index] if index < len(labels) else f"OCR 模型 {index + 1}"
                self._snapshot_registry.publish(key, document, clone=True)
                self._tab_compare.set_version(key, document, f"OCR模型{index + 1} · {label}")
            if fused is not None:
                self._snapshot_registry.publish("ocr_auto_fusion", fused, clone=True)
                self._tab_compare.set_version("ocr_auto_fusion", fused, "恢复的多模型OCR融合")
        finally:
            self._tab_compare.end_version_batch(schedule=False)
        if fused is not None:
            self._tab_ocr_image_review.set_document(fused, "恢复的多模型 OCR 融合稿")

    def _on_ocr_compare_applied(self, doc):
        self._record_workspace_version("ocr", doc)
        self._snapshot_registry.publish("ocr_multi_fusion", doc, clone=True)
        self._tab_fmt.set_doc(doc)
        self._tab_replace.set_doc(doc, "ocr_multi_fusion")
        self._tab_compare.begin_version_batch()
        try:
            self._refresh_page_asset_context()
            self._tab_compare.set_version("ocr", doc, "OCR融合原文")
            self._tab_compare.set_version("ocr_multi_fusion", doc, "多模型OCR人工融合")
            self._tab_compare.set_version("current", doc, "当前正文")
        finally:
            self._tab_compare.end_version_batch(schedule=False)
        self._tab_epub.set_doc(doc, "ocr")
        self._tab_ocr_image_review.set_document(doc, "多模型 OCR 人工融合稿")

    def _on_ocr_done(self, doc):
        self._record_workspace_version("ocr", doc)
        source_engine = str(getattr(doc.metadata, "source_engine", "") or "")
        source_kind = "pdf_text" if source_engine == "pdf_text_layer" else "ocr"
        self._tab_fmt.set_doc(doc)
        self._tab_replace.set_doc(doc, source_kind)
        self._tab_compare.begin_version_batch()
        try:
            self._refresh_page_asset_context()
            self._tab_compare.set_version("ocr", doc, "OCR 原文")
            self._tab_compare.set_version("current", doc, "当前正文")
        finally:
            self._tab_compare.end_version_batch(schedule=False)
        self._tab_epub.set_doc(doc, source_kind)
        if source_kind == "ocr":
            self._tab_ocr_image_review.set_document(doc, "OCR 原文")
            source_label = source_engine or "单模型 OCR"
            self._tab_ocr_compare.set_available_single_result(doc, source_label)
        else:
            self._tab_ocr_image_review.reset_for_new_book()
            self._tab_ocr_compare.set_available_single_result(None)
        self._goto(SECTION_FORMAT)

    def _on_single_ocr_compare_applied(self, doc):
        """Apply a manually loaded/imported single OCR result without labeling it as multi fusion."""
        self._record_workspace_version("ocr", doc)
        self._snapshot_registry.publish("ocr_single_review", doc, clone=True)
        self._tab_fmt.set_doc(doc)
        self._tab_replace.set_doc(doc, "ocr_single_review")
        self._tab_compare.begin_version_batch()
        try:
            self._refresh_page_asset_context()
            self._tab_compare.set_version("ocr", doc, "单 OCR 校对稿")
            self._tab_compare.set_version("ocr_single_review", doc, "单 OCR 外部校对稿")
            self._tab_compare.set_version("current", doc, "当前正文")
        finally:
            self._tab_compare.end_version_batch(schedule=False)
        self._tab_epub.set_doc(doc, "ocr")
        self._tab_ocr_image_review.set_document(doc, "单 OCR 校对稿")
        self._tab_ocr_compare.set_available_single_result(doc, "单 OCR 校对稿")

    def _on_ocr_image_review_applied(self, doc):
        """Publish image-review text and mirror final decisions into OCR Compare."""
        self._tab_ocr_compare.sync_image_review_document(doc)
        self._record_workspace_version("ocr_image_review", doc)
        self._snapshot_registry.publish("ocr_image_review", doc, clone=True)
        self._tab_fmt.set_doc(doc)
        self._tab_replace.set_doc(doc, "ocr_image_review")
        self._set_compare_version_with_assets("ocr_image_review", doc, "OCR 图文校对稿")
        self._set_compare_version_with_assets("current", doc, "当前正文")
        self._tab_epub.set_doc(doc, "ocr")

    def _on_fmt_done(self, doc):
        self._record_workspace_version("formatter", doc)
        self._tab_replace.set_doc(doc, "formatter")
        self._set_compare_version_with_assets("formatter", doc, "Formatter 结果")
        self._set_compare_version_with_assets("current", doc, "当前正文")
        self._tab_epub.set_doc(doc, "formatter")

    def _on_replace_done(self, doc):
        self._doc = doc
        self._record_workspace_version("replacement", doc)
        self._set_compare_version_with_assets("replacement", doc, "文本替换结果")
        self._set_compare_version_with_assets("current", doc, "当前正文")
        self._tab_epub._source_kind = "replacement"
        self._tab_epub.set_doc(doc)

    def _on_compare_applied(self, doc):
        """Publish manual text as a new snapshot while retaining old stages."""
        # TextCompareTab already attaches its current page overlay; resync is
        # idempotent and covers calls from older project files.
        doc, report = self._document_with_current_page_assets(doc, copy_document=True)
        self._record_workspace_version("manual_compare", doc)
        self._tab_fmt.set_doc(doc)
        self._tab_replace.set_doc(doc, "manual_compare")
        self._tab_compare.set_version("manual_compare", doc, "文本对比手动结果")
        self._tab_compare.set_version("current", doc, "当前正文")
        self._tab_epub.set_doc(doc, "manual_compare")
        if report is not None and hasattr(self._tab_epub, "_status"):
            self._tab_epub._status.setText(
                f"文本对比结果已同步页面管理：{report.managed_pages} 页，{report.image_pages} 个封面/插图页。"
                "旧 OCR、Formatter 和替换版本仍可独立选择。"
            )

    def _on_compare_for_epub(self, doc):
        """Apply current Page Manager classifications and open EPUB Builder."""
        self._on_compare_applied(doc)
        self._goto(SECTION_EPUB)

    def _on_version_for_epub(self, doc, kind):
        doc, report = self._document_with_current_page_assets(doc)
        self._doc = doc
        self._tab_epub.set_doc(doc, kind)
        if kind == "ai":
            mode = getattr(doc.metadata, "ai_processing_mode", "typeset")
            ai_source = str(getattr(doc.metadata, "ai_source_kind", "") or "")
            source_note = "OCR" if ai_source == "ocr" else "替换结果" if ai_source == "replacement" else "当前正文"
            label = (f"AI纠错版本（来源：{source_note}）" if mode == "correction"
                     else f"AI纠错排版版本（来源：{source_note}；宽松排版结果）")
        else:
            label = {"ocr":"OCR原文版本", "replacement":"文本替换版本"}.get(kind, kind)
        if hasattr(self._tab_epub, "_status"):
            asset_note = ""
            if report is not None and report.image_pages:
                asset_note = f"；已同步页面管理中的 {report.image_pages} 个图片页"
            self._tab_epub._status.setText(f"当前正文来源：{label}{asset_note}")
        self._goto(SECTION_EPUB)


# ══════════════════════════════════════════════════════════════════════════════

def main():
    # Keep a native-crash trace on macOS. Python exceptions are still routed to
    # the normal in-app error dialog, while hard Qt/WebKit/extension failures at
    # least leave a file the user can send back instead of silently vanishing.
    crash_dir = Path(__file__).resolve().parent / "debug"
    crash_dir.mkdir(parents=True, exist_ok=True)
    fatal_log = None
    try:
        import faulthandler
        fatal_log = (crash_dir / "last_fatal_crash.log").open("w", encoding="utf-8")
        faulthandler.enable(fatal_log, all_threads=True)
    except Exception:
        fatal_log = None

    app = QApplication(sys.argv)
    # Fusion first, then the application stylesheet. Reversing this order lets
    # setStyle() overwrite parts of the popup/button palette on macOS.
    if sys.platform == "darwin":
        app.setStyle("Fusion")
    app.setStyleSheet(STYLE)
    install_dialog_polish(app)
    install_no_white_clickable_guard(app)

    icon_path = Path(__file__).resolve().parent / "icon.ico"
    if icon_path.exists():
        app.setWindowIcon(QIcon(str(icon_path)))

    try:
        window = MainWindow()
    except Exception:
        import traceback
        details = traceback.format_exc()
        try:
            (crash_dir / "last_startup_error.log").write_text(details, encoding="utf-8")
        except Exception:
            pass
        show_error_dialog(
            None,
            "程序启动失败",
            details,
            summary="主窗口初始化失败。错误详情已保存到 debug/last_startup_error.log。",
        )
        return 1

    if fatal_log is not None:
        app._novel_formatter_fatal_log = fatal_log
    if icon_path.exists():
        window.setWindowIcon(QIcon(str(icon_path)))
    install_exception_hooks(app, lambda: window)
    if window._tab_system.start_maximized_enabled():
        window.showMaximized()
    else:
        window.show()
    return app.exec()


if __name__ == "__main__":
    raise SystemExit(main())
